.monitoreo_sheets_status_columns <- function(header) {
  grep("estado|clasificacion|clasificación|prioridad|severidad|tipo|sexo|edad completa|ump.*estado", header, ignore.case = TRUE)
}

.monitoreo_sheets_assignment_slot_columns <- function(header) {
  grep("^Encuesta [0-9]+$", header)
}

.monitoreo_sheets_progress_columns <- function(header) {
  grep("%|avance", header, ignore.case = TRUE)
}

.monitoreo_sheets_integer_columns <- function(header) {
  grep("validas|válidas|efectivas|encuestas|meta|referencia|pendientes|no iniciadas|cuota|cantidad|reportes|eventos|intentos|viviendas|poblacion|población|manzanas|hombre|mujer|edad|ump asignadas|ump realizadas|ump titulares|ump completas|ump en campo|ump por aplicar|por completar|observado|esperado|faltante", header, ignore.case = TRUE)
}

.monitoreo_sheets_tab_required_size <- function(rows) {
  rows <- rows %||% list()
  row_count <- max(1L, length(rows))
  sample_rows <- if (length(rows)) rows else list(list(""))
  column_count <- max(1L, max(vapply(sample_rows, function(row) length(row %||% character(0)), integer(1))))
  list(row_count = row_count, column_count = column_count)
}

.monitoreo_sheets_grid_count <- function(value, fallback) {
  out <- suppressWarnings(as.integer(value %||% fallback))
  if (!is.finite(out) || out < 1L) out <- fallback
  max(1L, as.integer(out))
}

.monitoreo_sheets_reset_tab_requests <- function(sheet_id, tab, rows) {
  required <- .monitoreo_sheets_tab_required_size(rows)
  current_rows <- .monitoreo_sheets_grid_count(tab$row_count, required$row_count)
  current_cols <- .monitoreo_sheets_grid_count(tab$column_count, required$column_count)
  requests <- list()
  if (isTRUE(tab$has_basic_filter)) {
    requests[[length(requests) + 1L]] <- list(clearBasicFilter = list(sheetId = sheet_id))
  }
  conditional_count <- suppressWarnings(as.integer(tab$conditional_format_count %||% 0L))
  if (!is.finite(conditional_count) || conditional_count < 0L) conditional_count <- 0L
  if (conditional_count > 0L) {
    for (idx in rev(seq_len(conditional_count) - 1L)) {
      requests[[length(requests) + 1L]] <- list(
        deleteConditionalFormatRule = list(sheetId = sheet_id, index = idx)
      )
    }
  }
  requests[[length(requests) + 1L]] <- list(
    unmergeCells = list(range = list(
      sheetId = sheet_id,
      startRowIndex = 0L,
      endRowIndex = current_rows,
      startColumnIndex = 0L,
      endColumnIndex = current_cols
    ))
  )
  c(requests, list(
    list(
      updateCells = list(
        range = list(
          sheetId = sheet_id,
          startRowIndex = 0L,
          endRowIndex = current_rows,
          startColumnIndex = 0L,
          endColumnIndex = current_cols
        ),
        fields = "userEnteredValue,userEnteredFormat,note,dataValidation"
      )
    ),
    list(
      updateSheetProperties = list(
        properties = list(
          sheetId = sheet_id,
          gridProperties = list(
            rowCount = required$row_count,
            columnCount = required$column_count
          )
        ),
        fields = "gridProperties(rowCount,columnCount)"
      )
    )
  ))
}

.monitoreo_sheets_professional_format_requests <- function(sheet_id, tab_name, rows) {
  rows <- rows %||% list()
  row_count <- length(rows)
  col_count <- max(1L, max(vapply(rows %||% list(list("")), function(row) length(row %||% character(0)), integer(1))))
  technical_tab <- tab_name %in% c(
    "Auditoría técnica", "Auditoria tecnica", "Base técnica", "Base tecnica",
    "Trazabilidad del corte", "Registros del corte"
  )
  requests <- list(list(updateSheetProperties = list(
    properties = list(sheetId = sheet_id, gridProperties = list(frozenRowCount = min(1L, row_count))),
    fields = "gridProperties.frozenRowCount"
  )))
  if (!row_count) return(requests)

  section_rows <- which(vapply(rows, .monitoreo_sheets_is_section_row, logical(1)))
  for (idx in section_rows) {
    requests[[length(requests) + 1L]] <- list(
      mergeCells = list(
        range = list(sheetId = sheet_id, startRowIndex = idx - 1L, endRowIndex = idx, startColumnIndex = 0L, endColumnIndex = col_count),
        mergeType = "MERGE_ALL"
      )
    )
    requests[[length(requests) + 1L]] <- list(
      repeatCell = list(
        range = list(sheetId = sheet_id, startRowIndex = idx - 1L, endRowIndex = idx, startColumnIndex = 0L, endColumnIndex = col_count),
        cell = list(userEnteredFormat = list(
          backgroundColor = .monitoreo_sheets_rgb(if (technical_tab) "#4B5563" else "#0F355E"),
          horizontalAlignment = "LEFT",
          textFormat = list(bold = TRUE, foregroundColor = .monitoreo_sheets_rgb("#FFFFFF"), fontSize = 11)
        )),
        fields = "userEnteredFormat(backgroundColor,horizontalAlignment,textFormat)"
      )
    )
  }

  card_sections <- section_rows[vapply(section_rows, function(idx) {
    values <- .monitoreo_sheets_row_values(rows[[idx]])
    grepl("TARJETAS|CARDS|LECTURA RÁPIDA|LECTURA RAPIDA|INDICADORES DEL CORTE|RESUMEN UMP Y RESPONSABLES|RESUMEN DE OCURRENCIAS", .monitoreo_scalar(values[[1]] %||% "", ""), ignore.case = TRUE)
  }, logical(1))]
  for (section_idx in card_sections) {
    block_end <- .monitoreo_sheets_next_block_end(rows, section_idx)
    if (block_end <= section_idx) next
    card_rows <- seq.int(section_idx + 1L, block_end)
    card_rows <- card_rows[!vapply(rows[card_rows], .monitoreo_sheets_is_blank_row, logical(1))]
    if (!length(card_rows)) next
    for (row_idx in card_rows) {
      requests[[length(requests) + 1L]] <- list(
        repeatCell = list(
          range = list(sheetId = sheet_id, startRowIndex = row_idx - 1L, endRowIndex = row_idx, startColumnIndex = 0L, endColumnIndex = col_count),
          cell = list(userEnteredFormat = list(
            backgroundColor = .monitoreo_sheets_rgb("#F8FAFC"),
            verticalAlignment = "MIDDLE",
            wrapStrategy = "WRAP"
          )),
          fields = "userEnteredFormat(backgroundColor,verticalAlignment,wrapStrategy)"
        )
      )
    }
    for (row_idx in card_rows[seq(1L, length(card_rows), by = 3L)]) {
      requests[[length(requests) + 1L]] <- list(
        repeatCell = list(
          range = list(sheetId = sheet_id, startRowIndex = row_idx - 1L, endRowIndex = row_idx, startColumnIndex = 0L, endColumnIndex = col_count),
          cell = list(userEnteredFormat = list(
            textFormat = list(bold = TRUE, foregroundColor = .monitoreo_sheets_rgb("#64748B"), fontSize = 9)
          )),
          fields = "userEnteredFormat.textFormat"
        )
      )
      if (row_idx + 1L <= block_end) {
        requests[[length(requests) + 1L]] <- list(
          repeatCell = list(
            range = list(sheetId = sheet_id, startRowIndex = row_idx, endRowIndex = row_idx + 1L, startColumnIndex = 0L, endColumnIndex = col_count),
            cell = list(userEnteredFormat = list(
              textFormat = list(bold = TRUE, foregroundColor = .monitoreo_sheets_rgb("#0F172A"), fontSize = 14)
            )),
            fields = "userEnteredFormat.textFormat"
          )
        )
      }
      if (row_idx + 2L <= block_end) {
        requests[[length(requests) + 1L]] <- list(
          repeatCell = list(
            range = list(sheetId = sheet_id, startRowIndex = row_idx + 1L, endRowIndex = row_idx + 2L, startColumnIndex = 0L, endColumnIndex = col_count),
            cell = list(userEnteredFormat = list(
              textFormat = list(foregroundColor = .monitoreo_sheets_rgb("#64748B"), fontSize = 9)
            )),
            fields = "userEnteredFormat.textFormat"
          )
        )
      }
      for (col_start in seq(0L, max(0L, col_count - 1L), by = 3L)) {
        col_end <- min(col_count, col_start + 2L)
        requests[[length(requests) + 1L]] <- list(
          updateBorders = list(
            range = list(sheetId = sheet_id, startRowIndex = row_idx - 1L, endRowIndex = min(block_end, row_idx + 2L), startColumnIndex = col_start, endColumnIndex = col_end),
            top = list(style = "SOLID", width = 1L, color = .monitoreo_sheets_rgb("#CBD5E1")),
            bottom = list(style = "SOLID", width = 1L, color = .monitoreo_sheets_rgb("#CBD5E1")),
            left = list(style = "SOLID", width = 1L, color = .monitoreo_sheets_rgb("#CBD5E1")),
            right = list(style = "SOLID", width = 1L, color = .monitoreo_sheets_rgb("#CBD5E1"))
          )
        )
      }
    }
  }

  headers <- .monitoreo_sheets_table_header_rows(rows)
  filter_header_index <- .monitoreo_sheets_filter_header_index(tab_name, rows, headers)
  for (item in headers) {
    idx <- item$index
    header <- item$header
    end_idx <- .monitoreo_sheets_next_block_end(rows, idx)
    header_color <- if (technical_tab) "#5B556C" else if (tab_name %in% c("Tabla maestra", "Cuotas por manzana", "Cuotas sexo y edad", "Casos accionables", "Casos para revisar", "Validación de tiempos", "GPS y territorio")) "#9F1239" else "#123B70"
    requests[[length(requests) + 1L]] <- list(
      repeatCell = list(
        range = list(sheetId = sheet_id, startRowIndex = idx - 1L, endRowIndex = idx, startColumnIndex = 0L, endColumnIndex = length(header)),
        cell = list(userEnteredFormat = list(
          backgroundColor = .monitoreo_sheets_rgb(header_color),
          horizontalAlignment = "LEFT",
          wrapStrategy = "WRAP",
          textFormat = list(bold = TRUE, foregroundColor = .monitoreo_sheets_rgb("#FFFFFF"), fontSize = 10)
        )),
        fields = "userEnteredFormat(backgroundColor,horizontalAlignment,wrapStrategy,textFormat)"
      )
    )
    if (identical(item$kind, "data") && end_idx >= idx && isTRUE(idx == filter_header_index)) {
      requests[[length(requests) + 1L]] <- list(
        setBasicFilter = list(filter = list(range = list(
          sheetId = sheet_id,
          startRowIndex = idx - 1L,
          endRowIndex = end_idx,
          startColumnIndex = 0L,
          endColumnIndex = length(header)
        )))
      )
    }
    has_data_rows <- end_idx > idx
    if (isTRUE(has_data_rows)) {
      for (col in .monitoreo_sheets_progress_columns(header)) {
        requests[[length(requests) + 1L]] <- list(
          repeatCell = list(
            range = list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col),
            cell = list(userEnteredFormat = list(numberFormat = list(type = "PERCENT", pattern = "0.0%"))),
            fields = "userEnteredFormat.numberFormat"
          )
        )
      }
      for (col in .monitoreo_sheets_integer_columns(header)) {
        requests[[length(requests) + 1L]] <- list(
          repeatCell = list(
            range = list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col),
            cell = list(userEnteredFormat = list(numberFormat = list(type = "NUMBER", pattern = "#,##0"))),
            fields = "userEnteredFormat.numberFormat"
          )
        )
      }
      numeric_alert_cols <- list(
        list(cols = grep("pendientes|faltantes|faltante", header, ignore.case = TRUE), bg = "#FEE2E2", fg = "#991B1B")
      )
      for (alert in numeric_alert_cols) {
        for (col in alert$cols) {
          requests[[length(requests) + 1L]] <- list(
            addConditionalFormatRule = list(
              rule = list(
                ranges = list(list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col)),
                booleanRule = list(
                  condition = list(type = "NUMBER_GREATER", values = list(list(userEnteredValue = "0"))),
                  format = list(backgroundColor = .monitoreo_sheets_rgb(alert$bg), textFormat = list(foregroundColor = .monitoreo_sheets_rgb(alert$fg), bold = TRUE))
                )
              ),
              index = 0L
            )
          )
        }
      }
      quota_pairs <- .monitoreo_sheets_quota_observed_pairs(header)
      if (length(quota_pairs)) {
        first_data_row <- idx + 1L
        pair_formats <- list(
          list(op = ">", bg = "#EDE9FE", fg = "#5B21B6"),
          list(op = "=", bg = "#DCFCE7", fg = "#14532D"),
          list(op = "<", bg = "#FEE2E2", fg = "#991B1B")
        )
        for (pair in quota_pairs) {
          observed_col <- .monitoreo_sheets_a1_col(pair$observed)
          quota_col <- .monitoreo_sheets_a1_col(pair$quota)
          observed_ref <- sprintf("$%s%d", observed_col, first_data_row)
          quota_ref <- sprintf("$%s%d", quota_col, first_data_row)
          for (fmt in pair_formats) {
            formula <- .monitoreo_sheets_quota_comparison_formula(observed_ref, quota_ref, fmt$op)
            requests[[length(requests) + 1L]] <- list(
              addConditionalFormatRule = list(
                rule = list(
                  ranges = list(list(
                    sheetId = sheet_id,
                    startRowIndex = idx,
                    endRowIndex = end_idx,
                    startColumnIndex = pair$observed - 1L,
                    endColumnIndex = pair$observed
                  )),
                  booleanRule = list(
                    condition = list(type = "CUSTOM_FORMULA", values = list(list(userEnteredValue = formula))),
                    format = list(
                      backgroundColor = .monitoreo_sheets_rgb(fmt$bg),
                      textFormat = list(foregroundColor = .monitoreo_sheets_rgb(fmt$fg), bold = TRUE)
                    )
                  )
                ),
                index = 0L
              )
            )
          }
        }
      }
      palette <- .monitoreo_sheets_status_palette()
      for (col in .monitoreo_sheets_status_columns(header)) {
        status_col <- .monitoreo_sheets_a1_col(col)
        first_data_row <- idx + 1L
        status_ref <- sprintf("$%s%d", status_col, first_data_row)
        for (status in names(palette)) {
          fmt <- palette[[status]]
          requests[[length(requests) + 1L]] <- list(
            addConditionalFormatRule = list(
              rule = list(
                ranges = list(list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col)),
                booleanRule = list(
                  condition = list(type = "CUSTOM_FORMULA", values = list(list(userEnteredValue = .monitoreo_sheets_text_equals_formula(status_ref, status)))),
                  format = list(backgroundColor = .monitoreo_sheets_rgb(fmt$bg), textFormat = list(foregroundColor = .monitoreo_sheets_rgb(fmt$fg), bold = TRUE))
                )
              ),
              index = 0L
            )
          )
        }
      }
      assignment_slot_palette <- list(
        "Completa" = list(bg = "#DCFCE7", fg = "#14532D"),
        "Pendiente" = list(bg = "#F3F4F6", fg = "#4B5563")
      )
      for (col in .monitoreo_sheets_assignment_slot_columns(header)) {
        slot_col <- .monitoreo_sheets_a1_col(col)
        first_data_row <- idx + 1L
        slot_ref <- sprintf("$%s%d", slot_col, first_data_row)
        for (status in names(assignment_slot_palette)) {
          fmt <- assignment_slot_palette[[status]]
          requests[[length(requests) + 1L]] <- list(
            addConditionalFormatRule = list(
              rule = list(
                ranges = list(list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col)),
                booleanRule = list(
                  condition = list(type = "CUSTOM_FORMULA", values = list(list(userEnteredValue = .monitoreo_sheets_text_equals_formula(slot_ref, status)))),
                  format = list(backgroundColor = .monitoreo_sheets_rgb(fmt$bg), textFormat = list(foregroundColor = .monitoreo_sheets_rgb(fmt$fg), bold = TRUE))
                )
              ),
              index = 0L
            )
          )
        }
      }
      wrap_cols <- which(grepl("descripcion|descripción|observaci|accion|acción|warnings|supuestos|alertas asociadas", header, ignore.case = TRUE))
      for (col in wrap_cols) {
        requests[[length(requests) + 1L]] <- list(
          repeatCell = list(
            range = list(sheetId = sheet_id, startRowIndex = idx, endRowIndex = end_idx, startColumnIndex = col - 1L, endColumnIndex = col),
            cell = list(userEnteredFormat = list(wrapStrategy = "WRAP", verticalAlignment = "TOP")),
            fields = "userEnteredFormat(wrapStrategy,verticalAlignment)"
          )
        )
      }
    }
    for (col in seq_along(header)) {
      requests[[length(requests) + 1L]] <- list(
        updateDimensionProperties = list(
          range = list(sheetId = sheet_id, dimension = "COLUMNS", startIndex = col - 1L, endIndex = col),
          properties = list(pixelSize = .monitoreo_sheets_col_width(header[[col]])),
          fields = "pixelSize"
        )
      )
    }
  }
  requests
}

monitoreo_sheets_publish_tabs <- function(spreadsheet_id, tabs) {
  spreadsheet_id <- .monitoreo_extract_spreadsheet_id(spreadsheet_id)
  if (!nzchar(spreadsheet_id)) stop("Falta spreadsheet_id para publicar.", call. = FALSE)
  tab_names <- names(tabs)
  .monitoreo_sheets_validate_controlled_tabs(tab_names)

  meta <- .monitoreo_sheets_metadata(spreadsheet_id)
  tab_map <- .monitoreo_sheets_tab_map(meta)
  missing_tabs <- setdiff(tab_names, names(tab_map))
  if (length(missing_tabs)) {
    .monitoreo_sheets_batch_update(
      spreadsheet_id,
      lapply(missing_tabs, function(tab_name) {
        list(addSheet = list(properties = list(title = tab_name)))
      })
    )
    meta <- .monitoreo_sheets_metadata(spreadsheet_id)
    tab_map <- .monitoreo_sheets_tab_map(meta)
  }

  metadata_requests <- list()
  for (tab_name in tab_names) {
    tab <- tab_map[[tab_name]]
    if (is.null(tab) || is.na(tab$sheet_id)) {
      stop(sprintf("No se pudo preparar la pestana controlada %s.", tab_name), call. = FALSE)
    }
    if (!.monitoreo_sheets_has_owner_metadata(tab)) {
      metadata_requests[[length(metadata_requests) + 1L]] <- list(
        createDeveloperMetadata = list(
          developerMetadata = list(
            metadataKey = .monitoreo_sheets_owner_key(),
            metadataValue = .monitoreo_sheets_owner_value(),
            visibility = "DOCUMENT",
            location = list(sheetId = tab$sheet_id)
          )
        )
      )
    }
  }
  .monitoreo_sheets_batch_update(spreadsheet_id, metadata_requests)

  reset_requests <- list()
  for (tab_name in tab_names) {
    tab <- tab_map[[tab_name]]
    sheet_id <- tab$sheet_id %||% NA_integer_
    if (is.null(tab) || is.na(sheet_id)) next
    reset_requests <- c(reset_requests, .monitoreo_sheets_reset_tab_requests(sheet_id, tab, tabs[[tab_name]]))
  }
  .monitoreo_sheets_batch_update(spreadsheet_id, reset_requests)

  written_ranges <- list()
  for (tab_name in tab_names) {
    range <- .monitoreo_sheets_quote_sheet(tab_name)
    encoded_range <- utils::URLencode(range, reserved = TRUE)
    clear_url <- paste0(.monitoreo_sheets_api_base(spreadsheet_id), "/values/", encoded_range, ":clear")
    update_url <- paste0(
      .monitoreo_sheets_api_base(spreadsheet_id),
      "/values/",
      encoded_range,
      "?valueInputOption=RAW"
    )
    .monitoreo_google_api(clear_url, method = "POST", body = structure(list(), names = character()))
    .monitoreo_google_api(
      update_url,
      method = "PUT",
      body = list(majorDimension = "ROWS", values = .monitoreo_sheets_values_rows(tabs[[tab_name]]))
    )
    written_ranges[[length(written_ranges) + 1L]] <- list(
      tab = tab_name,
      range = range,
      rows = length(tabs[[tab_name]] %||% list())
    )
  }
  format_requests <- list()
  for (tab_name in tab_names) {
    tab <- tab_map[[tab_name]]
    sheet_id <- tab$sheet_id %||% NA_integer_
    if (is.null(tab) || is.na(sheet_id)) next
    format_requests <- c(format_requests, .monitoreo_sheets_professional_format_requests(sheet_id, tab_name, tabs[[tab_name]]))
  }
  .monitoreo_sheets_batch_update(spreadsheet_id, format_requests)

  list(
    ok = TRUE,
    spreadsheet_id = spreadsheet_id,
    spreadsheet_url = paste0("https://docs.google.com/spreadsheets/d/", spreadsheet_id, "/edit"),
    controlled_tabs = as.list(tab_names),
    written_ranges = written_ranges,
    updated_at = .monitoreo_now_iso(),
    mode = "controlled_write"
  )
}

monitoreo_sheets_list_spreadsheets <- function(limit = 50L) {
  # Drive API list is optional for v1. It is useful when the token has Drive
  # scope; otherwise callers can register by spreadsheet id directly.
  url <- paste0(
    "https://www.googleapis.com/drive/v3/files?",
    "q=", utils::URLencode("mimeType='application/vnd.google-apps.spreadsheet' and trashed=false", reserved = TRUE),
    "&fields=files(id,name,modifiedTime,webViewLink)&pageSize=",
    max(1L, min(100L, .monitoreo_int(limit, 50L)))
  )
  payload <- .monitoreo_google_api(url)
  list(ok = TRUE, spreadsheets = payload$files %||% list())
}

monitoreo_sheets_inspect <- function(spreadsheet_id, sheet_name = "", header_row = 1L, range = "") {
  spreadsheet_id <- .monitoreo_extract_spreadsheet_id(spreadsheet_id)
  if (!nzchar(spreadsheet_id)) stop("Falta spreadsheet_id.", call. = FALSE)
  meta_url <- paste0(.monitoreo_sheets_api_base(spreadsheet_id), "?fields=spreadsheetId,properties.title,sheets.properties")
  meta <- .monitoreo_google_api(meta_url)
  sheets <- lapply(meta$sheets %||% list(), function(item) {
    props <- item$properties %||% list()
    list(
      sheet_id = props$sheetId %||% NA_integer_,
      title = .monitoreo_scalar(props$title, ""),
      row_count = props$gridProperties$rowCount %||% NA_integer_,
      column_count = props$gridProperties$columnCount %||% NA_integer_
    )
  })
  header <- character(0)
  selected <- .monitoreo_scalar(sheet_name, "")
  if (nzchar(selected)) {
    header_row <- max(1L, .monitoreo_int(header_row, 1L))
    header_range <- if (nzchar(range)) range else sprintf("'%s'!%s:%s", gsub("'", "''", selected), header_row, header_row)
    values_url <- paste0(.monitoreo_sheets_api_base(spreadsheet_id), "/values/", utils::URLencode(header_range, reserved = TRUE))
    values <- .monitoreo_google_api(values_url)
    header <- as.character((values$values %||% list(list()))[[1]] %||% character(0))
  }
  list(
    ok = TRUE,
    spreadsheet_id = spreadsheet_id,
    title = .monitoreo_scalar(meta$properties$title, ""),
    sheets = sheets,
    headers = as.list(header)
  )
}

.monitoreo_values_to_dataframe <- function(values, header_row = 1L) {
  if (is.null(values) || !length(values)) return(data.frame())
  rows <- lapply(values, function(row) as.character(row %||% character(0)))
  header_row <- max(1L, .monitoreo_int(header_row, 1L))
  if (length(rows) < header_row) return(data.frame())
  headers <- rows[[header_row]]
  if (!length(headers)) return(data.frame())
  headers <- ifelse(nzchar(trimws(headers)), trimws(headers), paste0("col_", seq_along(headers)))
  headers <- make.unique(headers, sep = "_")
  if (length(rows) <= header_row) {
    return(as.data.frame(setNames(rep(list(character(0)), length(headers)), headers), stringsAsFactors = FALSE))
  }
  data_rows <- rows[(header_row + 1L):length(rows)]
  aligned <- lapply(data_rows, function(row) {
    length(row) <- length(headers)
    row[is.na(row)] <- ""
    row
  })
  out <- as.data.frame(do.call(rbind, aligned), stringsAsFactors = FALSE, optional = TRUE)
  names(out) <- headers
  out
}

monitoreo_sheets_read_source <- function(source) {
  binding <- source$sheet_binding %||% .monitoreo_sheet_binding(source)
  spreadsheet_id <- .monitoreo_scalar(binding$spreadsheet_id, "")
  sheet_name <- .monitoreo_scalar(binding$sheet_name, "")
  if (!nzchar(spreadsheet_id) || !nzchar(sheet_name)) {
    stop("Fuente Google Sheets sin spreadsheet_id o sheet_name.", call. = FALSE)
  }
  range <- .monitoreo_scalar(binding$range, "")
  if (!nzchar(range)) range <- sprintf("'%s'", gsub("'", "''", sheet_name))
  url <- paste0(.monitoreo_sheets_api_base(spreadsheet_id), "/values/", utils::URLencode(range, reserved = TRUE))
  payload <- .monitoreo_google_api(url)
  data <- .monitoreo_values_to_dataframe(payload$values %||% list(), binding$header_row %||% 1L)
  binding$last_read_at <- .monitoreo_now_iso()
  binding$snapshot_hash <- monitoreo_snapshot_hash(data)
  attr(data, "sheet_binding") <- binding
  data
}

.monitoreo_kobo_max_submission_id <- function(data, fallback = NA_real_) {
  fallback <- suppressWarnings(as.numeric(fallback %||% NA_real_))
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(fallback)
  id_col <- c("_id", "id", "submission_id")
  id_col <- id_col[id_col %in% names(data)]
  if (!length(id_col)) return(fallback)
  values <- suppressWarnings(as.numeric(data[[id_col[[1]]]]))
  values <- values[is.finite(values)]
  if (!length(values)) return(fallback)
  max(values, fallback, na.rm = TRUE)
}

.monitoreo_kobo_source_cursor_id <- function(source) {
  cursor <- .monitoreo_normalize_sync_cursor(source$sync_cursor %||% source$syncCursor)
  value <- suppressWarnings(as.numeric(cursor$kobo_max_id %||% NA_real_))
  if (is.finite(value) && value > 0) value else NA_real_
}

.monitoreo_sync_mode <- function(value = "full") {
  mode <- tolower(.monitoreo_scalar(value, "full"))
  if (mode %in% c("advance", "avance", "responses", "responses_only", "response_only")) return("advance")
  "full"
}

.monitoreo_sync_mode_is_advance <- function(value = "full") {
  identical(.monitoreo_sync_mode(value), "advance")
}

monitoreo_sync_source <- function(source, since = NULL, progress = NULL, sid = NULL, connection_token = NULL, sync_mode = "full") {
  sync_mode <- .monitoreo_sync_mode(sync_mode)
  kind <- .monitoreo_scalar(source$kind, "")
  connection_token <- .monitoreo_scalar(connection_token, "")
  if (identical(kind, "kobo")) {
    if (!is.null(progress)) progress(0L, 8L, "Kobo: preparando perfil de conexion")
    profile_id <- .monitoreo_scalar(source$connection_profile_id %||% source$profile_id, "")
    base_url <- .monitoreo_scalar(source$base_url, "")
    if (!nzchar(base_url)) base_url <- .connections_profile_base_url("kobo", profile_id)
    if (!nzchar(base_url)) base_url <- kobo_api_default_base_url()
    if (!is.null(progress)) progress(1L, 8L, sprintf("Kobo: servidor %s", base_url))
    token <- if (nzchar(connection_token)) connection_token else .connections_token_require("kobo", sid, profile_id = profile_id, base_url = base_url)
    if (!is.null(progress)) progress(2L, 8L, "Kobo: token local encontrado")
    cursor_id <- .monitoreo_kobo_source_cursor_id(source)
    payload <- NULL
    sync_mode <- "full"
    if (is.finite(cursor_id)) {
      if (!is.null(progress)) progress(3L, 8L, "Kobo: buscando registros nuevos")
      payload <- tryCatch(
        kobo_api_fetch_all_asset_data(
          asset_uid = source$asset_uid,
          token = token,
          base_url = base_url,
          min_id = cursor_id,
          progress = progress
        ),
        error = function(e) {
          if (!is.null(progress)) progress(3L, 8L, "Kobo: consulta incremental no disponible; actualización completa")
          NULL
        }
      )
      if (!is.null(payload)) sync_mode <- "incremental"
    }
    if (is.null(payload)) {
      if (!is.null(progress)) progress(3L, 8L, "Kobo: descargando respuestas completas")
      payload <- kobo_api_fetch_all_asset_data(
        asset_uid = source$asset_uid,
        token = token,
        base_url = base_url,
        progress = progress
      )
      sync_mode <- "full"
    }
    if (!is.null(progress)) {
      progress(6L, 8L, sprintf("Kobo: %s respuestas recibidas", format(as.integer(payload$count %||% 0L), big.mark = ",", trim = TRUE)))
      progress(7L, 8L, "Kobo: normalizando respuestas")
    }
    data <- kobo_api_flatten_results(payload$results)
    if (!is.null(progress)) progress(8L, 8L, "Kobo: fechas y campos listos")
    data <- monitoreo_enrich_kobo_datetime_columns(data)
    max_id <- .monitoreo_kobo_max_submission_id(data, fallback = cursor_id)
    attr(data, "sync_mode") <- sync_mode
    attr(data, "sync_cursor") <- .monitoreo_normalize_sync_cursor(list(
      kobo_max_id = max_id,
      updated_at = .monitoreo_now_iso(),
      mode = sync_mode,
      fetched_count = as.integer(payload$count %||% nrow(data)),
      remote_total = as.integer(payload$total %||% payload$count %||% nrow(data))
    ))
  } else if (identical(kind, "surveymonkey")) {
    advance_mode <- .monitoreo_sync_mode_is_advance(sync_mode)
    profile_id <- .monitoreo_scalar(source$connection_profile_id %||% source$profile_id, "")
    base_url <- source$base_url %||% "https://api.surveymonkey.com/v3"
    token_candidates <- .monitoreo_surveymonkey_token_candidates(
      sid = sid,
      preferred_profile_id = profile_id,
      connection_token = connection_token
    )
    last_error <- NULL
    data <- NULL
    selected_profile_id <- profile_id
    for (candidate in token_candidates) {
      token <- .monitoreo_scalar(candidate$token, "")
      candidate_profile_id <- .monitoreo_scalar(candidate$profile_id, "")
      attempt <- tryCatch({
        details <- sm_api_fetch_survey_details(source$survey_id, token, base_url = base_url)
        source$survey_title <- .monitoreo_scalar(details$title, source$survey_title %||% "")
        collector_sync_error <- ""
        collectors_meta <- list()
        if (!advance_mode) {
          collectors_meta <- tryCatch({
            collectors <- sm_api_fetch_collectors(source$survey_id, token, base_url = base_url)
            out <- list()
            for (collector in collectors$data %||% list()) {
              collector_id <- .monitoreo_scalar(collector$id %||% collector$collector_id, "")
              if (!nzchar(collector_id)) next
              detail <- tryCatch(
                sm_api_fetch_collector_detail(collector_id, token, base_url = base_url),
                error = function(e) collector
              )
              out[[collector_id]] <- list(
                id = collector_id,
                collector_id = collector_id,
                name = .monitoreo_scalar(
                  detail$name %||% detail$title %||% detail$collector_name %||% detail$collectorName %||%
                    detail$display_name %||% detail$displayName %||% detail$nickname %||%
                    (detail$metadata %||% list())$name %||% (detail$metadata %||% list())$title %||%
                    (detail$collector %||% list())$name %||% (detail$collector %||% list())$title %||%
                    collector$name %||% collector$title %||% collector$collector_name %||% collector$collectorName %||%
                    collector$display_name %||% collector$displayName %||% collector$nickname,
                  ""
                ),
                type = .monitoreo_scalar(detail$type %||% detail$collector_type %||% detail$collectorType %||% collector$type, ""),
                url = .monitoreo_scalar(detail$url %||% collector$url %||% detail$href %||% collector$href, ""),
                response_count = as.integer(.monitoreo_num(detail$response_count %||% collector$response_count, 0)),
                synced_at = .monitoreo_now_iso()
              )
            }
            unname(out)
          }, error = function(e) {
            collector_sync_error <<- conditionMessage(e)
            list()
          })
        }
        payload <- sm_api_fetch_all_responses_bulk(
          survey_id = source$survey_id,
          token = token,
          since = since,
          progress = progress,
          base_url = base_url
        )
        df <- sm_api_flatten_responses(details, payload$data)
        df <- sm_api_enrich_response_recipients(
          df,
          token = token,
          base_url = base_url,
          include_details = !advance_mode
        )
        if (!advance_mode) {
          attr(df, "monitoreo_source_collectors") <- collectors_meta
          if (nzchar(collector_sync_error)) attr(df, "monitoreo_source_collectors_error") <- collector_sync_error
        }
        attr(df, "connection_profile_id") <- candidate_profile_id
        attr(df, "survey_title") <- source$survey_title
        df
      }, error = function(e) {
        last_error <<- list(profile_id = candidate_profile_id, message = conditionMessage(e))
        NULL
      })
      if (!is.null(attempt)) {
        data <- attempt
        selected_profile_id <- candidate_profile_id
        break
      }
    }
    if (is.null(data)) {
      msg <- .monitoreo_scalar(last_error$message, "No fue posible sincronizar SurveyMonkey.")
      profile_msg <- .monitoreo_scalar(last_error$profile_id, "")
      if (nzchar(profile_msg)) msg <- sprintf("%s (ultimo perfil probado: %s)", msg, profile_msg)
      stop(msg, call. = FALSE)
    }
    if (nzchar(selected_profile_id)) attr(data, "connection_profile_id") <- selected_profile_id
    survey_title <- .monitoreo_scalar(attr(data, "survey_title", exact = TRUE), "")
    if (nzchar(survey_title)) source$survey_title <- survey_title
    if (nzchar(selected_profile_id)) source$connection_profile_id <- selected_profile_id
    attr(data, "sync_mode") <- if (advance_mode) "advance" else if (is.null(since)) "full" else "incremental"
  } else if (identical(kind, "google_sheets")) {
    data <- monitoreo_sheets_read_source(source)
    attr(data, "sync_mode") <- "full"
  } else {
    stop("Tipo de fuente no soportado.", call. = FALSE)
  }
  sheet_binding <- attr(data, "sheet_binding", exact = TRUE)
  source_collectors <- attr(data, "monitoreo_source_collectors", exact = TRUE)
  connection_profile_id <- .monitoreo_scalar(attr(data, "connection_profile_id", exact = TRUE), "")
  if (identical(kind, "surveymonkey") && nzchar(source$survey_title %||% "")) attr(data, "survey_title") <- source$survey_title
  data <- .monitoreo_add_source_columns(data, source)
  if (is.list(sheet_binding)) attr(data, "sheet_binding") <- sheet_binding
  if (is.list(source_collectors)) attr(data, "monitoreo_source_collectors") <- source_collectors
  if (nzchar(connection_profile_id)) attr(data, "connection_profile_id") <- connection_profile_id
  data
}

monitoreo_sync_sources <- function(sources, config = list(), since = NULL, progress_path = NULL, build_dashboard = TRUE, sid = NULL, connection_tokens = list(), sync_mode = "full") {
  sync_mode <- .monitoreo_sync_mode(sync_mode)
  sources <- Filter(function(s) isTRUE(s$enabled), monitoreo_normalize_sources(sources))
  if (.monitoreo_sync_mode_is_advance(sync_mode)) {
    sources <- Filter(function(s) .monitoreo_scalar(s$kind, "") %in% c("surveymonkey", "kobo"), sources)
  }
  if (!length(sources)) stop("Configura al menos una fuente activa de monitoreo.", call. = FALSE)
  report <- if (!is.null(progress_path)) job_progress_writer(progress_path) else function(...) invisible(NULL)
  dfs <- list()
  errors <- list()
  sync_summary <- list()
  n_sources <- length(sources)
  report("prepare", percent = 3, message = "Preparando fuentes de monitoreo...")
  for (i in seq_along(sources)) {
    src <- sources[[i]]
    source_label <- .monitoreo_scalar(src$label, sprintf("fuente %d", i))
    source_kind <- .monitoreo_scalar(src$kind, "")
    source_start <- 8 + round(72 * (i - 1) / max(1, n_sources))
    source_end <- 8 + round(72 * i / max(1, n_sources))
    source_span <- max(1, source_end - source_start)
    source_phase <- switch(source_kind,
      kobo = "kobo_connect",
      surveymonkey = "survey_fetch",
      google_sheets = "sheets_fetch",
      "source"
    )
    report(source_phase, current = i, total = n_sources,
           percent = source_start,
           message = sprintf("Preparando %s...", source_label))
    local_progress <- function(current, total, message) {
      current_n <- suppressWarnings(as.numeric(current %||% NA_real_))
      total_n <- suppressWarnings(as.numeric(total %||% NA_real_))
      msg <- .monitoreo_scalar(message, sprintf("Sincronizando %s...", source_label))
      msg_l <- tolower(msg)
      phase <- source_phase
      pct <- NA_real_
      if (identical(source_kind, "kobo")) {
        if (grepl("perfil|servidor|token|conect", msg_l, perl = TRUE)) {
          phase <- "kobo_connect"
          pct <- source_start + round(source_span * 0.12)
        } else if (grepl("respuestas recibidas", msg_l, perl = TRUE)) {
          phase <- "kobo_fetch"
          pct <- source_start + round(source_span * 0.86)
        } else if (grepl("normalizando|fecha|campos", msg_l, perl = TRUE)) {
          phase <- "kobo_parse"
          pct <- source_start + round(source_span * 0.9)
        } else {
          phase <- "kobo_fetch"
          pct <- if (is.finite(current_n) && is.finite(total_n) && total_n > 0) {
            source_start + round(source_span * (0.25 + 0.58 * min(1, current_n / total_n)))
          } else {
            source_start + round(source_span * 0.22)
          }
        }
      } else if (identical(source_kind, "surveymonkey")) {
        phase <- "survey_fetch"
        pct <- if (is.finite(current_n) && is.finite(total_n) && total_n > 0) {
          source_start + round(source_span * 0.88 * min(1, current_n / total_n))
        } else {
          source_start + round(source_span * 0.2)
        }
      } else if (identical(source_kind, "google_sheets")) {
        phase <- "sheets_fetch"
        pct <- source_start + round(source_span * 0.5)
      } else {
        pct <- if (is.finite(current_n) && is.finite(total_n) && total_n > 0) {
          source_start + round(source_span * min(1, current_n / total_n))
        } else {
          source_start + round(source_span * 0.35)
        }
      }
      pct <- max(source_start, min(source_end - 1, round(pct)))
      report(phase,
             current = if (is.finite(current_n)) as.integer(current_n) else NULL,
             total = if (is.finite(total_n)) as.integer(total_n) else NULL,
             percent = pct,
             message = msg)
    }
    source_token <- .monitoreo_scalar(
      (connection_tokens %||% list())[[.monitoreo_scalar(src$id, "")]] %||%
        (connection_tokens %||% list())[[.monitoreo_scalar(src$survey_id, "")]] %||%
        (connection_tokens %||% list())[[.monitoreo_scalar(src$asset_uid, "")]],
      ""
    )
    df <- tryCatch(monitoreo_sync_source(src, since = since, progress = local_progress, sid = sid, connection_token = source_token, sync_mode = sync_mode), error = function(e) {
      errors[[length(errors) + 1L]] <<- list(source_id = src$id, source_label = src$label, message = conditionMessage(e))
      report("source_error", current = i, total = n_sources,
             percent = max(source_start, min(source_end - 1, source_start + round(source_span * 0.85))),
             message = sprintf("%s no se pudo sincronizar: %s", source_label, conditionMessage(e)))
      NULL
    })
    if (!is.null(df)) {
      binding <- attr(df, "sheet_binding", exact = TRUE)
      if (is.list(binding)) sources[[i]]$sheet_binding <- binding
      survey_title <- attr(df, "survey_title", exact = TRUE)
      if (is.character(survey_title) && nzchar(survey_title[[1]] %||% "")) sources[[i]]$survey_title <- survey_title[[1]]
      connection_profile_id <- .monitoreo_scalar(attr(df, "connection_profile_id", exact = TRUE), "")
      if (nzchar(connection_profile_id)) sources[[i]]$connection_profile_id <- connection_profile_id
      source_collectors <- attr(df, "monitoreo_source_collectors", exact = TRUE)
      if (is.list(source_collectors)) sources[[i]]$collectors <- .monitoreo_normalize_source_collectors(source_collectors)
      collector_sync_error <- .monitoreo_scalar(attr(df, "monitoreo_source_collectors_error", exact = TRUE), "")
      if (nzchar(collector_sync_error)) sources[[i]]$collectors_error <- collector_sync_error
      sync_mode <- .monitoreo_scalar(attr(df, "sync_mode", exact = TRUE), "full")
      sync_cursor <- attr(df, "sync_cursor", exact = TRUE)
      if (is.list(sync_cursor)) sources[[i]]$sync_cursor <- .monitoreo_normalize_sync_cursor(sync_cursor)
      sources[[i]]$last_sync_mode <- sync_mode
      sync_summary[[.monitoreo_scalar(src$id, paste0("source_", i))]] <- list(
        source_id = .monitoreo_scalar(src$id, ""),
        source_label = .monitoreo_scalar(src$label, ""),
        kind = .monitoreo_scalar(src$kind, ""),
        mode = sync_mode,
        rows = as.integer(nrow(df)),
        connection_profile_id = .monitoreo_scalar(sources[[i]]$connection_profile_id, ""),
        cursor = if (is.list(sync_cursor)) .monitoreo_normalize_sync_cursor(sync_cursor) else list()
      )
      dfs[[length(dfs) + 1L]] <- df
      report("source_done", current = i, total = n_sources,
             percent = source_end,
             message = sprintf("%s listo: %s registros", source_label, format(nrow(df), big.mark = ",", trim = TRUE)))
    }
  }
  if (!length(dfs)) {
    report("snapshot", percent = 82, message = "No se pudo actualizar ninguna fuente; se conservara el snapshot anterior.")
    empty <- data.frame()
    cfg <- monitoreo_normalize_config(config, empty)
    return(list(
      ok = FALSE,
      synced_at = .monitoreo_now_iso(),
      n_rows = 0L,
      n_sources = 0L,
      errors = errors,
      data = empty,
      sources = sources,
      config = cfg,
      dashboard = NULL,
      variables = list(),
      sync_summary = sync_summary
    ))
  }
  report("snapshot", percent = 82, message = "Uniendo fuentes en un snapshot local...")
  data <- .monitoreo_bind_rows(dfs)
  report("config", percent = 85, message = "Recalculando variables y mapeos...")
  cfg <- monitoreo_normalize_config(config, data)
  dashboard <- NULL
  variables <- list()
  if (isTRUE(build_dashboard)) {
    report("dashboard", percent = 90, message = "Reconstruyendo tablero de monitoreo...")
    dashboard <- monitoreo_build_dashboard(data, cfg)
    report("variables", percent = 96, message = "Preparando variables para la interfaz...")
    variables <- monitoreo_variables(data)
  } else {
    report("snapshot", percent = 88, message = "Combinando snapshot local...")
  }
  list(
    ok = TRUE,
    synced_at = .monitoreo_now_iso(),
    n_rows = as.integer(nrow(data)),
    n_sources = as.integer(length(dfs)),
    errors = errors,
    data = data,
    sources = sources,
    config = cfg,
    dashboard = dashboard,
    variables = variables,
    sync_summary = sync_summary
  )
}

.monitoreo_snapshot_nonempty_values <- function(x, limit = 6L) {
  if (is.null(x)) return(character(0))
  values <- trimws(as.character(x))
  values <- values[!is.na(values) & nzchar(values)]
  values <- unique(values)
  if (!length(values)) return(character(0))
  raw_limit <- suppressWarnings(as.numeric(limit)[1])
  limit_n <- if (is.finite(raw_limit)) max(1L, as.integer(raw_limit)) else length(values)
  values[seq_len(min(length(values), limit_n))]
}

.monitoreo_snapshot_variable_kind <- function(name, label) {
  text <- .monitoreo_text_key(paste(name, label))
  compact <- gsub("[^a-z0-9]+", "", text)
  if (grepl("pulso|codpulso|codigopulso", compact) && !grepl("pucp|puc|puk", compact)) return("other")
  if ((grepl("\\b(codigo|cod)\\b", text) && grepl("\\b(pucp|puc|puk)\\b|institucional|universitario|docente|estudiante|alumno", text)) ||
      grepl("codigopucp|codigopuc|codigopuk|codpucp|codpuc|codpuk", compact)) return("pucp")
  if (grepl("\\b(celular|telefono|movil|whatsapp|phone|cell)\\b", text)) return("cell")
  if (grepl("\\b(correo|email|mail)\\b", text)) return("email")
  if (grepl("\\b(nombre|apellido|persona|nombres)\\b", text)) return("name")
  "other"
}

.monitoreo_snapshot_declared_score <- function(name, label, examples, non_empty = 0L, total = 0L) {
  text <- .monitoreo_text_key(paste(name, label))
  compact <- gsub("[^a-z0-9]+", "", text)
  kind <- .monitoreo_snapshot_variable_kind(name, label)
  score <- 0
  if (identical(kind, "pucp")) score <- score + 70
  if (grepl("codigopucp|codigopuc|codigopuk|codpucp|codpuc|codpuk", compact)) score <- score + 50
  if (grepl("\\bpucp\\b|\\bpuc\\b|\\bpuk\\b", text)) score <- score + 24
  if (grepl("\\bpulso\\b|codpulso|codigopulso", compact)) score <- score - 120
  values <- trimws(as.character(examples %||% character(0)))
  values <- values[nzchar(values)]
  if (length(values)) {
    digits <- gsub("\\D+", "", values)
    plausible <- sum(nchar(digits) >= 5L & nchar(digits) <= 10L)
    sixish <- sum(nchar(digits) >= 5L & nchar(digits) <= 7L)
    score <- score + round(34 * plausible / length(values)) + round(16 * sixish / length(values))
  }
  total <- suppressWarnings(as.numeric(total)[1])
  non_empty <- suppressWarnings(as.numeric(non_empty)[1])
  if (is.finite(total) && total > 0 && is.finite(non_empty)) score <- score + round(18 * min(1, non_empty / total))
  as.integer(score)
}

.monitoreo_snapshot_variable_stats_for_source <- function(data, source_id, source = NULL, max_variables = 220L) {
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(list())
  source_id <- .monitoreo_scalar(source_id, "")
  if (!nzchar(source_id) || !".source_id" %in% names(data)) return(list())
  idx <- which(as.character(data$.source_id) == source_id)
  if (!length(idx)) return(list())
  df <- data[idx, , drop = FALSE]
  labels_by_source <- .monitoreo_source_variable_label_map(data)
  labels <- labels_by_source[[source_id]] %||% .monitoreo_variable_label_map(data)
  technical <- c(
    "response_id", "recipient_id", "collector_id", "survey_id", "source_id", "source_label",
    "ip_address", "analyze_url", "edit_url", "href", "total_time", "date_created",
    "date_modified", "collection_mode", "custom_variables", "first_name", "last_name"
  )
  cols <- names(df)
  cols <- cols[!startsWith(cols, ".")]
  cols <- cols[!startsWith(cols, "dim_")]
  cols <- cols[!(startsWith(cols, "recipient_") & !tolower(cols) %in% c(
    "recipient_email",
    "recipient_custom_value",
    "recipient_cv_id",
    "recipient_cv_codpulso",
    "recipient_cv_codigo_pucp",
    "recipient_cv_cod_pucp"
  ))]
  cols <- cols[!tolower(cols) %in% technical]
  if (!length(cols)) return(list())
  declared <- .monitoreo_scalar(source$declared_person_code_var %||% "", "")
  rows <- lapply(cols, function(nm) {
    values <- df[[nm]]
    observed <- trimws(as.character(values))
    non_empty <- sum(!is.na(observed) & nzchar(observed))
    examples <- .monitoreo_snapshot_nonempty_values(values, limit = 6L)
    label <- if (is.list(labels) || is.atomic(labels)) {
      label_names <- names(labels) %||% character(0)
      if (nm %in% label_names) .monitoreo_scalar(labels[[nm]], "") else ""
    } else {
      ""
    }
    if (!nzchar(label)) label <- nm
    kind <- .monitoreo_snapshot_variable_kind(nm, label)
    score <- .monitoreo_snapshot_declared_score(nm, label, examples, non_empty, nrow(df))
    list(
      name = nm,
      label = label,
      kind = kind,
      non_empty = as.integer(non_empty),
      total = as.integer(nrow(df)),
      coverage_pct = if (nrow(df) > 0L) as.integer(round(100 * non_empty / nrow(df))) else NA_integer_,
      examples = as.list(examples),
      score = score,
      selected = nzchar(declared) && identical(nm, declared)
    )
  })
  rows <- Filter(function(item) {
    isTRUE(item$selected) || item$non_empty > 0L || item$kind %in% c("pucp", "cell", "email", "name")
  }, rows)
  rows <- rows[order(
    -vapply(rows, function(item) as.integer(isTRUE(item$selected)), integer(1)),
    -vapply(rows, function(item) .monitoreo_int(item$score, 0L), integer(1)),
    vapply(rows, function(item) .monitoreo_scalar(item$label, ""), character(1))
  )]
  rows[seq_len(min(length(rows), max_variables))]
}

.monitoreo_snapshot_collector_config_map <- function(configured) {
  configured <- configured %||% list()
  if (is.data.frame(configured)) {
    configured <- lapply(seq_len(nrow(configured)), function(i) as.list(configured[i, , drop = FALSE]))
  }
  out <- list()
  if (!is.list(configured)) return(out)
  for (item in configured) {
    if (!is.list(item)) next
    source_id <- .monitoreo_scalar(item$source_id, "")
    collector_id <- .monitoreo_scalar(item$collector_id %||% item$collectorId, "")
    if (!nzchar(collector_id)) next
    out[[paste(source_id, collector_id, sep = "::")]] <- item
    if (is.null(out[[collector_id]])) out[[collector_id]] <- item
  }
  out
}

.monitoreo_snapshot_collector_name_is_technical <- function(value, collector_id = "") {
  value <- trimws(.monitoreo_scalar(value, ""))
  collector_id <- trimws(.monitoreo_scalar(collector_id, ""))
  key <- .monitoreo_text_key(value)
  if (!nzchar(key)) return(TRUE)
  if (nzchar(collector_id) && identical(key, .monitoreo_text_key(collector_id))) return(TRUE)
  if (grepl("^\\d{5,}$", key)) return(TRUE)
  if (grepl("^(collector|colector|recopilador|enlace|link|web link)\\s*[:#-]?\\s*\\d{4,}$", key)) return(TRUE)
  FALSE
}

.monitoreo_snapshot_collector_channel <- function(source, saved = NULL) {
  saved <- saved %||% list()
  channel <- .monitoreo_scalar(saved$channel %||% saved$canal, "")
  if (nzchar(channel)) return(channel)
  dims <- source$dimensions %||% list()
  channel <- .monitoreo_scalar(dims$canal %||% dims$channel %||% dims$modalidad %||% source$channel %||% source$canal, "")
  if (nzchar(channel)) return(channel)
  text <- .monitoreo_text_key(paste(source$label %||% "", source$survey_title %||% "", source$survey_id %||% ""))
  if (grepl("whatsapp", text)) return("WhatsApp")
  if (grepl("telefon|phone", text)) return("Telefónico")
  if (grepl("qr|presencial|ficha", text)) return("Ficha QR")
  if (grepl("sms", text)) return("SMS")
  if (grepl("correo|email|mail|web|online", text)) return("Correo")
  "Mixto"
}

.monitoreo_snapshot_collector_use <- function(channel, collector_type = "") {
  key <- .monitoreo_text_key(paste(channel, collector_type))
  if (grepl("telefon|phone", key)) return("telefono_asistido")
  if (grepl("whatsapp", key)) return("enlace_abierto")
  if (grepl("qr|presencial|ficha", key)) return("presencial_qr")
  if (grepl("sms", key)) return("sms")
  if (grepl("correo|email|mail", key)) return("correo_autoaplicado")
  if (grepl("web|link|enlace", key)) return("enlace_abierto")
  "sin_clasificar"
}

.monitoreo_snapshot_collector_modality <- function(channel, use) {
  key <- .monitoreo_text_key(paste(channel, use))
  if (grepl("whatsapp", key)) return("whatsapp")
  if (grepl("sms", key)) return("sms")
  if (grepl("telefon", key)) return("telefono")
  if (grepl("qr|presencial|ficha", key)) return("presencial")
  if (grepl("correo|email|mail", key)) return("email")
  "mixto"
}

.monitoreo_snapshot_source_rows <- function(data, source_id, collector_id = "") {
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(data.frame())
  ok <- rep(TRUE, nrow(data))
  if (nzchar(source_id) && ".source_id" %in% names(data)) ok <- ok & as.character(data$.source_id) == source_id
  if (nzchar(collector_id) && "collector_id" %in% names(data)) ok <- ok & as.character(data$collector_id) == collector_id
  data[ok, , drop = FALSE]
}

.monitoreo_snapshot_collector_records <- function(data, cfg, sources) {
  sources <- monitoreo_normalize_sources(sources)
  saved_map <- .monitoreo_snapshot_collector_config_map((cfg$operational_model %||% list())$link_collectors %||% list())
  configured_collectors <- (cfg$operational_model %||% list())$link_collectors %||% list()
  if (is.data.frame(configured_collectors)) {
    configured_collectors <- lapply(seq_len(nrow(configured_collectors)), function(i) as.list(configured_collectors[i, , drop = FALSE]))
  }
  out <- list()
  for (source in sources) {
    if (!identical(.monitoreo_scalar(source$kind, ""), "surveymonkey")) next
    source_id <- .monitoreo_scalar(source$id, "")
    source_rows <- .monitoreo_snapshot_source_rows(data, source_id)
    collector_ids <- character(0)
    if (nrow(source_rows) && "collector_id" %in% names(source_rows)) {
      collector_ids <- .monitoreo_chr_vec(source_rows$collector_id)
    }
    source_collectors <- .monitoreo_normalize_source_collectors(source$collectors %||% list())
    collector_ids <- unique(c(collector_ids, vapply(source_collectors, function(item) .monitoreo_scalar(item$collector_id %||% item$id, ""), character(1))))
    for (item in configured_collectors) {
      if (!is.list(item) || !identical(.monitoreo_scalar(item$source_id, ""), source_id)) next
      collector_ids <- unique(c(collector_ids, .monitoreo_scalar(item$collector_id, "")))
    }
    collector_ids <- collector_ids[nzchar(collector_ids)]
    for (collector_id in collector_ids) {
      collector_rows <- .monitoreo_snapshot_source_rows(data, source_id, collector_id)
      remote <- Filter(function(item) identical(.monitoreo_scalar(item$collector_id %||% item$id, ""), collector_id), source_collectors)
      remote <- if (length(remote)) remote[[1]] else list()
      saved <- saved_map[[paste(source_id, collector_id, sep = "::")]] %||% saved_map[[collector_id]] %||% list()
      snapshot_name <- ""
      for (col in intersect(c("collector_name", "Nombre recopilador", "nombre_recopilador", "Recopilador", "collector"), names(collector_rows))) {
        values <- .monitoreo_snapshot_nonempty_values(collector_rows[[col]], limit = 1L)
        if (length(values)) {
          snapshot_name <- values[[1]]
          break
        }
      }
      raw_name <- ""
      for (candidate in c(remote$name, snapshot_name, saved$collector_name, saved$label, saved$nombre)) {
        candidate <- .monitoreo_scalar(candidate, "")
        if (nzchar(candidate)) {
          raw_name <- candidate
          break
        }
      }
      channel <- .monitoreo_snapshot_collector_channel(source, saved)
      derived <- paste(Filter(nzchar, c(
        .monitoreo_scalar((source$dimensions %||% list())$actor %||% (source$dimensions %||% list())$segmento, ""),
        channel
      )), collapse = " · ")
      collector_name <- if (!.monitoreo_snapshot_collector_name_is_technical(raw_name, collector_id)) raw_name else derived
      if (!nzchar(collector_name)) collector_name <- raw_name
      if (!nzchar(collector_name)) collector_name <- paste("Recopilador", collector_id)
      collector_type <- .monitoreo_scalar(remote$type %||% saved$collector_type, "")
      operational_use <- .monitoreo_scalar(saved$operational_use %||% saved$uso_operativo, "")
      suggested_use <- .monitoreo_snapshot_collector_use(channel, collector_type)
      if (!operational_use %in% c("correo_autoaplicado", "telefono_asistido", "presencial_qr", "enlace_abierto", "sms", "mixto", "sin_clasificar")) {
        operational_use <- suggested_use
      }
      modality <- .monitoreo_scalar(saved$modality %||% saved$modalidad, .monitoreo_snapshot_collector_modality(channel, operational_use))
      recipient_total <- if ("recipient_id" %in% names(collector_rows)) length(.monitoreo_snapshot_nonempty_values(collector_rows$recipient_id, limit = Inf)) else 0L
      link_count <- if ("recipient_id" %in% names(collector_rows)) recipient_total else 0L
      out[[length(out) + 1L]] <- list(
        id = paste(source_id, collector_id, sep = "::"),
        source_id = source_id,
        source_label = .monitoreo_scalar(source$label, ""),
        survey_id = .monitoreo_scalar(source$survey_id, ""),
        collector_id = collector_id,
        collector_name = collector_name,
        collector_type = collector_type,
        enabled = .monitoreo_bool(saved$enabled %||% saved$activo %||% saved$included %||% saved$incluido, TRUE),
        channel = channel,
        operational_use = operational_use,
        configured_use = operational_use,
        suggested_use = suggested_use,
        modality = modality,
        roster_required = .monitoreo_bool(saved$roster_required %||% saved$requiere_base_casos, identical(operational_use, "telefono_asistido")),
        response_count = as.integer(nrow(collector_rows)),
        active_response_count = as.integer(nrow(collector_rows)),
        recipient_summary = list(
          available = FALSE,
          total = as.integer(recipient_total),
          scanned = 0L,
          truncated = FALSE,
          personalized_link_count = as.integer(link_count),
          mail_status_counts = list(),
          response_status_counts = if ("response_status" %in% names(collector_rows)) {
            table_values <- trimws(as.character(collector_rows$response_status %||% character(0)))
            table_values <- table_values[!is.na(table_values) & nzchar(table_values)]
            tab <- sort(table(table_values), decreasing = TRUE)
            stats::setNames(as.list(as.integer(tab)), names(tab))
          } else {
            list()
          }
        ),
        url_present = nzchar(.monitoreo_scalar(remote$url, "")),
        warnings = list(),
        metadata_source = if (length(remote)) "surveymonkey_sync" else if (nrow(collector_rows)) "responses_snapshot" else "config"
      )
    }
  }
  out
}

.monitoreo_snapshot_source_metadata <- function(data, cfg, sources, generated_at = .monitoreo_now_iso(), sync_summary = list()) {
  sources <- monitoreo_normalize_sources(sources)
  surveys <- list()
  variables_by_source <- list()
  for (source in sources) {
    source_id <- .monitoreo_scalar(source$id, "")
    if (!nzchar(source_id)) next
    source_rows <- .monitoreo_snapshot_source_rows(data, source_id)
    variables_by_source[[source_id]] <- .monitoreo_snapshot_variable_stats_for_source(data, source_id, source)
    if (identical(.monitoreo_scalar(source$kind, ""), "surveymonkey")) {
      surveys[[source_id]] <- list(
        source_id = source_id,
        survey_id = .monitoreo_scalar(source$survey_id, ""),
        title = .monitoreo_scalar(source$survey_title %||% source$label, ""),
        label = .monitoreo_scalar(source$label, ""),
        actor = .monitoreo_scalar((source$dimensions %||% list())$actor %||% (source$dimensions %||% list())$segmento, ""),
        channel = .monitoreo_snapshot_collector_channel(source),
        response_count = as.integer(nrow(source_rows)),
        declared_person_code_var = .monitoreo_scalar(source$declared_person_code_var, ""),
        declared_person_code_label = .monitoreo_scalar(source$declared_person_code_label, ""),
        collector_count = as.integer(length(.monitoreo_normalize_source_collectors(source$collectors %||% list())))
      )
    }
  }
  list(
    schema = "monitoreo_source_metadata_v1",
    generated_at = generated_at,
    source_count = as.integer(length(sources)),
    survey_count = as.integer(length(surveys)),
    sources = lapply(sources, function(source) {
      list(
        id = .monitoreo_scalar(source$id, ""),
        kind = .monitoreo_scalar(source$kind, ""),
        label = .monitoreo_scalar(source$label, ""),
        survey_id = .monitoreo_scalar(source$survey_id, ""),
        survey_title = .monitoreo_scalar(source$survey_title, ""),
        last_sync_at = .monitoreo_scalar(source$last_sync_at, ""),
        last_sync_mode = .monitoreo_scalar(source$last_sync_mode, ""),
        role = .monitoreo_scalar(source$role, "")
      )
    }),
    surveys = surveys,
    collectors = .monitoreo_snapshot_collector_records(data, cfg, sources),
    variables_by_source = variables_by_source,
    sync_summary = sync_summary %||% list()
  )
}

.monitoreo_snapshot_report_bundle <- function(dashboard, family = "") {
  dashboard <- dashboard %||% list()
  family <- .monitoreo_scalar(family, "")
  if (identical(family, "territorial")) return(dashboard$territorial_reports %||% list())
  if (identical(family, "aulas_universitarias")) return(dashboard$aulas_universitarias_reports %||% list())
  dashboard$acreditacion_reports %||% list()
}

.monitoreo_snapshot_chart_model_for_audience <- function(data, cfg, dashboard, synced_at, audience = "client") {
  model <- monitoreo_publication_model(
    data,
    cfg,
    audience = audience,
    include_targets = identical(audience, "internal"),
    dashboard = dashboard,
    synced_at = synced_at,
    context = list(source = "monitoreo_snapshot")
  )
  visual <- tryCatch(
    extract_app_visual_progress_model(model, updated = synced_at, updated_label = synced_at),
    error = function(e) list(error = conditionMessage(e))
  )
  daily <- model$daily_progress %||% list()
  empty <- daily$empty_state %||% list()
  empty_reason <- .monitoreo_scalar(empty$general %||% empty$date %||% empty$status %||% "", "")
  list(
    schema = "monitoreo_chart_model_audience_v1",
    audience = audience,
    generated_at = .monitoreo_scalar(model$generated_at, .monitoreo_now_iso()),
    family = .monitoreo_scalar(model$family, ""),
    daily_progress = daily,
    accreditation_progress = model$accreditation_progress %||% NULL,
    visual_progress = visual,
    empty_reason = empty_reason
  )
}

.monitoreo_snapshot_chart_models <- function(data, cfg, dashboard, synced_at = "", generated_at = .monitoreo_now_iso()) {
  client <- tryCatch(
    .monitoreo_snapshot_chart_model_for_audience(data, cfg, dashboard, synced_at, "client"),
    error = function(e) list(schema = "monitoreo_chart_model_audience_v1", audience = "client", error = conditionMessage(e), empty_reason = "no se pudo generar modelo cliente")
  )
  internal <- tryCatch(
    .monitoreo_snapshot_chart_model_for_audience(data, cfg, dashboard, synced_at, "internal"),
    error = function(e) list(schema = "monitoreo_chart_model_audience_v1", audience = "internal", error = conditionMessage(e), empty_reason = "no se pudo generar modelo interno")
  )
  list(
    schema = "monitoreo_chart_models_v1",
    generated_at = generated_at,
    client = client,
    internal = internal,
    daily_progress = client$daily_progress %||% internal$daily_progress %||% list(),
    empty_reason = .monitoreo_scalar(client$empty_reason %||% internal$empty_reason, "")
  )
}

monitoreo_snapshot_artifacts <- function(data,
                                         config = list(),
                                         sources = list(),
                                         dashboard = NULL,
                                         synced_at = "",
                                         errors = list(),
                                         sync_summary = list(),
                                         generated_at = .monitoreo_now_iso()) {
  if (is.null(data) || !is.data.frame(data)) data <- data.frame()
  cfg <- monitoreo_normalize_config(config, data)
  if (is.null(dashboard) || !is.list(dashboard)) {
    dashboard <- tryCatch(monitoreo_build_dashboard(data, cfg, include_reports = TRUE), error = function(e) list(ok = FALSE, error = conditionMessage(e)))
  }
  family <- cfg$monitoreo_profile$family %||% detect_monitoreo_family(config = cfg, data = data)
  source_metadata <- tryCatch(
    .monitoreo_snapshot_source_metadata(data, cfg, sources, generated_at = generated_at, sync_summary = sync_summary),
    error = function(e) list(schema = "monitoreo_source_metadata_v1", generated_at = generated_at, error = conditionMessage(e))
  )
  reports <- tryCatch(.monitoreo_snapshot_report_bundle(dashboard, family), error = function(e) list(error = conditionMessage(e)))
  chart_models <- tryCatch(
    .monitoreo_snapshot_chart_models(data, cfg, dashboard, synced_at = synced_at, generated_at = generated_at),
    error = function(e) list(schema = "monitoreo_chart_models_v1", generated_at = generated_at, error = conditionMessage(e), empty_reason = "fallo al generar modelos de graficos")
  )
  has_errors <- length(errors %||% list()) > 0L ||
    nzchar(.monitoreo_scalar(source_metadata$error %||% "", "")) ||
    nzchar(.monitoreo_scalar(chart_models$error %||% "", ""))
  status <- if (isTRUE(has_errors)) "partial" else "complete"
  list(
    generated_at = generated_at,
    generation_version = "monitoreo_snapshot_v2",
    generation_status = status,
    source_metadata = source_metadata,
    reports = reports,
    chart_models = chart_models,
    sync_errors = errors %||% list()
  )
}

.monitoreo_parse_time_vec <- function(x) {
  if (is.null(x)) return(as.POSIXct(rep(NA_real_, 0), origin = "1970-01-01", tz = "UTC"))
  if (inherits(x, "POSIXt")) return(as.POSIXct(x, tz = "UTC"))
  if (inherits(x, "Date")) return(as.POSIXct(x, tz = "UTC"))
  ch <- as.character(x)
  out <- as.POSIXct(rep(NA_real_, length(ch)), origin = "1970-01-01", tz = "UTC")
  candidates <- list(
    ch,
    sub("Z$", "+0000", ch),
    sub("([+-][0-9]{2}):([0-9]{2})$", "\\1\\2", ch, perl = TRUE)
  )
  fmts <- c(
    "%Y-%m-%dT%H:%M:%OS%z",
    "%Y-%m-%dT%H:%M:%S%z",
    "%Y-%m-%dT%H:%M:%OSZ",
    "%Y-%m-%dT%H:%M:%SZ",
    "%Y-%m-%dT%H:%M:%OS",
    "%Y-%m-%dT%H:%M:%S",
    "%Y-%m-%dT%H:%M",
    "%Y-%m-%d %H:%M:%OS",
    "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%d %H:%M",
    "%Y-%m-%d"
  )
  safe_parse <- function(value, fmt) {
    tryCatch(
      suppressWarnings(as.POSIXct(value, format = fmt, tz = "UTC")),
      error = function(e) as.POSIXct(rep(NA_real_, length(value)), origin = "1970-01-01", tz = "UTC")
    )
  }
  for (fmt in fmts) {
    for (candidate in candidates) {
      idx <- is.na(out) & !is.na(candidate) & nzchar(candidate)
      if (!any(idx)) next
      parsed <- safe_parse(candidate[idx], fmt)
      idx_pos <- which(idx)
      ok <- !is.na(parsed)
      if (any(ok)) out[idx_pos[ok]] <- parsed[ok]
    }
  }
  out
}

.monitoreo_datetime_display_tz <- function(raw) {
  raw <- trimws(as.character(raw %||% ""))
  raw[is.na(raw)] <- ""
  has_zone <- grepl("(Z|[+-][0-9]{2}:?[0-9]{2})$", raw, perl = TRUE)
  ifelse(has_zone, "America/Lima", "UTC")
}

.monitoreo_datetime_has_clock <- function(raw, n) {
  if (is.null(raw)) return(rep(TRUE, n))
  raw <- trimws(as.character(raw %||% ""))
  raw[is.na(raw)] <- ""
  grepl("([T[:space:]][0-9]{1,2}:[0-9]{2})", raw, perl = TRUE)
}

.monitoreo_datetime_has_meaningful_clock <- function(raw, parsed = NULL) {
  raw <- trimws(as.character(raw %||% ""))
  raw[is.na(raw)] <- ""
  n <- length(raw)
  if (is.null(parsed)) parsed <- .monitoreo_parse_time_vec(raw)
  has_clock <- .monitoreo_datetime_has_clock(raw, n)
  clock_text <- rep("", n)
  hit <- regexpr("([T[:space:]][0-9]{1,2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]+)?)?)", raw, perl = TRUE)
  ok_hit <- hit > 0
  matches <- regmatches(raw, hit)
  if (length(matches)) clock_text[ok_hit] <- trimws(sub("^[T[:space:]]+", "", matches))
  clock_text <- sub("\\.[0-9]+$", "", clock_text)
  !is.na(parsed) & has_clock & nzchar(clock_text) & !grepl("^0?0:00(:00)?$", clock_text)
}

.monitoreo_territorial_submission_time_values <- function(data, tcfg) {
  n <- if (is.data.frame(data)) nrow(data) else 0L
  empty <- rep("", n)
  if (!n || is.null(data) || !is.data.frame(data)) return(list(values = empty, source = ""))
  candidates <- c(
    "kobo_timestamp_iso",
    .monitoreo_scalar(tcfg$submission_time_var, ""),
    "_submission_time", "submission_time", "submitted_at", "date_submitted",
    .monitoreo_scalar(tcfg$end_var, ""),
    .monitoreo_scalar(tcfg$start_var, ""),
    "end", "end_time", "start", "start_time",
    "date_modified", "date_created"
  )
  candidates <- unique(candidates[nzchar(candidates) & candidates %in% names(data)])
  if (!length(candidates)) return(list(values = empty, source = ""))

  score_candidate <- function(col) {
    raw <- trimws(as.character(data[[col]] %||% ""))
    raw[is.na(raw)] <- ""
    if (length(raw) != n) raw <- rep(raw, length.out = n)
    parsed <- .monitoreo_parse_time_vec(raw)
    clock <- .monitoreo_datetime_has_clock(raw, n)
    meaningful <- .monitoreo_datetime_has_meaningful_clock(raw, parsed)
    hour <- .monitoreo_format_time_label_vec(parsed, raw)
    distinct_hour <- length(unique(hour[nzchar(hour)]))
    c(
      meaningful = sum(meaningful, na.rm = TRUE),
      distinct_hour = distinct_hour,
      clock = sum(clock & !is.na(parsed), na.rm = TRUE),
      parsed = sum(!is.na(parsed), na.rm = TRUE),
      non_empty = sum(nzchar(raw), na.rm = TRUE)
    )
  }

  scores <- t(vapply(candidates, score_candidate, numeric(5)))
  preferred <- unique(c(
    "kobo_timestamp_iso",
    .monitoreo_scalar(tcfg$submission_time_var, ""),
    "_submission_time", "submission_time", "submitted_at", "date_submitted"
  ))
  best <- ""
  for (col in preferred[nzchar(preferred)]) {
    idx <- match(col, candidates)
    if (is.na(idx)) next
    if (scores[idx, "parsed"] > 0 && scores[idx, "non_empty"] > 0) {
      best <- col
      break
    }
  }
  if (!nzchar(best)) {
    order_idx <- order(
      -scores[, "meaningful"],
      -scores[, "distinct_hour"],
      -scores[, "clock"],
      -scores[, "parsed"],
      -scores[, "non_empty"],
      seq_along(candidates)
    )
    best <- candidates[[order_idx[[1]]]]
  }
  values <- trimws(as.character(data[[best]] %||% ""))
  values[is.na(values)] <- ""
  if (length(values) != n) values <- rep(values, length.out = n)
  list(values = values, source = best)
}

.monitoreo_format_date_label_vec <- function(parsed, raw = NULL) {
  parsed <- as.POSIXct(parsed, origin = "1970-01-01", tz = "UTC")
  out <- rep("", length(parsed))
  ok <- !is.na(parsed)
  if (!any(ok)) return(out)
  months <- c("Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
              "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre")
  tzs <- if (is.null(raw)) rep("UTC", length(parsed)) else .monitoreo_datetime_display_tz(raw)
  for (tz in unique(tzs[ok])) {
    idx <- ok & tzs == tz
    parts <- as.POSIXlt(parsed[idx], tz = tz)
    out[idx] <- paste(parts$mday, months[pmax(1L, pmin(12L, parts$mon + 1L))])
  }
  out
}

.monitoreo_format_time_label_vec <- function(parsed, raw = NULL) {
  parsed <- as.POSIXct(parsed, origin = "1970-01-01", tz = "UTC")
  out <- rep("", length(parsed))
  ok <- !is.na(parsed) & .monitoreo_datetime_has_clock(raw, length(parsed))
  if (!any(ok)) return(out)
  tzs <- if (is.null(raw)) rep("UTC", length(parsed)) else .monitoreo_datetime_display_tz(raw)
  for (tz in unique(tzs[ok])) {
    idx <- ok & tzs == tz
    out[idx] <- tolower(format(parsed[idx], "%I:%M%p", tz = tz))
  }
  out
}

.monitoreo_date_iso_vec <- function(parsed, raw = NULL) {
  parsed <- as.POSIXct(parsed, origin = "1970-01-01", tz = "UTC")
  out <- rep("", length(parsed))
  ok <- !is.na(parsed)
  if (!any(ok)) return(out)
  tzs <- if (is.null(raw)) rep("UTC", length(parsed)) else .monitoreo_datetime_display_tz(raw)
  for (tz in unique(tzs[ok])) {
    idx <- ok & tzs == tz
    out[idx] <- as.character(as.Date(parsed[idx], tz = tz))
  }
  out
}

.monitoreo_timestamp_iso_vec <- function(parsed) {
  parsed <- as.POSIXct(parsed, origin = "1970-01-01", tz = "UTC")
  out <- rep("", length(parsed))
  ok <- !is.na(parsed)
  out[ok] <- format(parsed[ok], "%Y-%m-%dT%H:%M:%SZ", tz = "UTC")
  out
}

.monitoreo_format_datetime_label_vec <- function(parsed, raw = NULL) {
  date <- .monitoreo_format_date_label_vec(parsed, raw)
  time <- .monitoreo_format_time_label_vec(parsed, raw)
  out <- trimws(paste(date, time))
  out[!nzchar(out)] <- ""
  out
}

.monitoreo_kobo_timestamp_col <- function(data) {
  if (is.null(data) || !is.data.frame(data) || !length(names(data))) return("")
  priority <- c(
    "_submission_time", "submission_time", "submitted_at", "date_submitted",
    "end", "end_time", "start", "start_time",
    "date_modified", "date_created", "modified_at", "created_at"
  )
  clean_names <- .monitoreo_text_key(names(data))
  clean_priority <- .monitoreo_text_key(priority)
  for (alias in clean_priority) {
    hit <- which(clean_names == alias)
    if (length(hit)) return(names(data)[hit[[1]]])
  }
  for (alias in clean_priority) {
    hit <- which(grepl(alias, clean_names, fixed = TRUE))
    if (length(hit)) return(names(data)[hit[[1]]])
  }
  ""
}

monitoreo_enrich_kobo_datetime_columns <- function(data) {
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(data)
  labels <- .monitoreo_variable_label_map(data)
  col <- .monitoreo_kobo_timestamp_col(data)
  if (!nzchar(col) || !col %in% names(data)) return(data)
  raw <- trimws(as.character(data[[col]]))
  raw[is.na(raw)] <- ""
  parsed <- .monitoreo_parse_time_vec(raw)
  if (!any(!is.na(parsed))) return(data)
  data$kobo_timestamp_iso <- .monitoreo_timestamp_iso_vec(parsed)
  data$kobo_fecha_iso <- .monitoreo_date_iso_vec(parsed, raw)
  data$kobo_fecha <- .monitoreo_format_date_label_vec(parsed, raw)
  data$kobo_hora <- .monitoreo_format_time_label_vec(parsed, raw)
  data$kobo_fecha_hora <- .monitoreo_format_datetime_label_vec(parsed, raw)
  labels <- c(labels, c(
    kobo_timestamp_iso = "Timestamp Kobo normalizado",
    kobo_fecha_iso = "Fecha Kobo ISO",
    kobo_fecha = "Fecha Kobo",
    kobo_hora = "Hora Kobo",
    kobo_fecha_hora = "Fecha y hora Kobo"
  ))
  .monitoreo_restore_variable_labels(data, labels)
}

.monitoreo_duration_seconds <- function(data, cfg) {
  n <- nrow(data)
  if (n == 0L) return(numeric(0))
  dur_var <- cfg$duration_var
  if (nzchar(dur_var) && dur_var %in% names(data)) {
    val <- suppressWarnings(as.numeric(data[[dur_var]]))
    return(val)
  }
  if (nzchar(cfg$start_var) && nzchar(cfg$end_var) &&
      cfg$start_var %in% names(data) && cfg$end_var %in% names(data)) {
    st <- .monitoreo_parse_time_vec(data[[cfg$start_var]])
    en <- .monitoreo_parse_time_vec(data[[cfg$end_var]])
    return(as.numeric(difftime(en, st, units = "secs")))
  }
  rep(NA_real_, n)
}

.monitoreo_valid_mask <- function(data, cfg) {
  if (!nrow(data)) return(logical(0))
  status_var <- cfg$status_var
  if (!nzchar(status_var) || !status_var %in% names(data)) return(rep(TRUE, nrow(data)))
  valid <- tolower(.monitoreo_chr_vec(cfg$valid_statuses))
  if (!length(valid)) return(rep(TRUE, nrow(data)))
  tolower(trimws(as.character(data[[status_var]]))) %in% valid
}

.monitoreo_empty_mask <- function(x) {
  is.na(x) | !nzchar(trimws(as.character(x)))
}

.monitoreo_goal_meta_for_row <- function(row, goals) {
  if (!length(goals)) return(NA_integer_)
  total <- 0L
  matched <- FALSE
  for (g in goals) {
    filters <- g$filters %||% list()
    ok <- TRUE
    for (nm in names(filters)) {
      if (!nm %in% names(row) || !identical(as.character(row[[nm]]), as.character(filters[[nm]]))) {
        ok <- FALSE
        break
      }
    }
    if (ok) {
      total <- total + as.integer(g$meta %||% 0L)
      matched <- TRUE
    }
  }
  if (matched) total else NA_integer_
}

.monitoreo_territorial_rows_df <- function(rows) {
  if (is.null(rows) || !length(rows)) return(data.frame())
  if (is.data.frame(rows)) {
    out <- rows
    rownames(out) <- NULL
    return(out)
  }
  if (exists(".hojas_ruta_rows_df", mode = "function")) {
    out <- tryCatch(.hojas_ruta_rows_df(rows), error = function(e) data.frame())
    if (is.data.frame(out)) return(out)
  }
  rows <- rows[!vapply(rows, is.null, logical(1))]
  if (!length(rows)) return(data.frame())
  fields <- unique(unlist(lapply(rows, names), use.names = FALSE))
  fields <- fields[nzchar(fields)]
  if (!length(fields)) return(data.frame())
  out <- do.call(rbind, lapply(rows, function(row) {
    row <- row %||% list()
    as.data.frame(as.list(vapply(fields, function(field) {
      value <- row[[field]]
      if (is.null(value) || !length(value)) return(NA_character_)
      if (is.data.frame(value) || (is.list(value) && !is.atomic(value))) {
        return(as.character(jsonlite::toJSON(value, dataframe = "rows", auto_unbox = TRUE, null = "null", na = "null")))
      }
      .monitoreo_scalar(value, NA_character_)
    }, character(1))), stringsAsFactors = FALSE)
  }))
  rownames(out) <- NULL
  out
}

.monitoreo_territorial_df_rows <- function(df) {
  if (is.null(df) || !is.data.frame(df) || !nrow(df)) return(list())
  unname(lapply(seq_len(nrow(df)), function(i) {
    row <- as.list(df[i, , drop = FALSE])
    lapply(row, function(v) {
      if (length(v) == 0L) return(NA)
      v <- v[[1]]
      if (is.factor(v)) as.character(v) else v
    })
  }))
}

.monitoreo_territorial_block_id_variants <- function(id) {
  id <- trimws(as.character(id %||% ""))
  id <- id[!is.na(id) & nzchar(id)]
  if (!length(id)) return(character(0))
  variants <- unique(c(id, sub("0$", "", id, perl = TRUE)))
  variants[!is.na(variants) & nzchar(variants)]
}

.monitoreo_territorial_feature_id_col <- function(features) {
  intersect(c("IDMANZANA", "id_manzana_norm", "id_manzana", "ID_MANZANA", "IDMZNAR", "cartografia_id"), names(features))[1]
}

.monitoreo_territorial_resolve_blocks <- function(blocks, features = NULL) {
  blocks <- .monitoreo_territorial_rows_df(blocks)
  if (!nrow(blocks)) return(blocks)
  for (col in c("id_manzana", "ubigeo", "zona", "manzana", "distrito", "entrevistas", "tipo_manzana")) {
    if (!col %in% names(blocks)) blocks[[col]] <- ""
  }
  blocks$resolved_id_manzana <- ""
  blocks$match_method <- "geometry_unresolved"
  blocks$geometry_unresolved <- TRUE
  if (is.null(features) || !is.data.frame(features) || !nrow(features)) return(blocks)
  id_col <- .monitoreo_territorial_feature_id_col(features)
  if (is.na(id_col) || !nzchar(id_col)) return(blocks)
  feature_ids <- trimws(as.character(features[[id_col]]))
  feature_norm <- sub("0$", "", feature_ids, perl = TRUE)
  feature_zona <- trimws(as.character(features$CODZONA %||% features$zona %||% features$ZONA %||% ""))
  feature_manzana <- trimws(as.character(features$CODMZNA %||% features$manzana %||% features$MANZANA %||% ""))
  feature_ubigeo <- trimws(as.character(features$UBIGEO %||% features$ubigeo %||% ""))
  for (i in seq_len(nrow(blocks))) {
    original_id <- trimws(as.character(blocks$id_manzana[[i]] %||% ""))
    normalized_id <- sub("0$", "", original_id, perl = TRUE)
    idx <- match(original_id, feature_ids, nomatch = 0L)
    method <- "id_manzana_exact"
    if (is.na(idx) || !is.finite(idx) || idx <= 0L) {
      idx <- match(normalized_id, feature_ids, nomatch = 0L)
      if (is.na(idx) || !is.finite(idx) || idx <= 0L) {
        idx <- match(normalized_id, feature_norm, nomatch = 0L)
      }
      method <- "id_manzana_drop_operational_zero"
    }
    if (is.na(idx) || !is.finite(idx) || idx <= 0L) {
      key <- paste(trimws(as.character(blocks$ubigeo[[i]])), trimws(as.character(blocks$zona[[i]])), trimws(as.character(blocks$manzana[[i]])), sep = "\r")
      feature_key <- paste(feature_ubigeo, feature_zona, feature_manzana, sep = "\r")
      idx <- match(key, feature_key, nomatch = 0L)
      method <- "ubigeo_zona_manzana"
    }
    if (!is.na(idx) && is.finite(idx) && idx > 0L) {
      blocks$resolved_id_manzana[[i]] <- feature_ids[[idx]]
      blocks$match_method[[i]] <- method
      blocks$geometry_unresolved[[i]] <- FALSE
    }
  }
  blocks
}

.monitoreo_territorial_parse_gps_cell <- function(value) {
  empty <- c(lat = NA_real_, lon = NA_real_, altitude = NA_real_, accuracy_m = NA_real_)
  if (is.null(value) || !length(value)) return(empty)
  if (is.list(value) && !is.data.frame(value)) value <- unlist(value, use.names = FALSE)
  if (is.numeric(value) && length(value) >= 2L) {
    lat <- suppressWarnings(as.numeric(value[[1]]))
    lon <- suppressWarnings(as.numeric(value[[2]]))
    altitude <- if (length(value) >= 3L) suppressWarnings(as.numeric(value[[3]])) else NA_real_
    accuracy <- if (length(value) >= 4L) suppressWarnings(as.numeric(value[[4]])) else NA_real_
    if (is.finite(lat) && is.finite(lon)) return(c(lat = lat, lon = lon, altitude = altitude, accuracy_m = accuracy))
  }
  ch <- trimws(as.character(value[[1]] %||% ""))
  if (!nzchar(ch) || is.na(ch)) return(empty)
  if (grepl("^\\[|^\\{", ch)) {
    parsed <- tryCatch(jsonlite::fromJSON(ch, simplifyVector = TRUE), error = function(e) NULL)
    if (!is.null(parsed)) {
      vals <- suppressWarnings(as.numeric(unlist(parsed, use.names = FALSE)))
      vals <- vals[is.finite(vals)]
      if (length(vals) >= 2L) {
        return(c(
          lat = vals[[1]],
          lon = vals[[2]],
          altitude = if (length(vals) >= 3L) vals[[3]] else NA_real_,
          accuracy_m = if (length(vals) >= 4L) vals[[4]] else NA_real_
        ))
      }
    }
  }
  nums <- regmatches(ch, gregexpr("-?[0-9]+(?:[.][0-9]+)?", ch, perl = TRUE))[[1]]
  vals <- suppressWarnings(as.numeric(nums))
  vals <- vals[is.finite(vals)]
  if (length(vals) < 2L) return(empty)
  lat <- vals[[1]]
  lon <- vals[[2]]
  if (abs(lat) > 90 && abs(lon) <= 90) {
    tmp <- lat
    lat <- lon
    lon <- tmp
  }
  c(
    lat = lat,
    lon = lon,
    altitude = if (length(vals) >= 3L) vals[[3]] else NA_real_,
    accuracy_m = if (length(vals) >= 4L) vals[[4]] else NA_real_
  )
}

.monitoreo_territorial_gps_df <- function(data, gps_var, ref = NULL) {
  n <- nrow(data)
  gps_col <- .monitoreo_territorial_resolve_data_col(data, gps_var, ref = ref)
  if (!n || !nzchar(gps_col)) {
    return(data.frame(
      lat = rep(NA_real_, n),
      lon = rep(NA_real_, n),
      gps_altitude = rep(NA_real_, n),
      gps_accuracy_m = rep(NA_real_, n),
      gps_source_var = rep(.monitoreo_scalar(gps_var, ""), n),
      stringsAsFactors = FALSE
    ))
  }
  vals <- lapply(data[[gps_col]], .monitoreo_territorial_parse_gps_cell)
  data.frame(
    lat = vapply(vals, `[[`, numeric(1), "lat"),
    lon = vapply(vals, `[[`, numeric(1), "lon"),
    gps_altitude = vapply(vals, `[[`, numeric(1), "altitude"),
    gps_accuracy_m = vapply(vals, `[[`, numeric(1), "accuracy_m"),
    gps_source_var = rep(gps_col, n),
    stringsAsFactors = FALSE
  )
}

.monitoreo_territorial_geo_severity <- function(state) {
  key <- .monitoreo_text_key(.monitoreo_scalar(state, ""))
  if (key %in% c("geo_ok", "geo_cerca")) return(0L)
  if (identical(key, "geo_revision")) return(1L)
  if (key %in% c("geo_no_defendible", "geo_sin_cruce")) return(2L)
  3L
}

.monitoreo_territorial_geo_alternate_improves <- function(current_state,
                                                          current_distance,
                                                          alternate_state,
                                                          alternate_distance,
                                                          alternate_accuracy,
                                                          max_accuracy = 100) {
  acc <- suppressWarnings(as.numeric(.monitoreo_scalar(alternate_accuracy, NA_real_)))
  if (!is.finite(acc) || acc > max_accuracy) return(FALSE)
  current_sev <- .monitoreo_territorial_geo_severity(current_state)
  alternate_sev <- .monitoreo_territorial_geo_severity(alternate_state)
  if (alternate_sev < current_sev) return(TRUE)
  if (!identical(alternate_sev, current_sev)) return(FALSE)
  current_dist <- suppressWarnings(as.numeric(.monitoreo_scalar(current_distance, NA_real_)))
  alternate_dist <- suppressWarnings(as.numeric(.monitoreo_scalar(alternate_distance, NA_real_)))
  if (!is.finite(current_dist)) current_dist <- Inf
  if (!is.finite(alternate_dist)) alternate_dist <- Inf
  alternate_dist < current_dist
}

.monitoreo_territorial_geo_enrich_effective <- function(out, primary_source = "") {
  if (!is.data.frame(out)) return(out)
  n <- nrow(out)
  chr_default <- function(col, default = "") {
    if (col %in% names(out)) {
      x <- as.character(out[[col]])
      x[is.na(x)] <- default
      x
    } else {
      rep(default, n)
    }
  }
  num_default <- function(col, default = NA_real_) {
    if (col %in% names(out)) {
      x <- suppressWarnings(as.numeric(out[[col]]))
      x[is.na(x)] <- default
      x
    } else {
      rep(default, n)
    }
  }
  bool_default <- function(col, default = FALSE) {
    if (col %in% names(out)) {
      x <- out[[col]] %in% TRUE
      x[is.na(x)] <- default
      x
    } else {
      rep(default, n)
    }
  }
  source <- chr_default("gps_source_var", .monitoreo_scalar(primary_source, ""))
  if (!"gps_altitude" %in% names(out)) out$gps_altitude <- rep(NA_real_, n)
  if (!"gps_accuracy_m" %in% names(out)) out$gps_accuracy_m <- rep(NA_real_, n)
  if (!"gps_primary_source" %in% names(out)) out$gps_primary_source <- source
  if (!"gps_primary_lat" %in% names(out)) out$gps_primary_lat <- num_default("lat")
  if (!"gps_primary_lon" %in% names(out)) out$gps_primary_lon <- num_default("lon")
  if (!"gps_primary_altitude" %in% names(out)) out$gps_primary_altitude <- num_default("gps_altitude")
  if (!"gps_primary_accuracy_m" %in% names(out)) out$gps_primary_accuracy_m <- num_default("gps_accuracy_m")
  if (!"gps_primary_parseable" %in% names(out)) out$gps_primary_parseable <- bool_default("gps_parseable")
  if (!"gps_primary_estado" %in% names(out)) out$gps_primary_estado <- chr_default("geo_estado", "geo_sin_gps")
  if (!"gps_primary_distance_m" %in% names(out)) out$gps_primary_distance_m <- num_default("distance_m")
  if (!"gps_primary_nearest_block_id" %in% names(out)) out$gps_primary_nearest_block_id <- chr_default("nearest_block_id")
  if (!"gps_primary_nearest_block_type" %in% names(out)) out$gps_primary_nearest_block_type <- chr_default("nearest_block_type")
  if (!"gps_primary_geometry_match" %in% names(out)) out$gps_primary_geometry_match <- chr_default("geometry_match")
  if (!"gps_effective_source" %in% names(out)) out$gps_effective_source <- source
  if (!"gps_effective_lat" %in% names(out)) out$gps_effective_lat <- num_default("lat")
  if (!"gps_effective_lon" %in% names(out)) out$gps_effective_lon <- num_default("lon")
  if (!"gps_effective_altitude" %in% names(out)) out$gps_effective_altitude <- num_default("gps_altitude")
  if (!"gps_effective_accuracy_m" %in% names(out)) out$gps_effective_accuracy_m <- num_default("gps_accuracy_m")
  if (!"gps_effective_estado" %in% names(out)) out$gps_effective_estado <- chr_default("geo_estado", "geo_sin_gps")
  if (!"gps_effective_distance_m" %in% names(out)) out$gps_effective_distance_m <- num_default("distance_m")
  if (!"gps_effective_nearest_block_id" %in% names(out)) out$gps_effective_nearest_block_id <- chr_default("nearest_block_id")
  if (!"gps_effective_nearest_block_type" %in% names(out)) out$gps_effective_nearest_block_type <- chr_default("nearest_block_type")
  if (!"gps_effective_geometry_match" %in% names(out)) out$gps_effective_geometry_match <- chr_default("geometry_match")
  if (!"gps_reclassified" %in% names(out)) out$gps_reclassified <- rep(FALSE, n)
  if (!"gps_reclassification_note" %in% names(out)) out$gps_reclassification_note <- rep("", n)
  numeric_cols <- c(
    "lat", "lon", "distance_m", "gps_altitude", "gps_accuracy_m",
    "gps_primary_lat", "gps_primary_lon", "gps_primary_altitude", "gps_primary_accuracy_m", "gps_primary_distance_m",
    "gps_effective_lat", "gps_effective_lon", "gps_effective_altitude", "gps_effective_accuracy_m", "gps_effective_distance_m"
  )
  for (col in intersect(numeric_cols, names(out))) {
    out[[col]] <- suppressWarnings(as.numeric(out[[col]]))
  }
  bool_cols <- c("gps_parseable", "gps_primary_parseable", "gps_reclassified")
  for (col in intersect(bool_cols, names(out))) {
    out[[col]] <- out[[col]] %in% TRUE
  }
  out
}

.monitoreo_territorial_field_candidates <- function(value = "", ref = NULL) {
  out <- character(0)
  add <- function(x) {
    x <- .monitoreo_chr_vec(x)
    if (length(x)) out <<- c(out, x)
  }
  pulso_aliases <- function(x) {
    x <- .monitoreo_chr_vec(x)
    aliases <- character(0)
    for (item in x) {
      item <- trimws(as.character(item %||% ""))
      if (!nzchar(item)) next
      parts <- strsplit(gsub("\\\\", "/", item), "[/.]")[[1]]
      last <- .monitoreo_safe_name(parts[[length(parts)]] %||% item)
      swap_last <- function(from, to) {
        aliases <<- c(aliases, to)
        swapped <- sub(paste0("(^|[./\\\\])", from, "$"), paste0("\\1", to), item, ignore.case = TRUE, perl = TRUE)
        if (!identical(swapped, item)) aliases <<- c(aliases, swapped)
      }
      if (identical(last, "codigo_pulso")) swap_last("codigo_pulso", "code_pulso")
      if (identical(last, "code_pulso")) swap_last("code_pulso", "codigo_pulso")
    }
    aliases
  }
  add(value)
  if (is.list(ref)) {
    add(ref$name %||% ref$nombre)
    add(ref$original_name %||% ref$originalName)
    add(ref$normalized_name %||% ref$normalizedName)
    add(ref$path)
    add(ref$xpath)
    add(ref$technical)
  }
  add(pulso_aliases(out))
  unique(out[nzchar(trimws(out))])
}

.monitoreo_territorial_col_key <- function(value) {
  value <- tolower(trimws(as.character(value %||% "")))
  value <- iconv(value, to = "ASCII//TRANSLIT", sub = "")
  value <- gsub("\\\\", "/", value)
  value <- gsub("[.]", "/", value)
  value <- gsub("[^a-z0-9/]+", "_", value)
  value <- gsub("_+", "_", value)
  value <- gsub("^_+|_+$", "", value)
  value
}

.monitoreo_territorial_col_last_key <- function(value) {
  key <- .monitoreo_territorial_col_key(value)
  parts <- strsplit(key, "/", fixed = TRUE)[[1]]
  .monitoreo_safe_name(parts[[length(parts)]] %||% key)
}

.monitoreo_territorial_resolve_data_col <- function(data, value = "", ref = NULL) {
  if (is.null(data) || !is.data.frame(data) || !length(names(data))) return("")
  cols <- names(data)
  candidates <- .monitoreo_territorial_field_candidates(value, ref)
  candidates <- candidates[nzchar(trimws(candidates))]
  if (!length(candidates)) return("")
  exact <- candidates[candidates %in% cols]
  if (length(exact)) return(exact[[1]])
  col_path_keys <- stats::setNames(vapply(cols, .monitoreo_territorial_col_key, character(1)), cols)
  for (candidate in candidates) {
    variants <- unique(c(
      candidate,
      gsub("/", ".", candidate, fixed = TRUE),
      gsub(".", "/", candidate, fixed = TRUE)
    ))
    keys <- vapply(variants, .monitoreo_territorial_col_key, character(1))
    hit <- names(col_path_keys)[col_path_keys %in% keys]
    if (length(hit) == 1L) return(hit[[1]])
  }
  safe_cols <- stats::setNames(vapply(cols, .monitoreo_safe_name, character(1)), cols)
  safe_candidates <- unique(vapply(candidates, .monitoreo_safe_name, character(1)))
  hit <- names(safe_cols)[safe_cols %in% safe_candidates]
  if (length(hit) == 1L) return(hit[[1]])
  last_cols <- stats::setNames(vapply(cols, .monitoreo_territorial_col_last_key, character(1)), cols)
  last_candidates <- unique(vapply(candidates, .monitoreo_territorial_col_last_key, character(1)))
  hit <- names(last_cols)[last_cols %in% last_candidates]
  if (length(hit) == 1L) return(hit[[1]])
  ""
}

.monitoreo_territorial_source_value <- function(data, col, default = NA_character_, ref = NULL) {
  if (!nrow(data)) return(character(0))
  resolved <- .monitoreo_territorial_resolve_data_col(data, col, ref = ref)
  if (nzchar(resolved)) return(as.character(data[[resolved]]))
  rep(default, nrow(data))
}

.monitoreo_territorial_source_first_value <- function(data, candidates, default = "", ref = NULL) {
  if (!nrow(data)) return(character(0))
  out <- rep(default, nrow(data))
  missing <- rep(TRUE, nrow(data))
  candidates <- unique(.monitoreo_chr_vec(candidates))
  refs <- if (is.list(ref) && length(ref) && is.null(names(ref))) ref else list(ref)
  for (candidate in candidates) {
    ref_items <- refs
    if (!length(ref_items)) ref_items <- list(NULL)
    for (ref_item in ref_items) {
      resolved <- .monitoreo_territorial_resolve_data_col(data, candidate, ref = ref_item)
      if (!nzchar(resolved)) next
      values <- as.character(data[[resolved]])
      values[is.na(values)] <- default
      value_key <- .monitoreo_text_key(values)
      has_value <- nzchar(trimws(values)) & !value_key %in% c("na", "nan", "null", "sin_dato", "sin_datos", "sd")
      fill <- missing & has_value
      out[fill] <- values[fill]
      missing[fill] <- FALSE
      if (!any(missing)) return(out)
    }
  }
  out
}

