.monitoreo_internal_pending_base <- function(status, source = "", role = "") {
  key <- .monitoreo_text_key(paste(status, source, role))
  if (!nzchar(key)) return(FALSE)
  grepl("faltant", key) ||
    grepl("pendient", key) ||
    grepl("no barrido|nobarrido", key) ||
    grepl("sin respuesta|no respuesta", key) ||
    grepl("no contesta|contactar despues|contactar_despues", key)
}

.monitoreo_internal_collector_label <- function(collector_id, collector_name) {
  collector_id <- .monitoreo_scalar(collector_id, "")
  collector_name <- .monitoreo_scalar(collector_name, "")
  if (nzchar(collector_name) && nzchar(collector_id) && !identical(collector_name, collector_id)) {
    return(paste0(collector_name, " (", collector_id, ")"))
  }
  if (nzchar(collector_name)) return(collector_name)
  if (nzchar(collector_id)) return(collector_id)
  "Sin recopilador"
}

.monitoreo_internal_row_value_by_alias <- function(df, row_idx, aliases = character(0), source_label_maps = NULL) {
  if (is.null(df) || !is.data.frame(df) || row_idx < 1L || row_idx > nrow(df) || !length(names(df))) return("")
  aliases <- unique(.monitoreo_text_key(.monitoreo_chr_vec(aliases)))
  aliases <- aliases[nzchar(aliases)]
  if (!length(aliases)) return("")
  clean_names <- .monitoreo_text_key(names(df))
  for (alias in aliases) {
    idx <- which(clean_names == alias)
    if (!length(idx)) next
    for (pos in idx) {
      value <- .monitoreo_scalar(df[[pos]][[row_idx]], "")
      if (nzchar(value)) return(value)
    }
  }
  if (is.null(source_label_maps)) source_label_maps <- .monitoreo_source_variable_label_map(df)
  for (pos in seq_along(names(df))) {
    label <- .monitoreo_row_variable_label(df, row_idx, names(df)[[pos]], "", source_label_maps)
    label_key <- .monitoreo_text_key(label)
    if (!nzchar(label_key) || !label_key %in% aliases) next
    value <- .monitoreo_scalar(df[[pos]][[row_idx]], "")
    if (nzchar(value)) return(value)
  }
  ""
}

.monitoreo_internal_row_value_by_label <- function(df, row_idx, pattern = "", source_label_maps = NULL) {
  if (is.null(df) || !is.data.frame(df) || row_idx < 1L || row_idx > nrow(df) || !length(names(df))) return("")
  pattern <- .monitoreo_scalar(pattern, "")
  if (!nzchar(pattern)) return("")
  if (is.null(source_label_maps)) source_label_maps <- .monitoreo_source_variable_label_map(df)
  for (column in names(df)) {
    value <- .monitoreo_scalar(df[[column]][[row_idx]], "")
    if (!nzchar(value)) next
    label <- .monitoreo_row_variable_label(df, row_idx, column, "", source_label_maps)
    haystack <- .monitoreo_text_key(paste(column, label))
    if (grepl(pattern, haystack)) return(value)
  }
  ""
}

.monitoreo_internal_key_strategy <- function(channel = "", source_label = "", details = list()) {
  detail_text <- ""
  if (length(details)) {
    detail_text <- paste(vapply(details, function(item) {
      paste(
        .monitoreo_scalar(item$type, ""),
        .monitoreo_scalar(item$column, ""),
        .monitoreo_scalar(item$label, "")
      )
    }, character(1)), collapse = " ")
  }
  text <- .monitoreo_text_key(paste(channel, source_label, detail_text))
  if (grepl("telefon|llamada|barrido", text)) return("telefono_enlace_y_codigo_final")
  if (grepl("whatsapp|wsp", text)) return("pregunta_pucp_whatsapp")
  if (grepl("qr|presencial|ficha", text)) return("pregunta_pucp_qr")
  if (grepl("correo|mail|email", text)) return("correo_envio")
  "llave_configurada"
}

.monitoreo_internal_strategy_label <- function(strategy = "") {
  switch(.monitoreo_scalar(strategy, ""),
    telefono_enlace_y_codigo_final = "Telefónico: enlace personalizado + código final",
    pregunta_pucp_whatsapp = "WhatsApp: pregunta de código PUCP",
    pregunta_pucp_qr = "QR presencial: pregunta de código PUCP",
    correo_envio = "Correo: metadata del envío",
    llave_configurada = "Llave configurada por fuente",
    "Llave configurada por fuente"
  )
}

.monitoreo_internal_code_values_match <- function(a = "", b = "") {
  keys_a <- .monitoreo_code_keys(a)
  keys_b <- .monitoreo_code_keys(b)
  length(keys_a) && length(keys_b) && any(keys_a %in% keys_b)
}

.monitoreo_internal_base_phone_values <- function(base = list()) {
  values <- .monitoreo_internal_base_detail_values(base, "telefono")
  keys <- unique(unlist(base$all_keys %||% list(), use.names = FALSE))
  phone_keys <- sub("^telefono:", "", keys[grepl("^telefono:", keys)])
  unique(vapply(c(values, phone_keys), .monitoreo_phone_key, character(1)))
}

.monitoreo_internal_phone_distance <- function(a = "", b = "") {
  a <- .monitoreo_phone_key(a)
  b <- .monitoreo_phone_key(b)
  if (!nzchar(a) || !nzchar(b)) return(Inf)
  if (identical(a, b)) return(0L)
  if (nchar(a) != nchar(b)) return(Inf)
  sum(strsplit(a, "")[[1L]] != strsplit(b, "")[[1L]])
}

.monitoreo_internal_phone_evidence_level <- function(phone = "", base = list()) {
  phone <- .monitoreo_phone_key(phone)
  if (!nzchar(phone)) return("sin_telefono")
  base_phones <- .monitoreo_internal_base_phone_values(base)
  base_phones <- base_phones[nzchar(base_phones)]
  if (!length(base_phones)) return("sin_telefono_base")
  distances <- vapply(base_phones, function(value) .monitoreo_internal_phone_distance(phone, value), numeric(1))
  if (any(distances == 0, na.rm = TRUE)) return("telefono_exacto")
  if (any(distances <= 1, na.rm = TRUE)) return("telefono_casi_igual")
  "telefono_no_coincide"
}

.monitoreo_internal_base_snapshot <- function(base = list()) {
  if (is.null(base) || !is.list(base)) {
    return(list(record = "", person_label = "", case_key = "", status = "", responsible = "", source = ""))
  }
  list(
    record = .monitoreo_scalar(base$identifier, ""),
    person_label = .monitoreo_scalar(base$person, ""),
    case_key = .monitoreo_internal_base_official_code(base),
    status = .monitoreo_scalar(base$status, ""),
    responsible = .monitoreo_scalar(base$responsible, ""),
    source = .monitoreo_scalar(base$source, "")
  )
}

.monitoreo_internal_phone_audit <- function(response_rows,
                                            row_idx,
                                            response_actor = "",
                                            base = NULL,
                                            base_index = list(),
                                            source_label_maps = NULL) {
  cv_id <- .monitoreo_internal_row_value_by_alias(
    response_rows,
    row_idx,
    c("cv_id", "custom_value", "recipient_cv_id", "recipient_cv_codpulso", "recipient_custom_value"),
    source_label_maps
  )
  manual_code <- .monitoreo_internal_row_value_by_alias(
    response_rows,
    row_idx,
    c("q0034", "q034", "q34", "codigo pulso final", "código pulso final", "codpulso final"),
    source_label_maps
  )
  if (!nzchar(manual_code)) {
    manual_code <- .monitoreo_internal_row_value_by_label(
      response_rows,
      row_idx,
      "codigo.*pulso|cod.*pulso",
      source_label_maps
    )
  }
  declared_phone <- .monitoreo_internal_row_value_by_alias(
    response_rows,
    row_idx,
    c("q0035", "q035", "q35", "telefono final", "teléfono final", "celular"),
    source_label_maps
  )
  if (!nzchar(declared_phone)) {
    declared_phone <- .monitoreo_internal_row_value_by_label(
      response_rows,
      row_idx,
      "celular|telefono|teléfono|phone",
      source_label_maps
    )
  }
  if (!nzchar(cv_id) && !nzchar(manual_code) && !nzchar(declared_phone)) return(list())

  link_base <- NULL
  if (nzchar(cv_id)) {
    for (key in .monitoreo_code_keys(cv_id)) {
      link_base <- .monitoreo_report_base_index_lookup(base_index, key, response_actor)
      if (!is.null(link_base)) break
    }
  }
  manual_base <- NULL
  if (nzchar(manual_code)) {
    for (key in .monitoreo_code_keys(manual_code)) {
      manual_base <- .monitoreo_report_base_index_lookup(base_index, key, response_actor)
      if (!is.null(manual_base)) break
    }
  }
  if (is.null(link_base) && !is.null(base)) link_base <- base

  has_conflict <- nzchar(cv_id) && nzchar(manual_code) &&
    !isTRUE(.monitoreo_internal_code_values_match(cv_id, manual_code))
  has_confirmation <- nzchar(cv_id) && nzchar(manual_code) &&
    isTRUE(.monitoreo_internal_code_values_match(cv_id, manual_code))
  phone_level <- .monitoreo_internal_phone_evidence_level(declared_phone, link_base %||% base %||% list())
  if (isTRUE(has_conflict)) {
    match_level <- "conflicto"
    recommendation <- "Validar con responsable: el enlace usado y el código final escrito apuntan a personas distintas."
  } else if (isTRUE(has_confirmation)) {
    match_level <- "confirmado"
    recommendation <- "El enlace y el código final coinciden; revisar solo si hay duplicados o teléfono inconsistente."
  } else if (nzchar(cv_id) && !nzchar(manual_code)) {
    match_level <- "sin_confirmacion_final"
    recommendation <- "Cruce por enlace personalizado; falta código final escrito para confirmar la llamada."
  } else if (!nzchar(cv_id) && nzchar(manual_code)) {
    match_level <- "codigo_final_sin_enlace"
    recommendation <- "No hay enlace personalizado usable; el código final puede orientar una conciliación manual."
  } else {
    match_level <- "sin_codigo_telefonico"
    recommendation <- "No se encontró enlace ni código final usable para validar la llamada."
  }

  primary_base <- .monitoreo_internal_base_snapshot(link_base %||% base %||% list())
  secondary_base <- .monitoreo_internal_base_snapshot(manual_base %||% list())
  responsible <- .monitoreo_scalar(primary_base$responsible, "")
  if (!nzchar(responsible)) responsible <- .monitoreo_scalar(secondary_base$responsible, "")
  list(
    cv_id = .monitoreo_scalar(cv_id, ""),
    final_codpulso = .monitoreo_scalar(manual_code, ""),
    declared_phone = .monitoreo_scalar(declared_phone, ""),
    responsible = responsible,
    phone_match_level = match_level,
    phone_number_evidence = phone_level,
    link_base = primary_base,
    manual_code_base = secondary_base,
    recommended_action = recommendation
  )
}

.monitoreo_internal_identity_status <- function(result = "",
                                                advancement = "",
                                                issue_type = "",
                                                phone_audit = list(),
                                                partial_info = list()) {
  if (is.list(phone_audit) && identical(.monitoreo_scalar(phone_audit$phone_match_level, ""), "conflicto")) {
    return("conflicto_telefonico")
  }
  result_key <- .monitoreo_text_key(result)
  issue_key <- .monitoreo_text_key(issue_type)
  if (grepl("sin llave", result_key) || issue_key %in% c("sin_llave", "parcial_no_identificable")) return("no_identificable")
  if (grepl("sin cruce", result_key) || issue_key %in% c("fuera_base", "codigo_fuera_base")) return("fuera_base")
  if (identical(.monitoreo_scalar(advancement, ""), "partial") &&
      .monitoreo_int(partial_info$pct %||% 0L, 0L) >= 80L) return("parcial_revisable")
  if (identical(.monitoreo_scalar(advancement, ""), "effective")) return("identificado")
  if (identical(.monitoreo_scalar(advancement, ""), "included_review")) return("identificado_con_salvedad")
  if (identical(.monitoreo_scalar(advancement, ""), "partial")) return("parcial")
  if (identical(.monitoreo_scalar(advancement, ""), "refusal")) return("rechazo")
  if (identical(.monitoreo_scalar(advancement, ""), "pending")) return("pendiente_base")
  "revision"
}

.monitoreo_internal_identity_label <- function(status = "") {
  switch(.monitoreo_scalar(status, ""),
    conflicto_telefonico = "Conflicto telefónico",
    no_identificable = "Caso no identificable",
    fuera_base = "Llave fuera de base",
    parcial_revisable = "Parcial casi completa",
    duplicado = "Duplicado",
    identificado = "Persona identificada",
    identificado_con_salvedad = "Identificada con salvedad",
    parcial = "Parcial identificable",
    rechazo = "Rechazo",
    pendiente_base = "Pendiente en base",
    "Revisión"
  )
}

.monitoreo_internal_is_recovery_collector <- function(collector_id, collector_name, source_label = "") {
  key <- .monitoreo_safe_name(paste(collector_id, collector_name, source_label))
  grepl("faltante|faltantes|recuperacion|recuperacion", key)
}

.monitoreo_internal_declared_evidence <- function(response_rows, row_idx, details = list(), source_label_maps = NULL) {
  first_detail <- function(type) {
    if (!length(details)) return("")
    for (item in details) {
      if (identical(.monitoreo_scalar(item$type, ""), type)) {
        value <- .monitoreo_scalar(item$value, "")
        return(if (nzchar(value)) value else .monitoreo_scalar(item$key, ""))
      }
    }
    ""
  }
  declared_code <- first_detail("codigo")
  declared_email <- first_detail("email")
  recipient_email <- ""
  primary_key <- ""
  if (length(details)) {
    primary <- details[[1L]]
    primary_key <- .monitoreo_scalar(primary$value, "")
    if (!nzchar(primary_key)) primary_key <- .monitoreo_scalar(primary$key, "")
  }
  if (!is.null(response_rows) && is.data.frame(response_rows) && row_idx >= 1L && row_idx <= nrow(response_rows)) {
    recipient_email <- .monitoreo_internal_row_value_by_alias(
      response_rows,
      row_idx,
      c("recipient_email", "recipient email", "email del destinatario", "correo destinatario", "correo del destinatario"),
      source_label_maps
    )
  }
  if (!nzchar(declared_email) && !is.null(response_rows) && is.data.frame(response_rows) && row_idx >= 1L && row_idx <= nrow(response_rows)) {
    if (is.null(source_label_maps)) source_label_maps <- .monitoreo_source_variable_label_map(response_rows)
    for (column in names(response_rows)) {
      value <- .monitoreo_scalar(response_rows[[column]][[row_idx]], "")
      email_key <- .monitoreo_email_key(value)
      if (!nzchar(email_key)) next
      label <- .monitoreo_row_variable_label(response_rows, row_idx, column, "", source_label_maps)
      haystack <- .monitoreo_text_key(paste(column, label))
      if (grepl("mail|correo|email", haystack)) {
        declared_email <- value
        break
      }
    }
  }
  declared_name <- ""
  if (!is.null(response_rows) && is.data.frame(response_rows) && row_idx >= 1L && row_idx <= nrow(response_rows)) {
    declared_names <- .monitoreo_report_person_values(response_rows[row_idx, , drop = FALSE])
    declared_name <- .monitoreo_scalar(declared_names[[1]] %||% "", "")
  }
  list(
    primary_key = primary_key,
    declared_code = declared_code,
    recipient_email = recipient_email,
    declared_email = declared_email,
    declared_name = declared_name
  )
}

.monitoreo_internal_email_base_rescue <- function(base_index, evidence = list(), actor = "") {
  email_values <- unique(trimws(as.character(c(
    evidence$recipient_email %||% "",
    evidence$declared_email %||% ""
  ))))
  email_values <- email_values[nzchar(email_values)]
  for (value in email_values) {
    email <- .monitoreo_email_key(value)
    if (!nzchar(email)) next
    key <- paste0("email:", email)
    base <- .monitoreo_report_base_index_lookup(base_index, key, actor)
    if (is.null(base)) next
    return(list(
      base = base,
      detail = list(
        key = key,
        type = "email",
        column = "declared_email",
        label = "Correo declarado",
        value = value,
        configured = FALSE
      )
    ))
  }
  NULL
}

.monitoreo_internal_real_question_columns <- function(response_rows, source_label_maps = NULL) {
  if (is.null(response_rows) || !is.data.frame(response_rows) || !length(names(response_rows))) {
    return(character(0))
  }
  if (is.null(source_label_maps)) source_label_maps <- .monitoreo_source_variable_label_map(response_rows)
  label_map <- .monitoreo_variable_label_map(response_rows)
  out <- character(0)
  for (column in names(response_rows)) {
    clean <- .monitoreo_text_key(column)
    if (!nzchar(clean) || grepl("^\\.", column)) next
    label <- if (length(label_map) && column %in% names(label_map)) {
      .monitoreo_scalar(label_map[[column]], "")
    } else {
      ""
    }
    source_label <- ""
    if (length(source_label_maps)) {
      for (source_map in source_label_maps) {
        if (!is.list(source_map) || is.null(source_map$labels)) next
        candidate <- .monitoreo_scalar(source_map$labels[[column]], "")
        if (nzchar(candidate)) {
          source_label <- candidate
          break
        }
      }
    }
    haystack <- .monitoreo_text_key(paste(column, label, source_label))
    technical <- grepl(
      paste(c(
        "^source", "survey", "response", "collector", "recipient", "custom_value", "cv_id",
        "metadata", "meta", "ip_address", "ip address", "href", "edit_url", "language",
        "date_created", "date_modified", "fecha_creacion", "fecha_modificacion",
        "total_time", "tiempo_total", "status", "estado", "completa", "parcial",
        "rechazo", "dim_", "actor", "canal", "channel", "source_role", "source_id"
      ), collapse = "|"),
      haystack
    )
    is_question <- grepl("^q[0-9]+($|_)", clean) || (nzchar(label) && !technical)
    if (isTRUE(is_question) && !technical) out <- c(out, column)
  }
  unique(out)
}

.monitoreo_internal_partial_diagnostics <- function(response_rows,
                                                    row_idx,
                                                    source_label_maps = NULL,
                                                    question_columns = NULL) {
  if (is.null(response_rows) || !is.data.frame(response_rows) || row_idx < 1L || row_idx > nrow(response_rows)) {
    return(list(answered = 0L, total = 0L, pct = 0L, last = "", next_question = ""))
  }
  if (is.null(source_label_maps)) source_label_maps <- .monitoreo_source_variable_label_map(response_rows)
  if (is.null(question_columns)) question_columns <- .monitoreo_internal_real_question_columns(response_rows, source_label_maps)
  question_columns <- question_columns[question_columns %in% names(response_rows)]
  if (!length(question_columns)) return(list(answered = 0L, total = 0L, pct = 0L, last = "", next_question = ""))
  values <- vapply(question_columns, function(column) {
    .monitoreo_scalar(response_rows[[column]][[row_idx]], "")
  }, character(1))
  values <- trimws(values)
  values_key <- .monitoreo_text_key(values)
  answered <- nzchar(values) & !values_key %in% c("na", "n a", "n/a", "sd", "s d", "s/d", "sin dato", "sin respuesta")
  labels <- vapply(question_columns, function(column) {
    label <- .monitoreo_row_variable_label(response_rows, row_idx, column, "", source_label_maps)
    if (nzchar(label)) label else column
  }, character(1))
  question_keys <- .monitoreo_text_key(labels)
  column_question_keys <- sub("^q0*([0-9]+).*$", "q\\1", .monitoreo_text_key(question_columns))
  q_column <- grepl("^q[0-9]+", column_question_keys)
  question_keys[q_column] <- column_question_keys[q_column]
  missing_question_key <- !nzchar(question_keys) | is.na(question_keys)
  question_keys[missing_question_key] <- question_columns[missing_question_key]
  group_keys <- unique(question_keys)
  group_answered <- vapply(group_keys, function(key) {
    any(answered[question_keys == key], na.rm = TRUE)
  }, logical(1))
  group_labels <- vapply(group_keys, function(key) {
    labels[which(question_keys == key)[[1L]]]
  }, character(1))
  total <- length(group_keys)
  answered_count <- sum(group_answered, na.rm = TRUE)
  last_label <- if (answered_count) group_labels[max(which(group_answered))] else ""
  next_idx <- which(!group_answered)
  next_label <- if (length(next_idx)) group_labels[min(next_idx)] else ""
  list(
    answered = as.integer(answered_count),
    total = as.integer(total),
    pct = as.integer(round(answered_count / max(1L, total) * 100)),
    last = last_label,
    next_question = next_label
  )
}

.monitoreo_internal_base_official_code <- function(base = list()) {
  details <- base$key_details %||% list()
  if (length(details)) {
    for (item in details) {
      if (identical(.monitoreo_scalar(item$type, ""), "codigo")) {
        value <- .monitoreo_scalar(item$value, "")
        if (nzchar(value)) return(value)
      }
    }
  }
  value <- .monitoreo_scalar(base$value, "")
  if (nzchar(value)) value else .monitoreo_scalar(base$identifier, "")
}

.monitoreo_internal_base_detail_values <- function(base = list(), type = "") {
  type <- .monitoreo_scalar(type, "")
  details <- base$key_details %||% list()
  if (!length(details) || !nzchar(type)) return(character(0))
  out <- character(0)
  for (item in details) {
    if (!identical(.monitoreo_scalar(item$type, ""), type)) next
    value <- .monitoreo_scalar(item$value, "")
    key <- .monitoreo_scalar(item$key, "")
    if (nzchar(value)) out <- c(out, value)
    if (nzchar(key)) out <- c(out, sub("^[^:]+:", "", key))
  }
  unique(out[nzchar(out)])
}

.monitoreo_internal_assignment_evidence <- function(base = list(),
                                                    email_keys = character(0),
                                                    code_keys = character(0),
                                                    declared_email = "",
                                                    declared_code = "",
                                                    declared_name = "") {
  base_keys <- unique(unlist(base$all_keys %||% list(), use.names = FALSE))
  base_keys <- base_keys[nzchar(base_keys)]
  email_match <- length(email_keys) && any(email_keys %in% base_keys)
  code_match <- length(code_keys) && any(code_keys %in% base_keys)
  if (isTRUE(email_match) && isTRUE(code_match)) {
    return(list(
      match_type = "email_code_exact",
      match_label = "Coincidencia por correo y código exactos",
      evidence_level = "exact",
      evidence_label = "Correo y código exactos",
      evidence_score = 100L,
      evidence_fields = c("correo", "codigo")
    ))
  }
  if (isTRUE(email_match)) {
    return(list(
      match_type = "email_exact",
      match_label = "Coincidencia por correo exacto",
      evidence_level = "exact",
      evidence_label = "Correo exacto",
      evidence_score = 100L,
      evidence_fields = "correo"
    ))
  }
  if (isTRUE(code_match)) {
    return(list(
      match_type = "code_exact",
      match_label = "Coincidencia por código exacto",
      evidence_level = "exact",
      evidence_label = "Código exacto",
      evidence_score = 100L,
      evidence_fields = "codigo"
    ))
  }
  base_emails <- .monitoreo_internal_base_detail_values(base, "email")
  declared_email_key <- .monitoreo_email_key(declared_email)
  email_scores <- if (nzchar(declared_email_key) && length(base_emails)) {
    vapply(base_emails, function(email) .monitoreo_email_similarity_score(declared_email_key, email), integer(1))
  } else {
    integer(0)
  }
  best_email_score <- if (length(email_scores)) max(email_scores, na.rm = TRUE) else 0L
  if (is.finite(best_email_score) && best_email_score >= 72L) {
    return(list(
      match_type = "email_similar",
      match_label = "Correo similar en pendiente",
      evidence_level = "possible",
      evidence_label = paste0("Correo similar ", best_email_score, "%"),
      evidence_score = as.integer(best_email_score),
      evidence_fields = "correo"
    ))
  }
  base_name <- .monitoreo_scalar(base$person, "")
  name_score <- .monitoreo_text_similarity_score(declared_name, base_name)
  if (nzchar(.monitoreo_text_key(declared_name)) && nzchar(.monitoreo_text_key(base_name)) && name_score >= 88L) {
    exact_name <- identical(.monitoreo_text_key(declared_name), .monitoreo_text_key(base_name))
    return(list(
      match_type = if (exact_name) "name_exact" else "name_similar",
      match_label = if (exact_name) "Coincidencia por nombre exacto" else "Nombre similar en pendiente",
      evidence_level = if (exact_name) "exact" else "possible",
      evidence_label = if (exact_name) "Nombre exacto" else paste0("Nombre similar ", name_score, "%"),
      evidence_score = as.integer(name_score),
      evidence_fields = "nombre"
    ))
  }
  list(
    match_type = "manual_pending",
    match_label = "Pendiente del universo/base",
    evidence_level = "manual",
    evidence_label = "Sin evidencia automática",
    evidence_score = 0L,
    evidence_fields = character(0)
  )
}

.monitoreo_internal_candidate_id <- function(base = list()) {
  details <- base$key_details %||% list()
  if (length(details)) {
    for (item in details) {
      if (identical(.monitoreo_scalar(item$type, ""), "codigo")) {
        key <- .monitoreo_scalar(item$key, "")
        if (nzchar(key)) return(key)
      }
    }
  }
  key <- .monitoreo_scalar(base$key, "")
  if (nzchar(key)) key else paste0("base-row:", .monitoreo_int(base$row, 0L))
}

.monitoreo_internal_base_candidate <- function(base = list(),
                                              answered_base_keys = character(0),
                                              match_type = "manual_pending",
                                              match_label = "Pendiente del universo/base",
                                              suggested = FALSE,
                                              evidence_level = "",
                                              evidence_label = "",
                                              evidence_score = NA_integer_,
                                              evidence_fields = character(0),
                                              already_answered = NULL) {
  base_keys <- unique(unlist(base$all_keys %||% list(), use.names = FALSE))
  base_keys <- base_keys[nzchar(base_keys)]
  automatic_answered <- length(answered_base_keys) && any(base_keys %in% answered_base_keys)
  if (is.null(already_answered)) already_answered <- automatic_answered
  already_answered <- isTRUE(.monitoreo_bool(already_answered, FALSE))
  if (!nzchar(evidence_level)) evidence_level <- if (identical(match_type, "manual_pending")) "manual" else "exact"
  if (!nzchar(evidence_label)) evidence_label <- if (identical(evidence_level, "manual")) "Sin evidencia automática" else match_label
  evidence_score <- suppressWarnings(as.numeric(evidence_score)[1])
  if (!is.finite(evidence_score)) evidence_score <- if (identical(evidence_level, "exact")) 100L else 0L
  list(
    candidate_id = .monitoreo_internal_candidate_id(base),
    person_label = .monitoreo_scalar(base$person, ""),
    case_key = .monitoreo_internal_base_official_code(base),
    base_record = .monitoreo_scalar(base$identifier, ""),
    base_source = .monitoreo_scalar(base$source, ""),
    base_row = .monitoreo_int(base$row, 0L),
    base_status = .monitoreo_scalar(base$status, ""),
    match_type = match_type,
    match_label = match_label,
    evidence_level = evidence_level,
    evidence_label = evidence_label,
    evidence_score = as.integer(evidence_score),
    evidence_fields = as.list(.monitoreo_chr_vec(evidence_fields)),
    current_status = if (already_answered) "Tiene respuesta reconciliada en el corte" else "Pendiente en universo/base",
    already_effective = already_answered,
    assignment_allowed = !already_answered,
    suggested = isTRUE(suggested)
  )
}

.monitoreo_internal_find_base_by_candidate <- function(base_records = list(), candidate_id = "", actor = "") {
  candidate_id <- .monitoreo_scalar(candidate_id, "")
  actor_key <- .monitoreo_text_key(actor)
  if (!nzchar(candidate_id)) return(NULL)
  for (base in base_records) {
    if (nzchar(actor_key) && !identical(.monitoreo_text_key(base$actor %||% ""), actor_key)) next
    keys <- unique(unlist(base$all_keys %||% list(), use.names = FALSE))
    official <- .monitoreo_internal_base_official_code(base)
    values <- unique(c(.monitoreo_internal_candidate_id(base), keys, official, .monitoreo_code_keys(official)))
    if (candidate_id %in% values) return(base)
  }
  NULL
}

.monitoreo_internal_assisted_review <- function(evidence = list(),
                                                response_actor = "",
                                                response_id = "",
                                                response_state = "",
                                                result = "",
                                                base_records = list(),
                                                answered_base_keys = character(0),
                                                current_base = NULL,
                                                profile = list()) {
  manual <- .monitoreo_reconciliation_manual_decision(profile, response_id)
  state_key <- .monitoreo_text_key(response_state)
  result_key <- .monitoreo_text_key(result)
  eligible_state <- state_key %in% c("completa", "parcial", "rechazo")
  current_partial_base <- !is.null(current_base) &&
    identical(state_key, "parcial") &&
    grepl("^cruzo", result_key)
  eligible <- isTRUE(eligible_state) &&
    (!identical(result, "Cruzó") || !is.null(manual) || isTRUE(current_partial_base))
  declared_code <- .monitoreo_scalar(evidence$declared_code, "")
  declared_email <- .monitoreo_scalar(evidence$declared_email, "")
  declared_name <- .monitoreo_scalar(evidence$declared_name, "")
  primary_key <- .monitoreo_scalar(evidence$primary_key, "")
  if (!isTRUE(eligible) && is.null(manual)) return(NULL)

  email_key <- .monitoreo_email_key(declared_email)
  email_keys <- if (nzchar(email_key)) paste0("email:", email_key) else character(0)
  code_keys <- .monitoreo_code_keys(declared_code)
  actor_key <- .monitoreo_text_key(response_actor)
  candidates <- list()
  seen <- character(0)
  current_partial_candidate <- NULL
  if (isTRUE(current_partial_base)) {
    current_partial_candidate <- .monitoreo_internal_base_candidate(
      current_base,
      answered_base_keys,
      match_type = "partial_current_case",
      match_label = "Parcial cruzada a base oficial",
      suggested = TRUE,
      evidence_level = "manual",
      evidence_label = "Validación manual requerida",
      evidence_score = 80L,
      evidence_fields = c("platform_state", "case_key"),
      already_answered = FALSE
    )
    candidate_id <- .monitoreo_scalar(current_partial_candidate$candidate_id, "")
    if (nzchar(candidate_id)) {
      candidates[[length(candidates) + 1L]] <- current_partial_candidate
      seen <- c(seen, candidate_id)
    }
  }
  for (base in base_records) {
    if (nzchar(actor_key) && !identical(.monitoreo_text_key(base$actor %||% ""), actor_key)) next
    base_keys <- unique(unlist(base$all_keys %||% list(), use.names = FALSE))
    email_match <- length(email_keys) && any(email_keys %in% base_keys)
    code_match <- length(code_keys) && any(code_keys %in% base_keys)
    if (!email_match && !code_match) next
    candidate_id <- .monitoreo_internal_candidate_id(base)
    if (candidate_id %in% seen) next
    seen <- c(seen, candidate_id)
    evidence <- .monitoreo_internal_assignment_evidence(
      base,
      email_keys = email_keys,
      code_keys = code_keys,
      declared_email = declared_email,
      declared_code = declared_code,
      declared_name = declared_name
    )
    candidates[[length(candidates) + 1L]] <- .monitoreo_internal_base_candidate(
      base,
      answered_base_keys,
      match_type = evidence$match_type,
      match_label = evidence$match_label,
      suggested = TRUE,
      evidence_level = evidence$evidence_level,
      evidence_label = evidence$evidence_label,
      evidence_score = evidence$evidence_score,
      evidence_fields = evidence$evidence_fields
    )
  }

  assignment_candidates <- list()
  assignment_seen <- character(0)
  if (!is.null(current_partial_candidate)) {
    candidate_id <- .monitoreo_scalar(current_partial_candidate$candidate_id, "")
    if (nzchar(candidate_id)) {
      assignment_candidates[[length(assignment_candidates) + 1L]] <- current_partial_candidate
      assignment_seen <- c(assignment_seen, candidate_id)
    }
  }
  for (base in base_records) {
    if (nzchar(actor_key) && !identical(.monitoreo_text_key(base$actor %||% ""), actor_key)) next
    evidence <- .monitoreo_internal_assignment_evidence(
      base,
      email_keys = email_keys,
      code_keys = code_keys,
      declared_email = declared_email,
      declared_code = declared_code,
      declared_name = declared_name
    )
    candidate <- .monitoreo_internal_base_candidate(
      base,
      answered_base_keys,
      match_type = evidence$match_type,
      match_label = evidence$match_label,
      suggested = FALSE,
      evidence_level = evidence$evidence_level,
      evidence_label = evidence$evidence_label,
      evidence_score = evidence$evidence_score,
      evidence_fields = evidence$evidence_fields
    )
    candidate_id <- .monitoreo_scalar(candidate$candidate_id, "")
    if (!nzchar(candidate_id) || candidate_id %in% assignment_seen) next
    assignment_seen <- c(assignment_seen, candidate_id)
    if (isTRUE(candidate$already_effective)) next
    assignment_candidates[[length(assignment_candidates) + 1L]] <- candidate
  }

  warnings <- character(0)
  has_email_candidate <- any(vapply(candidates, function(item) grepl("email", .monitoreo_scalar(item$match_type, ""), fixed = TRUE), logical(1)))
  has_name_candidate <- any(vapply(candidates, function(item) grepl("name", .monitoreo_scalar(item$match_type, ""), fixed = TRUE), logical(1)))
  if (has_email_candidate && grepl("sin cruce|sin llave", result_key)) {
    warnings <- c(warnings, "La llave principal no cruza con la base, pero el correo declarado sí cruza con una persona del universo.")
  }
  if (has_name_candidate && grepl("sin cruce|sin llave", result_key)) {
    warnings <- c(warnings, "La llave principal no cruza con la base, pero el nombre declarado es compatible con una persona del universo.")
  }
  for (candidate in candidates) {
    if (!grepl("email", .monitoreo_scalar(candidate$match_type, ""), fixed = TRUE) || !nzchar(declared_code)) next
    official_code <- .monitoreo_scalar(candidate$case_key, "")
    if (nzchar(official_code) && !any(.monitoreo_code_keys(declared_code) %in% .monitoreo_code_keys(official_code))) {
      warnings <- c(warnings, "El código declarado no coincide con el código de la persona encontrada por correo.")
      break
    }
  }
  has_pending_evidence <- any(vapply(assignment_candidates, function(item) {
    .monitoreo_scalar(item$evidence_level, "") %in% c("exact", "possible")
  }, logical(1)))
  if (!length(candidates) && !isTRUE(has_pending_evidence) && (nzchar(declared_code) || nzchar(declared_email) || nzchar(declared_name) || nzchar(primary_key))) {
    warnings <- c(warnings, "No se encontró coincidencia por código, correo ni nombre en el universo.")
  }
  if (isTRUE(has_pending_evidence)) {
    warnings <- c(warnings, "Hay personas pendientes del universo con correo, código o nombre compatible; revisa estos casos antes de publicar la lista de no respuesta.")
  }

  list(
    eligible = TRUE,
    primary_key = primary_key,
    declared_code = declared_code,
    declared_email = declared_email,
    declared_name = declared_name,
    candidates = candidates,
    assignment_candidates = assignment_candidates,
    warnings = as.list(unique(warnings)),
    manual_decision = manual %||% NULL
  )
}

.monitoreo_internal_decision_for <- function(result, response_id, profile = list(), has_base = TRUE) {
  if (!isTRUE(has_base) && !identical(result, "Sin llave")) {
    return(list(
      label = "Excluido del avance",
      note = "Excluido porque no hay base oficial configurada para contrastar esta respuesta."
    ))
  }
  .monitoreo_reconciliation_decision(result, response_id, profile)
}

.monitoreo_internal_advancement <- function(state, decision_label, manual_include = FALSE) {
  state_key <- .monitoreo_text_key(state)
  decision_key <- .monitoreo_text_key(decision_label)
  included <- grepl("incluido", decision_key)
  if (isTRUE(manual_include) && included) return("effective")
  if (identical(state_key, "completa") && included) return("effective")
  if (identical(state_key, "parcial")) return("partial")
  if (identical(state_key, "rechazo")) return("refusal")
  if (included) return("included_review")
  "excluded"
}

.monitoreo_internal_issue_type <- function(state, result, advancement, key) {
  state_key <- .monitoreo_text_key(state)
  result_key <- .monitoreo_text_key(result)
  if (identical(state_key, "completa") &&
      identical(advancement, "effective") &&
      (grepl("sin cruce", result_key) || grepl("sin llave", result_key))) {
    return("incluido_con_salvedad")
  }
  if (identical(advancement, "effective")) return("efectiva_real")
  if (identical(state_key, "parcial")) {
    return(if (nzchar(.monitoreo_scalar(key, ""))) "parcial_identificable" else "parcial_no_identificable")
  }
  if (identical(state_key, "rechazo")) return("rechazo_plataforma")
  if (grepl("sin llave", result_key)) return("sin_llave")
  if (grepl("sin cruce", result_key)) return("fuera_base")
  if (identical(advancement, "included_review")) return("incluido_con_salvedad")
  "revision"
}

.monitoreo_internal_issue_label <- function(type) {
  switch(type,
    efectiva_real = "Efectiva real",
    parcial_identificable = "Parcial identificable",
    parcial_no_identificable = "Parcial no identificable",
    rechazo_plataforma = "Rechazo de plataforma",
    sin_respuesta = "Sin respuesta",
    sin_llave = "Respuesta sin llave",
    fuera_base = "Llave fuera de base",
    incluido_con_salvedad = "Incluido con salvedad",
    conflicto_telefonico = "Conflicto telefónico",
    duplicado_caso = "Caso duplicado",
    "Revisión"
  )
}

.monitoreo_internal_case_rule <- function(result, issue_type) {
  result_key <- .monitoreo_text_key(result)
  if (grepl("^cruzo", result_key) && grepl("correo|email", result_key)) {
    return("Completa incluida por correo exacto contra la base; si el código declarado difiere, queda auditada con salvedad.")
  }
  if (grepl("sin cruce", result_key)) {
    return("Llave detectada fuera de la base; queda fuera hasta corregir o decidir incluir con salvedad.")
  }
  if (grepl("sin llave", result_key)) {
    return("Respuesta sin llave reconciliable; queda fuera hasta identificarla.")
  }
  switch(issue_type,
    efectiva_real = "Completa válida incluida en avance; si venía de faltantes, sale de pendientes sin importar el recopilador usado.",
    parcial_identificable = "Parcial con llave identificable; sirve para seguimiento, no cuenta como efectiva.",
    parcial_no_identificable = "Parcial sin código, correo ni llave reconocible; no cuenta como efectiva y no se puede atribuir a un caso.",
    rechazo_plataforma = "Rechazo de plataforma o consentimiento; no cuenta como efectiva.",
    sin_llave = "Respuesta sin llave reconciliable; queda fuera hasta identificarla.",
    fuera_base = "Llave detectada fuera de la base; queda fuera hasta corregir o decidir incluir con salvedad.",
    incluido_con_salvedad = "Incluido por decisión auditada pese a no cruzar automáticamente.",
    conflicto_telefonico = "El enlace personalizado y el código final escrito apuntan a personas distintas; queda fuera hasta validarlo con responsable.",
    "Revisión pendiente."
  )
}

.monitoreo_internal_case_priority <- function(row) {
  advancement <- .monitoreo_scalar(row$advancement, "")
  state <- .monitoreo_text_key(row$platform_state)
  base <- switch(advancement,
    effective = 50,
    included_review = 40,
    partial = 30,
    refusal = 20,
    pending = 8,
    excluded = 10,
    1
  )
  if (identical(state, "completa")) base <- max(base, 45)
  if (identical(state, "parcial")) base <- max(base, 30)
  if (identical(state, "rechazo")) base <- max(base, 20)
  parsed <- suppressWarnings(tryCatch(
    as.Date(.monitoreo_scalar(row$date, "")),
    error = function(e) as.Date(NA)
  ))
  date_bonus <- if (!is.na(parsed)) -as.integer(parsed - as.Date("1970-01-01")) / 100000 else -1
  base + date_bonus
}

.monitoreo_internal_records_to_df <- function(rows) {
  if (!length(rows)) return(data.frame())
  out <- do.call(rbind, lapply(rows, function(row) {
    if (is.data.frame(row)) return(row)
    if (is.list(row) && length(row)) {
      row <- lapply(row, function(value) {
        if (is.null(value) || length(value) == 0L) return("")
        if (is.list(value) && !is.data.frame(value)) return(I(list(value)))
        if (length(value) != 1L) return(I(list(value)))
        value
      })
    }
    as.data.frame(row, check.names = FALSE, stringsAsFactors = FALSE)
  }))
  rownames(out) <- NULL
  out
}

.monitoreo_internal_deduplicate_cases <- function(cases_df) {
  if (is.null(cases_df) || !is.data.frame(cases_df) || !nrow(cases_df)) return(cases_df)
  dedupe_key <- as.character(cases_df$case_key %||% "")
  actor_key <- vapply(as.character(cases_df$actor %||% ""), .monitoreo_report_unit_key, character(1))
  actor_key[!nzchar(actor_key) | is.na(actor_key)] <- "sin_actor"
  dedupe_key <- ifelse(nzchar(dedupe_key) & !is.na(dedupe_key), paste(actor_key, dedupe_key, sep = "\r"), dedupe_key)
  fallback <- as.character(cases_df$response_id %||% rep("", nrow(cases_df)))
  response_row <- as.character(cases_df$response_row %||% rep("", nrow(cases_df)))
  state_key <- vapply(as.character(cases_df$platform_state %||% ""), .monitoreo_text_key, character(1))
  missing <- !nzchar(dedupe_key) | is.na(dedupe_key)
  has_response_id <- missing & nzchar(fallback) & !is.na(fallback)
  dedupe_key[has_response_id] <- paste(actor_key[has_response_id], "response", fallback[has_response_id], sep = "\r")
  missing <- !nzchar(dedupe_key) | is.na(dedupe_key)
  has_response_row <- missing & nzchar(response_row) & !is.na(response_row)
  dedupe_key[has_response_row] <- paste(actor_key[has_response_row], "response_row", response_row[has_response_row], sep = "\r")
  missing <- !nzchar(dedupe_key) | is.na(dedupe_key)
  dedupe_key[missing] <- paste(actor_key[missing], "event", state_key[missing], seq_len(nrow(cases_df))[missing], sep = "\r")
  priorities <- vapply(seq_len(nrow(cases_df)), function(i) {
    .monitoreo_internal_case_priority(as.list(cases_df[i, , drop = FALSE]))
  }, numeric(1))
  keep <- logical(nrow(cases_df))
  for (key in unique(dedupe_key)) {
    idx <- which(dedupe_key == key)
    best <- idx[which.max(priorities[idx])]
    keep[best] <- TRUE
  }
  cases_df[keep, , drop = FALSE]
}

.monitoreo_acreditacion_case_rollup_df <- function(data, profile = list(), internal_queries = NULL) {
  profile <- monitoreo_normalize_profile(profile)
  if (!.monitoreo_scalar(profile$family, "") %in% c("acreditacion", "telefonico")) return(data.frame())
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(data.frame())
  if (!any(.monitoreo_report_base_mask(data), na.rm = TRUE)) return(data.frame())
  queries <- internal_queries %||% .monitoreo_acreditacion_internal_queries(data, profile)
  cases <- .monitoreo_internal_records_to_df(queries$cases %||% list())
  if (!nrow(cases)) cases <- .monitoreo_internal_records_to_df(queries$case_rollup %||% list())
  if (!nrow(cases)) return(data.frame())
  .monitoreo_internal_deduplicate_cases(cases)
}

.monitoreo_acreditacion_case_in_base <- function(cases_df) {
  if (is.null(cases_df) || !is.data.frame(cases_df) || !nrow(cases_df)) return(logical(0))
  result_key <- .monitoreo_text_key(cases_df$base_result %||% "")
  grepl("^cruzo", result_key)
}

.monitoreo_acreditacion_summary_from_case_rollup <- function(data, profile = list(), case_rollup = NULL) {
  rollup <- case_rollup
  if (is.null(rollup)) rollup <- .monitoreo_acreditacion_case_rollup_df(data, profile)
  if (!is.data.frame(rollup) || !nrow(rollup)) return(data.frame())
  units <- .monitoreo_report_units(profile, data)
  if (!length(units)) return(data.frame())

  actor_keys <- vapply(as.character(rollup$actor %||% ""), .monitoreo_report_unit_key, character(1))
  in_base <- .monitoreo_acreditacion_case_in_base(rollup)
  advancement <- as.character(rollup$advancement %||% "")
  state_key <- .monitoreo_text_key(rollup$platform_state %||% "")
  states_all <- .monitoreo_report_states(data, profile)
  rows <- lapply(units, function(unit) {
    actor_key <- .monitoreo_report_unit_key(unit$label)
    unit_mask <- actor_keys == actor_key
    part <- rollup[unit_mask, , drop = FALSE]
    part_in_base <- in_base[unit_mask]
    part_advancement <- advancement[unit_mask]
    part_state_key <- state_key[unit_mask]
    sweep_mask <- .monitoreo_report_unit_mask(data, unit, roles = "barrido")
    response_mask <- .monitoreo_report_unit_mask(data, unit, roles = "respuestas")
    sweep_states <- states_all[sweep_mask]
    reconciliation <- .monitoreo_report_phone_reconciliation(
      data[sweep_mask, , drop = FALSE],
      data[response_mask, , drop = FALSE],
      profile
    )

    total <- sum(part_in_base, na.rm = TRUE)
    effective_main <- sum(part_in_base & part_advancement %in% c("effective", "included_review"), na.rm = TRUE)
    partial_main <- sum(part_in_base & part_advancement == "partial", na.rm = TRUE)
    refusal_unlinked <- sum(!part_in_base & part_state_key == "rechazo", na.rm = TRUE)
    # Unlinked platform refusals stay as audit evidence; they do not count in official advance.
    refusal_main <- sum(part_in_base & part_advancement == "refusal", na.rm = TRUE)
    rechazos_telefono <- sum(sweep_states == "Rechazo", na.rm = TRUE)
    sin_respuesta <- max(0L, as.integer(total) - effective_main - partial_main - refusal_main)
    completed_unlinked <- sum(!part_in_base & part_state_key == "completa", na.rm = TRUE)
    partial_unlinked <- sum(!part_in_base & part_state_key == "parcial", na.rm = TRUE)
    respondidas_plataforma <- effective_main + partial_main + refusal_main
    minimo <- .monitoreo_int(unit$minimum, NA_integer_)
    avance_minimo <- if (is.finite(minimo) && minimo > 0L) round(effective_main / minimo, 4) else NA_real_
    avance_total <- if (total > 0L) round(effective_main / total, 4) else NA_real_
    data.frame(
      Unidad = unit$label,
      Universo = as.integer(total),
      `Mínimo` = if (is.finite(minimo)) as.integer(minimo) else NA_integer_,
      `Respondidas plataforma` = as.integer(respondidas_plataforma),
      Efectivas = as.integer(effective_main),
      Completas = as.integer(effective_main),
      Parciales = as.integer(partial_main),
      Rechazos = as.integer(refusal_main),
      `Rechazos plataforma` = as.integer(refusal_main),
      `Rechazos telefónicos` = as.integer(rechazos_telefono),
      `Sin respuesta plataforma` = as.integer(sin_respuesta),
      `Sin respuesta` = as.integer(sin_respuesta),
      `Efectivas telefónicas` = as.integer(reconciliation$phone_effective),
      `Efectivas telefónicas conciliadas` = as.integer(reconciliation$phone_conciliated),
      `Efectivas telefónicas sin plataforma completa` = as.integer(reconciliation$phone_without_complete),
      `Respuestas plataforma sin cruce base` = as.integer(completed_unlinked + partial_unlinked + refusal_unlinked),
      `Efectivas sin cruce base` = as.integer(completed_unlinked),
      `Parciales sin cruce base` = as.integer(partial_unlinked),
      `Rechazos plataforma sin cruce base` = as.integer(refusal_unlinked),
      `Origen avance` = "Casos reconciliados",
      `Avance mínimo` = avance_minimo,
      `Avance total` = avance_total,
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
  })
  out <- do.call(rbind, rows)
  rownames(out) <- NULL
  out
}

.monitoreo_acreditacion_daily_from_case_rollup <- function(data, profile = list(), effective_only = FALSE, case_rollup = NULL) {
  rollup <- case_rollup
  if (is.null(rollup)) rollup <- .monitoreo_acreditacion_case_rollup_df(data, profile)
  if (!is.data.frame(rollup) || !nrow(rollup)) return(data.frame())
  units <- .monitoreo_report_units(profile, data)
  if (!length(units)) return(data.frame())
  actor_keys <- vapply(as.character(rollup$actor %||% ""), .monitoreo_report_unit_key, character(1))
  in_base <- .monitoreo_acreditacion_case_in_base(rollup)
  advancement <- as.character(rollup$advancement %||% "")
  include_mask <- if (isTRUE(effective_only)) {
    in_base & advancement %in% c("effective", "included_review")
  } else {
    in_base & advancement %in% c("effective", "included_review", "partial", "refusal")
  }
  dates <- trimws(as.character(rollup$date %||% ""))
  dates[!nzchar(dates) | is.na(dates)] <- "Sin fecha"
  dates_sorted <- sort(unique(dates[include_mask & nzchar(dates)]))
  if (!length(dates_sorted)) dates_sorted <- "Sin fecha"
  state_rows <- if (isTRUE(effective_only)) {
    list(effective = "Efectivas", included_review = "Efectivas")
  } else {
    list(effective = "Efectivas", included_review = "Efectivas", partial = "Parciales", refusal = "Rechazos plataforma")
  }
  rows <- list()
  for (unit in units) {
    actor_key <- .monitoreo_report_unit_key(unit$label)
    unit_mask <- actor_keys == actor_key
    for (state in names(state_rows)) {
      values <- vapply(dates_sorted, function(day) {
        sum(unit_mask & include_mask & advancement == state & dates == day, na.rm = TRUE)
      }, integer(1))
      label <- state_rows[[state]]
      existing_idx <- which(vapply(rows, function(row) {
        identical(as.character(row$Unidad[[1]]), unit$label) && identical(as.character(row$Estado[[1]]), label)
      }, logical(1)))
      if (length(existing_idx)) {
        current <- rows[[existing_idx[[1]]]]
        for (day in dates_sorted) current[[day]] <- as.integer(current[[day]]) + as.integer(values[[day]])
        current$Total <- as.integer(current$Total) + as.integer(sum(values))
        rows[[existing_idx[[1]]]] <- current
      } else {
        rows[[length(rows) + 1L]] <- as.data.frame(as.list(c(
          Unidad = unit$label,
          Estado = label,
          stats::setNames(as.list(as.integer(values)), dates_sorted),
          Total = as.integer(sum(values))
        )), check.names = FALSE, stringsAsFactors = FALSE)
      }
    }
  }
  if (!length(rows)) return(data.frame())
  out <- do.call(rbind, rows)
  rownames(out) <- NULL
  out
}

.monitoreo_acreditacion_daily_source_from_case_rollup <- function(data, profile = list(), by_collector = FALSE, config = list(), case_rollup = NULL) {
  rollup <- case_rollup
  if (is.null(rollup)) rollup <- .monitoreo_acreditacion_case_rollup_df(data, profile)
  if (!is.data.frame(rollup) || !nrow(rollup)) return(data.frame())
  in_base <- .monitoreo_acreditacion_case_in_base(rollup)
  advancement <- as.character(rollup$advancement %||% "")
  include_mask <- in_base & advancement %in% c("effective", "included_review", "partial", "refusal")
  if (!any(include_mask, na.rm = TRUE)) return(data.frame())
  dates <- trimws(as.character(rollup$date %||% ""))
  dates[!nzchar(dates) | is.na(dates)] <- "Sin fecha"
  dates_sorted <- sort(unique(dates[include_mask & nzchar(dates)]))
  if (!length(dates_sorted)) dates_sorted <- "Sin fecha"
  state_rows <- list(effective = "Efectivas", included_review = "Efectivas", partial = "Parciales", refusal = "Rechazos plataforma")
  source_id <- trimws(as.character(rollup$source_id %||% ""))
  source_label <- trimws(as.character(rollup$source_label %||% ""))
  source_label[!nzchar(source_label) | is.na(source_label)] <- "Respuestas"
  source_key <- ifelse(nzchar(source_id), source_id, source_label)
  channel <- trimws(as.character(rollup$channel %||% ""))
  collector_id <- trimws(as.character(rollup$collector_id %||% ""))
  collector_name <- trimws(as.character(rollup$collector_name %||% ""))
  collector_name[!nzchar(collector_name) | is.na(collector_name)] <- ""
  collector_type <- trimws(as.character(rollup$collector_type %||% ""))
  if (length(collector_type) != nrow(rollup)) collector_type <- rep("", nrow(rollup))
  if (isTRUE(by_collector)) {
    collector_lookup <- .monitoreo_collector_config_lookup(config)
    if (length(collector_lookup)) {
      for (i in seq_len(nrow(rollup))) {
        name_override <- .monitoreo_collector_config_value(
          collector_lookup,
          source_id[[i]] %||% "",
          collector_id[[i]] %||% "",
          "collector_name",
          ""
        )
        if (!nzchar(name_override)) {
          name_override <- .monitoreo_collector_config_value(
            collector_lookup,
            source_id[[i]] %||% "",
            collector_id[[i]] %||% "",
            "name",
            ""
          )
        }
        if (!nzchar(name_override)) {
          name_override <- .monitoreo_collector_config_value(
            collector_lookup,
            source_id[[i]] %||% "",
            collector_id[[i]] %||% "",
            "nombre",
            ""
          )
        }
        if (nzchar(name_override)) collector_name[[i]] <- name_override
        type_override <- .monitoreo_collector_config_value(
          collector_lookup,
          source_id[[i]] %||% "",
          collector_id[[i]] %||% "",
          "collector_type",
          ""
        )
        if (nzchar(type_override)) collector_type[[i]] <- type_override
        channel_override <- .monitoreo_collector_config_value(
          collector_lookup,
          source_id[[i]] %||% "",
          collector_id[[i]] %||% "",
          "channel",
          ""
        )
        if (!nzchar(channel_override)) {
          channel_override <- .monitoreo_collector_config_value(
            collector_lookup,
            source_id[[i]] %||% "",
            collector_id[[i]] %||% "",
            "canal",
            ""
          )
        }
        if (nzchar(channel_override)) channel[[i]] <- channel_override
      }
    }
  }
  collector_label <- vapply(seq_len(nrow(rollup)), function(i) {
    id <- collector_id[[i]]
    name <- collector_name[[i]]
    if (nzchar(id) && nzchar(name) && grepl(paste0("(", id, ")"), name, fixed = TRUE)) {
      return(name)
    }
    .monitoreo_internal_collector_label(id, name)
  }, character(1))
  collector_key <- ifelse(nzchar(collector_id), collector_id, collector_label)
  rows <- list()
  for (key in unique(source_key[include_mask])) {
    source_mask_base <- source_key == key
    collector_order <- if (isTRUE(by_collector)) unique(collector_key[source_mask_base & include_mask]) else ""
    for (collector in collector_order) {
      source_mask <- source_mask_base
      if (isTRUE(by_collector)) source_mask <- source_mask & collector_key == collector
      first_idx <- which(source_mask & include_mask)[[1]]
      for (state in names(state_rows)) {
        values <- vapply(dates_sorted, function(day) {
          sum(source_mask & include_mask & advancement == state & dates == day, na.rm = TRUE)
        }, integer(1))
        total <- as.integer(sum(values))
        if (!total) next
        row <- c(
          list(
            source_id = source_id[[first_idx]] %||% "",
            Fuente = source_label[[first_idx]] %||% "",
            Actor = rollup$actor[[first_idx]] %||% "",
            Canal = channel[[first_idx]] %||% ""
          ),
          if (isTRUE(by_collector)) list(
            collector_id = collector_id[[first_idx]] %||% "",
            Recopilador = collector_label[[first_idx]] %||% "",
            `Tipo recopilador` = collector_type[[first_idx]] %||% ""
          ) else list(),
          list(Estado = state_rows[[state]]),
          stats::setNames(as.list(as.integer(values)), dates_sorted),
          list(Total = total)
        )
        rows[[length(rows) + 1L]] <- as.data.frame(as.list(row), check.names = FALSE, stringsAsFactors = FALSE)
      }
    }
  }
  if (!length(rows)) return(data.frame())
  out <- do.call(rbind, rows)
  rownames(out) <- NULL
  out
}

.monitoreo_internal_totals_df <- function(cases_df, group_col, group_label = "grupo") {
  if (is.null(cases_df) || !is.data.frame(cases_df) || !nrow(cases_df) || !group_col %in% names(cases_df)) {
    return(data.frame())
  }
  group <- trimws(as.character(cases_df[[group_col]] %||% ""))
  group[!nzchar(group) | is.na(group)] <- "Sin dato"
  in_base <- .monitoreo_acreditacion_case_in_base(cases_df)
  advancement <- as.character(cases_df$advancement %||% "")
  counts_raw <- cases_df$counts_in_advance %||% rep(FALSE, nrow(cases_df))
  if (length(counts_raw) != nrow(cases_df)) counts_raw <- rep(FALSE, nrow(cases_df))
  counts_in_advance <- vapply(counts_raw, .monitoreo_bool, logical(1), default = FALSE)
  if (!"counts_in_advance" %in% names(cases_df)) {
    counts_in_advance <- in_base & advancement %in% c("effective", "included_review")
  }
  df <- data.frame(
    grupo = group,
    total = as.integer(in_base),
    efectivas = as.integer(counts_in_advance),
    parciales = as.integer(in_base & advancement == "partial"),
    rechazos = as.integer(in_base & advancement == "refusal"),
    pendientes = as.integer(in_base & advancement == "pending"),
    revision = as.integer(!in_base | !advancement %in% c("effective", "included_review", "partial", "refusal", "pending")),
    salen_de_pendientes = as.integer(cases_df$pending_exit %in% TRUE | cases_df$pending_exit == "TRUE"),
    stringsAsFactors = FALSE
  )
  out <- stats::aggregate(
    df[, c("total", "efectivas", "parciales", "rechazos", "pendientes", "revision", "salen_de_pendientes"), drop = FALSE],
    by = list(grupo = df$grupo),
    FUN = sum
  )
  names(out)[names(out) == "grupo"] <- group_label
  out <- out[order(-out$efectivas, -out$total, out[[group_label]]), , drop = FALSE]
  rownames(out) <- NULL
  out
}

.monitoreo_internal_case_issues <- function(cases_df) {
  if (is.null(cases_df) || !is.data.frame(cases_df) || !nrow(cases_df)) return(data.frame())
  rows <- list()
  for (i in seq_len(nrow(cases_df))) {
    type <- .monitoreo_scalar(cases_df$issue_type[[i]], "revision")
    if (type %in% c("efectiva_real", "sin_respuesta")) next
    rows[[length(rows) + 1L]] <- data.frame(
      issue_type = type,
      label = .monitoreo_internal_issue_label(type),
      severity = if (type %in% c("sin_llave", "fuera_base")) "alta" else "media",
      actor = cases_df$actor[[i]],
      case_key = cases_df$case_key[[i]],
      response_id = cases_df$response_id[[i]],
      count = 1L,
      detail = cases_df$rule[[i]],
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
  }
  key <- as.character(cases_df$case_key %||% "")
  key <- key[nzchar(key) & !is.na(key)]
  if (length(key)) {
    tab <- table(key)
    duplicated_keys <- names(tab)[tab > 1L]
    for (dup in duplicated_keys) {
      subset <- cases_df[cases_df$case_key == dup, , drop = FALSE]
      rows[[length(rows) + 1L]] <- data.frame(
        issue_type = "duplicado_caso",
        label = .monitoreo_internal_issue_label("duplicado_caso"),
        severity = "alta",
        actor = subset$actor[[1]],
        case_key = dup,
        response_id = paste(subset$response_id[nzchar(subset$response_id)], collapse = ", "),
        count = as.integer(nrow(subset)),
        detail = "Varias respuestas comparten la misma llave; el conteo interno prioriza completa válida sobre parcial o rechazo.",
        check.names = FALSE,
        stringsAsFactors = FALSE
      )
    }
  }
  if (!length(rows)) return(data.frame())
  out <- do.call(rbind, rows)
  rownames(out) <- NULL
  out
}

.monitoreo_internal_flow <- function(cases_df) {
  if (is.null(cases_df) || !is.data.frame(cases_df) || !nrow(cases_df)) {
    return(list(nodes = list(), links = list()))
  }
  base_result_key <- .monitoreo_text_key(cases_df$base_result %||% "")
  base_layer <- ifelse(
    cases_df$pending_exit %in% TRUE | cases_df$pending_exit == "TRUE",
    "Faltantes / barrido",
    ifelse(grepl("^cruzo", base_result_key), "En base", "Fuera de base")
  )
  stages <- data.frame(
    base = base_layer,
    channel = ifelse(nzchar(cases_df$channel), cases_df$channel, "Sin canal"),
    state = ifelse(nzchar(cases_df$platform_state), cases_df$platform_state, "Sin estado"),
    decision = ifelse(nzchar(cases_df$decision), cases_df$decision, "Sin decisión"),
    stringsAsFactors = FALSE
  )
  link_parts <- list(
    data.frame(source = stages$base, target = stages$channel, stringsAsFactors = FALSE),
    data.frame(source = stages$channel, target = stages$state, stringsAsFactors = FALSE),
    data.frame(source = stages$state, target = stages$decision, stringsAsFactors = FALSE)
  )
  links <- do.call(rbind, link_parts)
  links$value <- 1L
  links <- stats::aggregate(value ~ source + target, data = links, FUN = sum)
  links <- links[order(-links$value, links$source, links$target), , drop = FALSE]
  nodes <- unique(c(as.character(links$source), as.character(links$target)))
  nodes_df <- data.frame(
    id = vapply(nodes, .monitoreo_safe_name, character(1)),
    label = nodes,
    stringsAsFactors = FALSE
  )
  list(
    nodes = .monitoreo_report_records(nodes_df),
    links = .monitoreo_report_records(links)
  )
}

.monitoreo_acreditacion_internal_queries <- function(data, profile = list()) {
  if (is.null(data) || !is.data.frame(data) || !nrow(data)) return(.monitoreo_internal_empty_queries())
  profile <- monitoreo_normalize_profile(profile)
  response_mask <- .monitoreo_report_role_mask(data, "respuestas")
  base_mask <- .monitoreo_report_base_mask(data)
  if (!any(response_mask, na.rm = TRUE) && !any(base_mask, na.rm = TRUE)) {
    return(.monitoreo_internal_empty_queries())
  }
  response_rows <- data[response_mask, , drop = FALSE]
  response_idx <- which(response_mask)
  response_states <- .monitoreo_report_states(response_rows, profile)
  response_dates <- .monitoreo_report_date_values(response_rows)
  response_datetimes <- .monitoreo_report_datetime_values(response_rows)
  response_channels <- .monitoreo_report_channel_values(response_rows)
  response_actors <- .monitoreo_report_trace_actor_values(response_rows, profile)
  response_details <- .monitoreo_report_key_details(response_rows, profile, "respuesta")
  response_label_maps <- .monitoreo_source_variable_label_map(response_rows)
  response_question_columns <- .monitoreo_internal_real_question_columns(response_rows, response_label_maps)
  response_ids <- .monitoreo_report_response_ids(response_rows)
  response_person <- .monitoreo_report_person_values(response_rows)
  source_ids <- if (".source_id" %in% names(response_rows)) trimws(as.character(response_rows$.source_id %||% "")) else rep("", nrow(response_rows))
  source_labels <- if (".source_label" %in% names(response_rows)) trimws(as.character(response_rows$.source_label %||% "")) else rep("", nrow(response_rows))
  collector_ids <- .monitoreo_report_first_values(response_rows, c("collector_id", "id_recopilador", "recopilador_id"))
  collector_names <- .monitoreo_report_first_values(response_rows, c("collector_name", "Nombre recopilador", "nombre_recopilador", "Recopilador", "recopilador"))
  collector_types <- .monitoreo_report_first_values(response_rows, c("collector_type", "Tipo recopilador", "tipo_recopilador", "Collector Type"))

  base_index <- list()
  base_records <- list()
  has_base <- any(base_mask, na.rm = TRUE)
  if (has_base) {
    base_rows <- data[base_mask, , drop = FALSE]
    base_idx <- which(base_mask)
    base_details <- .monitoreo_report_key_details(base_rows, profile, "universo")
    base_sources <- if (".source_label" %in% names(base_rows)) as.character(base_rows$.source_label %||% "") else rep("", nrow(base_rows))
    base_source_ids <- if (".source_id" %in% names(base_rows)) as.character(base_rows$.source_id %||% "") else rep("", nrow(base_rows))
    base_roles <- if (".source_role" %in% names(base_rows)) as.character(base_rows$.source_role %||% "") else rep("", nrow(base_rows))
    base_status <- .monitoreo_report_status_values(base_rows)
    base_dates <- .monitoreo_report_date_values(base_rows)
    base_channels <- .monitoreo_report_channel_values(base_rows)
    base_actors <- .monitoreo_report_trace_actor_values(base_rows, profile)
    base_people <- .monitoreo_report_person_values(base_rows)
    base_responsibles <- .monitoreo_report_responsable_values(base_rows)
    base_ids <- .monitoreo_report_first_values(base_rows, c(
      "CodPulso", "Cod Pulso", "Cód Pulso", "Codigo Pulso", "Código Pulso", "Código PUCP", "Codigo PUCP",
      "Código", "Codigo", "ID", "id", "correo", "email", "E-mail", "CORREO PUCP",
      "Nombre", "Nombres", "Apellidos"
    ))
    base_ids[!nzchar(trimws(base_ids)) | is.na(base_ids)] <- paste0("Fila base ", base_idx[!nzchar(trimws(base_ids)) | is.na(base_ids)])
    for (i in seq_along(base_details)) {
      items <- base_details[[i]]
      if (!length(items)) next
      primary <- items[[1L]]
      item_keys <- unique(vapply(items, function(item) item$key %||% "", character(1)))
      item_keys <- item_keys[nzchar(item_keys)]
      base_record <- c(primary, list(
        row = base_idx[[i]],
        identifier = base_ids[[i]],
        source_id = base_source_ids[[i]],
        source = base_sources[[i]],
        role = base_roles[[i]],
        status = base_status[[i]],
        date = base_dates[[i]],
        channel = base_channels[[i]],
        actor = base_actors[[i]],
        person = base_people[[i]],
        responsible = base_responsibles[[i]],
        pending = .monitoreo_internal_pending_base(base_status[[i]], base_sources[[i]], base_roles[[i]]),
        all_keys = as.list(item_keys),
        key_details = items
      ))
      base_records[[length(base_records) + 1L]] <- base_record
      for (item in items) {
        key <- item$key %||% ""
        if (!nzchar(key)) next
        base <- c(item, list(
          row = base_idx[[i]],
          identifier = base_ids[[i]],
          source_id = base_source_ids[[i]],
          source = base_sources[[i]],
          role = base_roles[[i]],
          status = base_status[[i]],
          date = base_dates[[i]],
          channel = base_channels[[i]],
          actor = base_actors[[i]],
          person = base_people[[i]],
          responsible = base_responsibles[[i]],
          pending = .monitoreo_internal_pending_base(base_status[[i]], base_sources[[i]], base_roles[[i]]),
          all_keys = as.list(item_keys),
          key_details = items
        ))
        base_index <- .monitoreo_report_base_index_add(base_index, key, base)
      }
    }
  }
  sweep_base_crosswalk <- list()
  if (has_base) {
    sweep_mask <- .monitoreo_report_role_mask(data, "barrido") & !base_mask
    if (any(sweep_mask, na.rm = TRUE)) {
      sweep_rows <- data[sweep_mask, , drop = FALSE]
      sweep_details <- .monitoreo_report_key_details(sweep_rows, profile, "universo")
      sweep_actors <- .monitoreo_report_trace_actor_values(sweep_rows, profile)
      for (i in seq_along(sweep_details)) {
        items <- sweep_details[[i]]
        if (!length(items)) next
        canonical_base <- NULL
        canonical_detail <- NULL
        for (item in items) {
          candidate_base <- .monitoreo_report_base_index_lookup(base_index, item$key %||% "", sweep_actors[[i]])
          if (is.null(candidate_base)) next
          canonical_base <- candidate_base
          canonical_detail <- item
          break
        }
        if (is.null(canonical_base)) next
        actor_key <- .monitoreo_report_unit_key(sweep_actors[[i]] %||% "")
        for (item in items) {
          key <- item$key %||% ""
          if (!nzchar(key)) next
          sweep_base_crosswalk[[key]] <- c(sweep_base_crosswalk[[key]] %||% list(), list(list(
            base = canonical_base,
            detail = canonical_detail %||% item,
            actor_key = actor_key
          )))
        }
      }
    }
  }
  sweep_base_lookup <- function(key, actor) {
    key <- key %||% ""
    if (!nzchar(key)) return(NULL)
    entries <- sweep_base_crosswalk[[key]] %||% list()
    if (!length(entries)) return(NULL)
    actor_key <- .monitoreo_report_unit_key(actor %||% "")
    for (entry in entries) {
      entry_actor_key <- entry$actor_key %||% ""
      if (nzchar(actor_key) && nzchar(entry_actor_key) && !identical(actor_key, entry_actor_key)) next
      return(entry)
    }
    NULL
  }

  relevant <- response_states %in% c("Completa", "Parcial", "Rechazo")
  automatic_answered_base_keys <- character(0)
  if (has_base && any(relevant, na.rm = TRUE)) {
    for (i in which(relevant)) {
      details <- response_details[[i]]
      matched <- FALSE
      for (candidate in details) {
        candidate_base <- .monitoreo_report_base_index_lookup(base_index, candidate$key %||% "", response_actors[[i]])
        if (is.null(candidate_base)) next
        automatic_answered_base_keys <- c(
          automatic_answered_base_keys,
          unlist(candidate_base$all_keys %||% list(candidate$key %||% ""), use.names = FALSE)
        )
        matched <- TRUE
        break
      }
      if (!isTRUE(matched)) {
        for (candidate in details) {
          sweep_match <- sweep_base_lookup(candidate$key %||% "", response_actors[[i]])
          if (is.null(sweep_match)) next
          automatic_answered_base_keys <- c(
            automatic_answered_base_keys,
            unlist(sweep_match$base$all_keys %||% list(candidate$key %||% ""), use.names = FALSE)
          )
          matched <- TRUE
          break
        }
      }
      if (!isTRUE(matched)) {
        evidence <- .monitoreo_internal_declared_evidence(response_rows, i, details, response_label_maps)
        rescued <- .monitoreo_internal_email_base_rescue(base_index, evidence, response_actors[[i]])
        if (!is.null(rescued$base)) {
          automatic_answered_base_keys <- c(
            automatic_answered_base_keys,
            unlist(rescued$base$all_keys %||% list(rescued$detail$key %||% ""), use.names = FALSE)
          )
        }
      }
    }
    automatic_answered_base_keys <- unique(automatic_answered_base_keys[nzchar(automatic_answered_base_keys)])
  }

  cases <- list()
  answered_base_keys <- character(0)
  answered_base_rows <- character(0)
  mark_answered_base <- function(base, fallback_keys = character(0)) {
    keys <- unlist(base$all_keys %||% as.list(fallback_keys), use.names = FALSE)
    keys <- keys[nzchar(keys) & !is.na(keys)]
    if (length(keys)) answered_base_keys <<- c(answered_base_keys, keys)
    row <- .monitoreo_scalar(base$row %||% "", "")
    if (nzchar(row)) answered_base_rows <<- c(answered_base_rows, row)
    invisible(NULL)
  }
  for (i in which(relevant)) {
    details <- response_details[[i]]
    response_id <- response_ids[[i]] %||% ""
    result <- "Sin llave"
    detail <- list(key = "", type = "", column = "", label = "", value = "")
    base <- NULL
    evidence <- .monitoreo_internal_declared_evidence(response_rows, i, details, response_label_maps)
    email_rescue_code_mismatch <- FALSE
    if (length(details)) {
      detail <- details[[1L]]
      result <- if (has_base) "Sin cruce" else "Sin base configurada"
      if (has_base) {
        for (candidate in details) {
          candidate_base <- .monitoreo_report_base_index_lookup(base_index, candidate$key %||% "", response_actors[[i]])
          if (is.null(candidate_base)) next
          detail <- candidate
          base <- candidate_base
          result <- "Cruzó"
          mark_answered_base(candidate_base, candidate$key %||% "")
          break
        }
      }
    }
    if (is.null(base) && has_base) {
      for (candidate in details) {
        sweep_match <- sweep_base_lookup(candidate$key %||% "", response_actors[[i]])
        if (is.null(sweep_match)) next
        detail <- candidate
        base <- sweep_match$base
        result <- "Cruzó por barrido"
        mark_answered_base(base, candidate$key %||% "")
        break
      }
    }
    if (is.null(base) && has_base) {
      rescued <- .monitoreo_internal_email_base_rescue(base_index, evidence, response_actors[[i]])
      if (!is.null(rescued$base)) {
        detail <- rescued$detail
        base <- rescued$base
        result <- "Cruzó por correo"
        mark_answered_base(base, detail$key %||% "")
        declared_code <- .monitoreo_scalar(evidence$declared_code %||% "", "")
        official_code <- .monitoreo_internal_base_official_code(base)
        if (nzchar(declared_code) && nzchar(official_code)) {
          email_rescue_code_mismatch <- !any(.monitoreo_code_keys(declared_code) %in% .monitoreo_code_keys(official_code))
        }
      }
    }
    assisted_review <- .monitoreo_internal_assisted_review(
      evidence = evidence,
      response_actor = response_actors[[i]],
      response_id = response_id,
      response_state = response_states[[i]],
      result = result,
      base_records = base_records,
      answered_base_keys = automatic_answered_base_keys,
      current_base = base,
      profile = profile
    )
    manual_decision <- assisted_review$manual_decision %||% NULL
    manual_include_requested <- !is.null(manual_decision) &&
      identical(.monitoreo_scalar(manual_decision$action, ""), "include_with_caveat")
    manual_include_with_base <- FALSE
    if (isTRUE(manual_include_requested)) {
      assigned_base <- .monitoreo_internal_find_base_by_candidate(
        base_records,
        .monitoreo_scalar(manual_decision$assigned_case_key, ""),
        response_actors[[i]]
      )
      if (!is.null(assigned_base)) {
        manual_include_with_base <- TRUE
        mark_answered_base(assigned_base)
        base <- assigned_base
        result <- "Cruzó manualmente"
        detail <- list(
          key = assigned_base$key %||% "",
          type = assigned_base$type %||% "",
          column = assigned_base$column %||% "",
          label = assigned_base$label %||% "",
          value = assigned_base$value %||% "",
          configured = assigned_base$configured %||% FALSE
        )
      }
    }
    decision <- .monitoreo_internal_decision_for(result, response_id, profile, has_base = has_base)
    if (isTRUE(manual_include_requested) && !isTRUE(manual_include_with_base)) {
      decision <- list(
        label = "Excluido del avance",
        note = "Decision manual sin persona vigente del universo/base; queda fuera hasta reasignar un registro valido."
      )
    }
    if (isTRUE(email_rescue_code_mismatch)) {
      decision$note <- "Incluido automaticamente: el correo exacto cruza con una persona del universo, pero el codigo declarado difiere del codigo base."
    }
    advancement <- .monitoreo_internal_advancement(
      response_states[[i]],
      decision$label,
      manual_include = manual_include_with_base
    )
    issue_type <- .monitoreo_internal_issue_type(response_states[[i]], result, advancement, detail$key %||% "")
    if (isTRUE(email_rescue_code_mismatch) && advancement %in% c("effective", "included_review")) {
      issue_type <- "incluido_con_salvedad"
    }
    if (isTRUE(manual_include_with_base) && advancement %in% c("effective", "included_review")) {
      issue_type <- "incluido_con_salvedad"
    }
    collector_label <- .monitoreo_internal_collector_label(collector_ids[[i]], collector_names[[i]])
    case_channel <- response_channels[[i]] %||% ""
    if (!is.null(base)) {
      base_responsible <- .monitoreo_scalar(base$responsible %||% "", "")
      base_responsible_key <- .monitoreo_text_key(base_responsible)
      base_channel_key <- .monitoreo_text_key(paste(
        response_channels[[i]] %||% "",
        base$channel %||% "",
        base$source %||% "",
        base$role %||% ""
      ))
      if (nzchar(base_responsible) &&
          !grepl("sin responsable|sin asignar|no asignad", base_responsible_key) &&
          grepl("telefon|barrido|llamada", base_channel_key)) {
        collector_label <- base_responsible
        case_channel <- base$channel %||% "Telefónico"
      }
    }
    base_pending <- isTRUE(base$pending %||% FALSE)
    recovery_collector <- .monitoreo_internal_is_recovery_collector(collector_ids[[i]], collector_names[[i]], source_labels[[i]])
    pending_exit <- identical(advancement, "effective") && (base_pending || recovery_collector)
    person <- response_person[[i]]
    if (!is.null(base) && nzchar(base$person %||% "")) person <- base$person %||% ""
    if (!nzchar(person) && !is.null(base)) person <- base$identifier %||% ""
    if (!nzchar(person)) person <- detail$value %||% detail$key %||% response_id
    partial_info <- .monitoreo_internal_partial_diagnostics(
      response_rows,
      i,
      source_label_maps = response_label_maps,
      question_columns = response_question_columns
    )
    key_strategy <- .monitoreo_internal_key_strategy(case_channel, source_labels[[i]] %||% "", details)
    phone_audit <- if (identical(key_strategy, "telefono_enlace_y_codigo_final")) {
      .monitoreo_internal_phone_audit(
        response_rows,
        i,
        response_actor = response_actors[[i]],
        base = base,
        base_index = base_index,
        source_label_maps = response_label_maps
      )
    } else {
      list()
    }
    if (is.list(phone_audit) &&
        identical(.monitoreo_scalar(phone_audit$phone_match_level, ""), "conflicto")) {
      decision <- list(
        label = "Excluido del avance",
        note = "Revisión telefónica necesaria: el enlace usado y el código final escrito apuntan a personas distintas."
      )
      advancement <- "excluded"
      issue_type <- "conflicto_telefonico"
      pending_exit <- FALSE
    }
    identity_status <- .monitoreo_internal_identity_status(
      result,
      advancement,
      issue_type,
      phone_audit,
      partial_info
    )
    if (isTRUE(email_rescue_code_mismatch) && identical(identity_status, "identificado")) {
      identity_status <- "identificado_con_salvedad"
    }
    primary_identity_label <- "Llave usada"
    primary_identity_value <- detail$value %||% detail$key %||% ""
    secondary_identity_label <- "Evidencia secundaria"
    secondary_identity_value <- ""
    if (identical(key_strategy, "telefono_enlace_y_codigo_final")) {
      primary_identity_label <- "Enlace usado"
      primary_identity_value <- .monitoreo_scalar(phone_audit$cv_id %||% "", "")
      secondary_identity_label <- "Código final"
      secondary_identity_value <- .monitoreo_scalar(phone_audit$final_codpulso %||% "", "")
      if (!nzchar(secondary_identity_value)) {
        secondary_identity_label <- "Celular declarado"
        secondary_identity_value <- .monitoreo_scalar(phone_audit$declared_phone %||% "", "")
      }
    } else if (identical(key_strategy, "correo_envio")) {
      recipient_email <- .monitoreo_scalar(evidence$recipient_email %||% "", "")
      declared_email <- .monitoreo_scalar(evidence$declared_email %||% "", "")
      if (nzchar(recipient_email)) {
        primary_identity_label <- "Correo del envío"
        primary_identity_value <- recipient_email
        secondary_identity_label <- if (nzchar(declared_email) && !identical(.monitoreo_email_key(declared_email), .monitoreo_email_key(recipient_email))) {
          "Correo declarado"
        } else {
          "Código declarado"
        }
        secondary_identity_value <- if (identical(secondary_identity_label, "Correo declarado")) declared_email else evidence$declared_code %||% ""
      } else {
        primary_identity_label <- if (nzchar(declared_email)) "Correo observado en respuesta" else "Llave usada"
        primary_identity_value <- if (nzchar(declared_email)) declared_email else primary_identity_value
        secondary_identity_label <- "Código declarado"
        secondary_identity_value <- evidence$declared_code %||% ""
      }
    } else {
      primary_identity_label <- if (nzchar(evidence$declared_code %||% "")) "Código PUCP declarado" else "Llave usada"
      primary_identity_value <- evidence$declared_code %||% primary_identity_value
      secondary_identity_label <- if (nzchar(evidence$declared_email %||% "")) "Correo declarado" else "Dato complementario"
      secondary_identity_value <- evidence$declared_email %||% ""
    }
    review_priority <- switch(identity_status,
      conflicto_telefonico = 100L,
      no_identificable = 90L,
      fuera_base = 82L,
      parcial_revisable = 68L,
      revision = 50L,
      20L
    )
    case_key <- detail$key %||% ""
    if (!is.null(base)) {
      canonical_case_key <- .monitoreo_internal_candidate_id(base)
      if (nzchar(canonical_case_key)) case_key <- canonical_case_key
    }
    cases[[length(cases) + 1L]] <- data.frame(
      actor = response_actors[[i]],
      person_label = person,
      case_key = case_key,
      response_id = response_id,
      date = response_dates[[i]],
      response_datetime = response_datetimes[[i]] %||% "",
      source_id = source_ids[[i]] %||% "",
      source_label = source_labels[[i]] %||% "",
      channel = case_channel,
      collector_id = collector_ids[[i]] %||% "",
      collector_name = collector_label,
      collector_type = collector_types[[i]] %||% "",
      platform_state = response_states[[i]],
      base_result = result,
      base_record = base$identifier %||% "",
      base_source = base$source %||% "",
      base_status = base$status %||% "",
      decision = decision$label %||% "",
      decision_reason = decision$note %||% "",
      advancement = advancement,
      issue_type = issue_type,
      rule = .monitoreo_internal_case_rule(result, issue_type),
      pending_exit = pending_exit,
      recovery_collector = recovery_collector,
      response_row = as.integer(response_idx[[i]]),
      partial_answered_questions = as.integer(partial_info$answered %||% 0L),
      partial_total_questions = as.integer(partial_info$total %||% 0L),
      partial_completion_pct = as.integer(partial_info$pct %||% 0L),
      partial_last_question = partial_info$last %||% "",
      partial_next_question = partial_info$next_question %||% "",
      duplicate_group_key = "",
      duplicate_group_size = 1L,
      counts_in_advance = FALSE,
      duplicate_counting_status = "",
      identity_status = identity_status,
      identity_label = .monitoreo_internal_identity_label(identity_status),
      channel_key_strategy = key_strategy,
      channel_key_strategy_label = .monitoreo_internal_strategy_label(key_strategy),
      primary_identity_label = primary_identity_label,
      primary_identity_value = primary_identity_value,
      secondary_identity_label = secondary_identity_label,
      secondary_identity_value = secondary_identity_value,
      review_priority = as.integer(review_priority),
      phone_audit = I(list(phone_audit %||% list())),
      assisted_review = I(list(assisted_review %||% list())),
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
  }
  answered_base_keys <- unique(answered_base_keys[nzchar(answered_base_keys)])
  answered_base_rows <- unique(answered_base_rows[nzchar(answered_base_rows)])
  if (length(base_records)) {
    for (base in base_records) {
      base_row <- .monitoreo_scalar(base$row %||% "", "")
      if (nzchar(base_row)) {
        if (base_row %in% answered_base_rows) next
      } else {
        base_keys <- unlist(base$all_keys %||% list(base$key %||% ""), use.names = FALSE)
        base_keys <- unique(base_keys[nzchar(base_keys)])
        if (length(base_keys) && any(base_keys %in% answered_base_keys)) next
      }
      person <- base$person %||% ""
      if (!nzchar(person)) person <- base$identifier %||% base$value %||% base$key %||% ""
      cases[[length(cases) + 1L]] <- data.frame(
        actor = base$actor %||% "",
        person_label = person,
        case_key = base$key %||% "",
        response_id = "",
        date = base$date %||% "Sin fecha",
        response_datetime = "",
        source_id = base$source_id %||% "",
        source_label = base$source %||% "",
        channel = base$channel %||% "",
        collector_id = "",
        collector_name = base$responsible %||% "Sin responsable",
        collector_type = "",
        platform_state = "Sin respuesta",
        base_result = "Cruzó",
        base_record = base$identifier %||% "",
        base_source = base$source %||% "",
        base_status = base$status %||% "",
        decision = "Pendiente de respuesta",
        decision_reason = "Existe en la base del corte y no tiene respuesta SurveyMonkey reconciliada.",
        advancement = "pending",
        issue_type = "sin_respuesta",
        rule = "Caso en base sin respuesta reconciliada; queda para seguimiento operativo.",
        pending_exit = FALSE,
        recovery_collector = FALSE,
        response_row = NA_integer_,
        partial_answered_questions = 0L,
        partial_total_questions = 0L,
        partial_completion_pct = 0L,
        partial_last_question = "",
        partial_next_question = "",
        duplicate_group_key = "",
        duplicate_group_size = 1L,
        counts_in_advance = FALSE,
        duplicate_counting_status = "",
        identity_status = "pendiente_base",
        identity_label = .monitoreo_internal_identity_label("pendiente_base"),
        channel_key_strategy = "base_sin_respuesta",
        channel_key_strategy_label = "Base sin respuesta",
        primary_identity_label = "Llave en base",
        primary_identity_value = base$key %||% "",
        secondary_identity_label = "Responsable",
        secondary_identity_value = base$responsible %||% "",
        review_priority = 10L,
        phone_audit = I(list(list())),
        assisted_review = I(list(list())),
        check.names = FALSE,
        stringsAsFactors = FALSE
      )
    }
  }
  if (!length(cases)) return(.monitoreo_internal_empty_queries())

  cases_df <- .monitoreo_internal_records_to_df(cases)
  key <- as.character(cases_df$case_key %||% "")
  actor_key <- vapply(as.character(cases_df$actor %||% ""), .monitoreo_report_unit_key, character(1))
  actor_key[!nzchar(actor_key) | is.na(actor_key)] <- "sin_actor"
  fallback <- as.character(cases_df$response_id %||% rep("", nrow(cases_df)))
  response_row <- as.character(cases_df$response_row %||% rep("", nrow(cases_df)))
  state_key <- vapply(as.character(cases_df$platform_state %||% ""), .monitoreo_text_key, character(1))
  duplicate_group_key <- ifelse(nzchar(key) & !is.na(key), paste(actor_key, key, sep = "\r"), key)
  missing_duplicate_key <- !nzchar(duplicate_group_key) | is.na(duplicate_group_key)
  has_response_id <- missing_duplicate_key & nzchar(fallback) & !is.na(fallback)
  duplicate_group_key[has_response_id] <- paste(actor_key[has_response_id], "response", fallback[has_response_id], sep = "\r")
  missing_duplicate_key <- !nzchar(duplicate_group_key) | is.na(duplicate_group_key)
  has_response_row <- missing_duplicate_key & nzchar(response_row) & !is.na(response_row)
  duplicate_group_key[has_response_row] <- paste(actor_key[has_response_row], "response_row", response_row[has_response_row], sep = "\r")
  missing_duplicate_key <- !nzchar(duplicate_group_key) | is.na(duplicate_group_key)
  duplicate_group_key[missing_duplicate_key] <- paste(actor_key[missing_duplicate_key], "event", state_key[missing_duplicate_key], seq_len(nrow(cases_df))[missing_duplicate_key], sep = "\r")
  duplicate_count <- rep(1L, nrow(cases_df))
  for (dup_key in unique(duplicate_group_key[nzchar(duplicate_group_key) & !is.na(duplicate_group_key)])) {
    idx <- which(duplicate_group_key == dup_key)
    duplicate_count[idx] <- length(idx)
  }
  cases_df$duplicate_group_key <- duplicate_group_key
  cases_df$duplicate_group_size <- duplicate_count
  cases_df$duplicate_count <- duplicate_count
  cases_df$issue_type[duplicate_count > 1L & cases_df$issue_type == "efectiva_real"] <- "efectiva_real"
  duplicate_identity <- duplicate_count > 1L &
    !as.character(cases_df$identity_status %||% "") %in% c("conflicto_telefonico", "no_identificable", "fuera_base")
  cases_df$identity_status[duplicate_identity] <- "duplicado"
  cases_df$identity_label <- vapply(as.character(cases_df$identity_status %||% ""), .monitoreo_internal_identity_label, character(1))
  review_priority <- suppressWarnings(as.integer(cases_df$review_priority %||% 0L))
  review_priority[!is.finite(review_priority)] <- 0L
  cases_df$review_priority <- pmax(review_priority, ifelse(duplicate_count > 1L, 72L, 0L))

  deduped <- .monitoreo_internal_deduplicate_cases(cases_df)
  row_id <- paste(cases_df$response_id %||% "", cases_df$case_key %||% "", cases_df$response_row %||% "", sep = "\r")
  kept_id <- paste(deduped$response_id %||% "", deduped$case_key %||% "", deduped$response_row %||% "", sep = "\r")
  cases_df_in_base <- .monitoreo_acreditacion_case_in_base(cases_df)
  cases_df$counts_in_advance <- cases_df_in_base & cases_df$advancement %in% c("effective", "included_review") & row_id %in% kept_id
  cases_df$duplicate_counting_status <- ifelse(
    cases_df$counts_in_advance,
    "Cuenta en avance",
    ifelse(cases_df$duplicate_group_size > 1L, "No cuenta por duplicado o estado", "No cuenta")
  )
  deduped <- cases_df[row_id %in% kept_id, , drop = FALSE]
  pending_exit_df <- deduped[deduped$pending_exit %in% TRUE | deduped$pending_exit == "TRUE", , drop = FALSE]
  issues_df <- .monitoreo_internal_case_issues(cases_df)
  flow <- .monitoreo_internal_flow(deduped)
  case_rollup_df <- deduped[.monitoreo_acreditacion_case_in_base(deduped), , drop = FALSE]

  list(
    schema = "monitoreo_acreditacion_internal_queries_v1",
    cases = .monitoreo_report_records(cases_df),
    case_rollup = .monitoreo_report_records(case_rollup_df),
    totals = list(
      actor = .monitoreo_report_records(.monitoreo_internal_totals_df(deduped, "actor", "actor")),
      date = .monitoreo_report_records(.monitoreo_internal_totals_df(deduped, "date", "date")),
      channel = .monitoreo_report_records(.monitoreo_internal_totals_df(deduped, "channel", "channel")),
      source = .monitoreo_report_records(.monitoreo_internal_totals_df(deduped, "source_label", "source")),
      collector = .monitoreo_report_records(.monitoreo_internal_totals_df(deduped, "collector_name", "collector"))
    ),
    pending_exit = .monitoreo_report_records(pending_exit_df),
    issues = .monitoreo_report_records(issues_df),
    flow = flow
  )
}

.monitoreo_client_report_model <- function(data, config = list(), generated_at = NULL, detail = c("full", "advance_summary"), case_rollup = NULL) {
  detail <- match.arg(detail)
  summary_only <- identical(detail, "advance_summary")
  cfg <- monitoreo_normalize_config(config, data)
  data <- .monitoreo_filter_disabled_collectors(data, cfg)
  profile <- cfg$monitoreo_profile %||% monitoreo_normalize_profile(list())
  if (is.null(case_rollup)) {
    case_rollup <- .monitoreo_acreditacion_case_rollup_df(data, profile)
  }
  resumen <- .monitoreo_report_summary_df(data, profile, case_rollup = case_rollup)
  avance_general <- .monitoreo_report_daily_df(data, profile, FALSE, case_rollup = case_rollup)
  avance_fuente <- .monitoreo_report_daily_source_df(data, profile, config = cfg, case_rollup = case_rollup)
  avance_recopilador <- if (isTRUE(summary_only)) data.frame() else .monitoreo_report_daily_source_df(data, profile, by_collector = TRUE, config = cfg, case_rollup = case_rollup)
  controles <- if (isTRUE(summary_only)) data.frame() else .monitoreo_report_control_distribution_df(data, profile)
  if (is.null(generated_at) || !nzchar(as.character(generated_at))) generated_at <- .monitoreo_now_iso()

  if (!nrow(resumen)) {
    empty_summary <- data.frame(
      Indicador = c("Actores reportados", "Efectivas", "Parciales", "Rechazos plataforma", "Sin respuesta", "Universo"),
      Valor = c(0L, 0L, 0L, 0L, 0L, 0L),
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
    return(list(
      schema = "monitoreo_client_report_v1",
      generated_at = generated_at,
      title = "Reporte de avance para cliente",
      summary = .monitoreo_report_records(empty_summary),
      actors = list(),
      daily_general = list(),
      daily_actor = list(),
      sources = list(),
      collector_sources = list(),
      controls = list(),
      client_report = cfg$client_report %||% .monitoreo_client_report_config(list()),
      has_targets = FALSE,
      sheets = list()
    ))
  }

  safe_num <- function(x, default = 0) {
    out <- suppressWarnings(as.numeric(x))
    out[!is.finite(out)] <- default
    out
  }
  raw_sin_respuesta <- resumen$`Sin respuesta`
  sin_respuesta_values <- if (is.null(raw_sin_respuesta)) rep(NA_real_, nrow(resumen)) else safe_num(raw_sin_respuesta, NA_real_)
  actor_df <- data.frame(
    Actor = as.character(resumen$Unidad %||% ""),
    Universo = as.integer(safe_num(resumen$Universo)),
    Efectivas = as.integer(safe_num(resumen$Efectivas %||% resumen$Completas)),
    Parciales = as.integer(safe_num(resumen$Parciales)),
    `Rechazos plataforma` = as.integer(.monitoreo_publication_platform_refusal_values(resumen)),
    `Sin respuesta plataforma` = as.integer(safe_num(resumen$`Sin respuesta plataforma` %||% resumen$`Sin respuesta`)),
    `Sin respuesta` = as.integer(sin_respuesta_values),
    Meta = as.integer(safe_num(resumen$Mínimo, NA_real_)),
    `Origen avance` = as.character(resumen$`Origen avance` %||% ""),
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
  fallback_sin_respuesta <- pmax(
    0L,
    actor_df$Universo - actor_df$Efectivas - actor_df$Parciales - actor_df$`Rechazos plataforma`
  )
  missing_sin_respuesta <- !is.finite(actor_df$`Sin respuesta`)
  actor_df$`Sin respuesta`[missing_sin_respuesta] <- fallback_sin_respuesta[missing_sin_respuesta]
  actor_df$`Sin respuesta` <- as.integer(pmax(0L, actor_df$`Sin respuesta`))
  actor_df$`Sin respuesta plataforma`[!is.finite(actor_df$`Sin respuesta plataforma`)] <- actor_df$`Sin respuesta`[!is.finite(actor_df$`Sin respuesta plataforma`)]
  actor_df$Meta[!is.finite(actor_df$Meta)] <- NA_integer_
  actor_df$`Referencia operativa` <- actor_df$Meta
  actor_df$`Referencia etiqueta` <- ifelse(!is.na(actor_df$Meta), "Mínimo a alcanzar", "")
  actor_df$`Avance universo` <- vapply(seq_len(nrow(actor_df)), function(i) {
    .monitoreo_client_report_pct(actor_df$Efectivas[[i]], actor_df$Universo[[i]])
  }, numeric(1))
  actor_df$`Avance meta` <- vapply(seq_len(nrow(actor_df)), function(i) {
    .monitoreo_client_report_pct(actor_df$Efectivas[[i]], actor_df$Meta[[i]])
  }, numeric(1))
  actor_df$`Brecha meta` <- ifelse(is.na(actor_df$Meta), NA_integer_, pmax(0L, actor_df$Meta - actor_df$Efectivas))

  date_cols <- .monitoreo_client_report_date_cols(avance_general)
  safe_as_date <- function(value) {
    tryCatch(suppressWarnings(as.Date(as.character(value))), error = function(e) as.Date(NA))
  }
  safe_as_date_vec <- function(values) {
    as.Date(vapply(values, function(value) {
      parsed <- safe_as_date(value)
      if (is.na(parsed)) NA_character_ else as.character(parsed)
    }, character(1)))
  }
  normalize_daily_date <- function(value) {
    raw <- trimws(as.character(value %||% ""))
    if (!nzchar(raw) || is.na(raw)) return("")
    parsed <- safe_as_date(raw)
    if (is.na(parsed)) {
      parsed <- tryCatch(
        suppressWarnings(as.Date(raw, tryFormats = c("%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%d-%m-%Y", "%b %d", "%B %d"))),
        error = function(e) as.Date(NA)
      )
    }
    if (is.na(parsed) && grepl("^[A-Za-z]{3,9}\\s+[0-9]{1,2}$", raw, perl = TRUE)) {
      year <- as.integer(format(Sys.Date(), "%Y"))
      parsed <- tryCatch(
        suppressWarnings(as.Date(paste(raw, year), tryFormats = c("%b %d %Y", "%B %d %Y"))),
        error = function(e) as.Date(NA)
      )
    }
    if (!is.na(parsed)) as.character(parsed) else raw
  }
  complete_daily_calendar <- function(df, actor_levels = character(0)) {
    df <- .monitoreo_workbook_df(df)
    base <- data.frame(
      Actor = character(),
      Fecha = character(),
      Efectivas = integer(),
      Parciales = integer(),
      `Rechazos plataforma` = integer(),
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
    if (!nrow(df)) return(base)
    df$Fecha <- vapply(df$Fecha, normalize_daily_date, character(1))
    df <- df[nzchar(as.character(df$Fecha)), , drop = FALSE]
    if (!nrow(df)) return(base)
    parsed <- safe_as_date_vec(as.character(df$Fecha))
    can_complete <- any(!is.na(parsed))
    if (!isTRUE(can_complete)) {
      df <- df[order(df$Actor, df$Fecha), , drop = FALSE]
      rownames(df) <- NULL
      return(df)
    }
    valid_dates <- parsed[!is.na(parsed)]
    all_dates <- as.character(seq(min(valid_dates), max(valid_dates), by = "day"))
    actors <- unique(c(actor_levels, as.character(df$Actor)))
    actors <- actors[nzchar(actors) & !is.na(actors)]
    if (!length(actors)) actors <- "Sin actor"
    grid <- expand.grid(Actor = actors, Fecha = all_dates, stringsAsFactors = FALSE)
    key <- paste(as.character(df$Actor), as.character(df$Fecha), sep = "\r")
    sums <- stats::aggregate(
      df[, c("Efectivas", "Parciales", "Rechazos plataforma"), drop = FALSE],
      by = list(key = key),
      FUN = sum
    )
    lookup <- setNames(seq_len(nrow(sums)), sums$key)
    grid_key <- paste(grid$Actor, grid$Fecha, sep = "\r")
    idx <- unname(lookup[grid_key])
    for (col in c("Efectivas", "Parciales", "Rechazos plataforma")) {
      values <- rep(0L, nrow(grid))
      hit <- !is.na(idx)
      values[hit] <- as.integer(safe_num(sums[[col]][idx[hit]], 0))
      grid[[col]] <- values
    }
    grid <- grid[order(grid$Actor, grid$Fecha), , drop = FALSE]
    rownames(grid) <- NULL
    grid
  }
  is_platform_refusal_state <- function(state) {
    grepl("rechazo", state) && !grepl("telefon", state)
  }
  actor_daily_map <- list()
  if (nrow(avance_general) && length(date_cols)) {
    for (i in seq_len(nrow(avance_general))) {
      actor <- as.character(avance_general$Unidad[[i]] %||% "")
      state <- .monitoreo_text_key(avance_general$Estado[[i]] %||% "")
      if (grepl("rechazo", state) && !isTRUE(is_platform_refusal_state(state))) next
      for (day in date_cols) {
        value <- as.integer(safe_num(avance_general[[day]][[i]], 0))
        if (value <= 0L) next
        day_key <- normalize_daily_date(day)
        key <- paste(actor, day_key, sep = "\r")
        current <- actor_daily_map[[key]]
        if (is.null(current)) current <- list(Actor = actor, Fecha = day_key, Efectivas = 0L, Parciales = 0L, `Rechazos plataforma` = 0L)
        if (grepl("efectiva|completa", state)) current$Efectivas <- current$Efectivas + value
        else if (grepl("parcial", state)) current$Parciales <- current$Parciales + value
        else if (isTRUE(is_platform_refusal_state(state))) current$`Rechazos plataforma` <- current$`Rechazos plataforma` + value
        actor_daily_map[[key]] <- current
      }
    }
  }
  actor_daily <- if (length(actor_daily_map)) {
    do.call(rbind, lapply(actor_daily_map, function(row) as.data.frame(row, check.names = FALSE, stringsAsFactors = FALSE)))
  } else {
    data.frame(Actor = character(), Fecha = character(), Efectivas = integer(), Parciales = integer(), `Rechazos plataforma` = integer(), check.names = FALSE)
  }
  actor_daily <- complete_daily_calendar(actor_daily, actor_df$Actor %||% character(0))
  if (nrow(actor_daily)) {
    actor_daily <- actor_daily[order(actor_daily$Actor, actor_daily$Fecha), , drop = FALSE]
    actor_daily$`Total respuestas` <- actor_daily$Efectivas + actor_daily$Parciales + actor_daily$`Rechazos plataforma`
    actor_daily$Acumulado <- ave(actor_daily$Efectivas, actor_daily$Actor, FUN = cumsum)
  } else {
    actor_daily$`Total respuestas` <- integer(0)
    actor_daily$Acumulado <- integer(0)
  }

  daily_general <- if (nrow(actor_daily)) {
    agg <- stats::aggregate(
      actor_daily[, c("Efectivas", "Parciales", "Rechazos plataforma"), drop = FALSE],
      by = list(Fecha = actor_daily$Fecha),
      FUN = sum
    )
    agg <- agg[order(agg$Fecha), , drop = FALSE]
    agg$`Total respuestas` <- agg$Efectivas + agg$Parciales + agg$`Rechazos plataforma`
    agg$Acumulado <- cumsum(agg$Efectivas)
    agg
  } else {
    data.frame(Fecha = character(), Efectivas = integer(), Parciales = integer(), `Rechazos plataforma` = integer(), `Total respuestas` = integer(), Acumulado = integer(), check.names = FALSE)
  }

  build_source_summary <- function(source_progress, include_collector = FALSE) {
    source_progress <- .monitoreo_workbook_df(source_progress)
    source_map <- list()
    if (nrow(source_progress)) {
      source_dates <- .monitoreo_client_report_date_cols(source_progress)
      for (i in seq_len(nrow(source_progress))) {
        state <- .monitoreo_text_key(source_progress$Estado[[i]] %||% "")
        if (grepl("rechazo", state) && !isTRUE(is_platform_refusal_state(state))) next
        values <- as.integer(safe_num(unlist(source_progress[i, source_dates, drop = TRUE], use.names = FALSE), 0))
        total <- sum(values, na.rm = TRUE)
        if (total <= 0L) next
        active_dates <- source_dates[values > 0L]
        collector_label <- as.character(source_progress$Recopilador[[i]] %||% "")
        collector_id <- as.character(source_progress$collector_id[[i]] %||% "")
        collector_type <- as.character(source_progress$`Tipo recopilador`[[i]] %||% "")
        key <- paste(
          as.character(source_progress$source_id[[i]] %||% ""),
          source_progress$Actor[[i]] %||% "",
          source_progress$Canal[[i]] %||% "",
          source_progress$Fuente[[i]] %||% "",
          if (isTRUE(include_collector)) collector_id else "",
          if (isTRUE(include_collector)) collector_label else "",
          sep = "\r"
        )
        current <- source_map[[key]]
        if (is.null(current)) {
          current <- c(
            list(
              source_id = as.character(source_progress$source_id[[i]] %||% ""),
              Actor = as.character(source_progress$Actor[[i]] %||% "Sin actor"),
              Canal = as.character(source_progress$Canal[[i]] %||% "Sin canal"),
              Fuente = as.character(source_progress$Fuente[[i]] %||% "Encuesta")
            ),
            if (isTRUE(include_collector)) list(
              Recopilador = if (nzchar(collector_label)) collector_label else "Sin recopilador",
              collector_id = collector_id,
              `Tipo recopilador` = collector_type
            ) else list(),
            list(
              Efectivas = 0L,
              Parciales = 0L,
              `Rechazos plataforma` = 0L,
              `Primer día` = "",
              `Última respuesta` = "",
              `Última efectiva` = ""
            )
          )
        }
        if (grepl("efectiva|completa", state)) {
          current$Efectivas <- current$Efectivas + total
          if (length(active_dates)) current$`Última efectiva` <- active_dates[[length(active_dates)]]
        } else if (grepl("parcial", state)) {
          current$Parciales <- current$Parciales + total
        } else if (grepl("rechazo", state)) {
          current$`Rechazos plataforma` <- current$`Rechazos plataforma` + total
        }
        if (length(active_dates)) {
          if (!nzchar(current$`Primer día`)) current$`Primer día` <- active_dates[[1]]
          current$`Última respuesta` <- active_dates[[length(active_dates)]]
        }
        source_map[[key]] <- current
      }
    }
    out <- if (length(source_map)) {
      do.call(rbind, lapply(source_map, function(row) as.data.frame(row, check.names = FALSE, stringsAsFactors = FALSE)))
    } else {
      base_cols <- list(
        source_id = character(), Actor = character(), Canal = character(), Fuente = character()
      )
      collector_cols <- if (isTRUE(include_collector)) list(Recopilador = character(), collector_id = character(), `Tipo recopilador` = character()) else list()
      as.data.frame(c(base_cols, collector_cols, list(
        Efectivas = integer(), Parciales = integer(), `Rechazos plataforma` = integer(),
        `Primer día` = character(), `Última respuesta` = character(), `Última efectiva` = character()
      )), check.names = FALSE)
    }
    if (nrow(out)) {
      out$`Total respuestas` <- out$Efectivas + out$Parciales + out$`Rechazos plataforma`
    } else {
      out$`Total respuestas` <- integer(0)
    }
    rownames(out) <- NULL
    out
  }
  sources_df <- build_source_summary(avance_fuente, include_collector = FALSE)
  collector_sources_df <- if (isTRUE(summary_only)) {
    build_source_summary(data.frame(), include_collector = TRUE)
  } else {
    build_source_summary(avance_recopilador, include_collector = TRUE)
  }

  controls_df <- controles
  if (!nrow(controls_df)) controls_df <- data.frame(
    Actor = character(), Variable = character(), Valor = character(), Universo = integer(), Efectivas = integer(),
    Parciales = integer(), `Rechazos plataforma` = integer(), `Sin respuesta plataforma` = integer(),
    `% base` = numeric(), `% efectivas` = numeric(), `Diferencia pp` = numeric(), check.names = FALSE
  )

  first_last <- function(actor, field) {
    dates <- actor_daily$Fecha[actor_daily$Actor == actor & actor_daily$Efectivas > 0L]
    if (!length(dates)) return("")
    if (identical(field, "first")) dates[[1]] else dates[[length(dates)]]
  }
  actor_df$`Primer día` <- vapply(actor_df$Actor, first_last, character(1), field = "first")
  actor_df$`Última efectiva` <- vapply(actor_df$Actor, first_last, character(1), field = "last")
  actor_df <- actor_df[order(-actor_df$Efectivas, -actor_df$`Avance universo`, actor_df$Actor), , drop = FALSE]

  total_universe <- sum(actor_df$Universo, na.rm = TRUE)
  total_effective <- sum(actor_df$Efectivas, na.rm = TRUE)
  total_partial <- sum(actor_df$Parciales, na.rm = TRUE)
  total_refusal <- sum(actor_df$`Rechazos plataforma`, na.rm = TRUE)
  total_pending <- sum(actor_df$`Sin respuesta`, na.rm = TRUE)
  summary <- data.frame(
    Indicador = c("Actores reportados", "Efectivas", "Parciales", "Rechazos plataforma", "Sin respuesta", "Universo", "Avance efectivo", "Fuentes reportadas"),
    Valor = c(
      as.character(nrow(actor_df)),
      as.character(total_effective),
      as.character(total_partial),
      as.character(total_refusal),
      as.character(total_pending),
      as.character(total_universe),
      if (total_universe > 0L) sprintf("%.1f%%", 100 * total_effective / total_universe) else "S/D",
      as.character(nrow(sources_df))
    ),
    check.names = FALSE,
    stringsAsFactors = FALSE
  )

  list(
    schema = "monitoreo_client_report_v1",
    generated_at = generated_at,
    title = "Reporte de avance para cliente",
    summary = .monitoreo_report_records(summary),
    actors = .monitoreo_report_records(actor_df),
    daily_general = .monitoreo_report_records(daily_general),
    daily_actor = .monitoreo_report_records(actor_daily),
    sources = .monitoreo_report_records(sources_df),
    collector_sources = .monitoreo_report_records(collector_sources_df),
    controls = .monitoreo_report_records(controls_df),
    client_report = cfg$client_report %||% .monitoreo_client_report_config(list()),
    has_targets = any(!is.na(actor_df$Meta)),
    sheets = list()
  )
}

.monitoreo_client_report_sheet_frames <- function(model, include_targets = FALSE) {
  records_df <- function(records) {
    records <- records %||% list()
    if (!length(records)) return(data.frame())
    rows <- lapply(records, function(row) as.data.frame(as.list(row), check.names = FALSE, stringsAsFactors = FALSE))
    out <- tryCatch(do.call(rbind, rows), error = function(e) data.frame())
    rownames(out) <- NULL
    out
  }
  actors <- records_df(model$actors)
  daily_general <- records_df(model$daily_general)
  daily_actor <- records_df(model$daily_actor)
  sources <- records_df(model$sources)
  controls <- records_df(model$controls)
  if (!nrow(actors)) {
    actors <- data.frame(Actor = character(), Universo = integer(), Efectivas = integer(), `Avance universo` = numeric(), check.names = FALSE)
  }
  actor_cols <- c("Actor", "Universo", "Efectivas", "Parciales", "Rechazos plataforma", "Sin respuesta plataforma", "Sin respuesta", "Referencia operativa", "Referencia etiqueta", "Origen avance", "Avance universo", "Primer día", "Última efectiva")
  if (isTRUE(include_targets)) actor_cols <- c(actor_cols, "Meta", "Brecha meta", "Avance meta")
  actor_cols <- intersect(actor_cols, names(actors))
  reporte <- actors[, actor_cols, drop = FALSE]

  avance_actor <- daily_actor
  if (nrow(avance_actor)) {
    avance_actor <- avance_actor[, intersect(c("Actor", "Fecha", "Efectivas", "Parciales", "Rechazos plataforma", "Total respuestas", "Acumulado"), names(avance_actor)), drop = FALSE]
  }

  fechas <- if (nrow(avance_actor)) sort(unique(as.character(avance_actor$Fecha))) else character(0)
  matriz <- data.frame(Fecha = fechas, check.names = FALSE, stringsAsFactors = FALSE)
  if (length(fechas)) {
    for (actor in as.character(actors$Actor %||% character(0))) {
      matriz[[actor]] <- vapply(fechas, function(day) {
        sum(as.integer(avance_actor$Efectivas[avance_actor$Actor == actor & avance_actor$Fecha == day]), na.rm = TRUE)
      }, integer(1))
    }
    actor_cols_m <- setdiff(names(matriz), "Fecha")
    matriz$`Total día` <- rowSums(matriz[, actor_cols_m, drop = FALSE], na.rm = TRUE)
    matriz$Parciales <- vapply(fechas, function(day) {
      sum(as.integer(avance_actor$Parciales[avance_actor$Fecha == day]), na.rm = TRUE)
    }, integer(1))
    matriz$`Rechazos plataforma` <- vapply(fechas, function(day) {
      sum(as.integer(avance_actor$`Rechazos plataforma`[avance_actor$Fecha == day]), na.rm = TRUE)
    }, integer(1))
    matriz$Acumulado <- cumsum(matriz$`Total día`)
  } else {
    matriz$`Total día` <- integer(0)
    matriz$Parciales <- integer(0)
    matriz$`Rechazos plataforma` <- integer(0)
    matriz$Acumulado <- integer(0)
  }

  fuentes <- if (nrow(sources)) {
    sources[, intersect(c("Actor", "Canal", "Fuente", "Efectivas", "Parciales", "Rechazos plataforma", "Total respuestas", "Primer día", "Última respuesta", "Última efectiva"), names(sources)), drop = FALSE]
  } else {
    data.frame(Actor = character(), Canal = character(), Fuente = character(), Efectivas = integer(), check.names = FALSE)
  }

  variables_control <- if (nrow(controls)) {
    controls[, intersect(c("Actor", "Variable", "Valor", "Universo", "Efectivas", "Parciales", "Rechazos plataforma", "Sin respuesta plataforma", "% base", "% efectivas", "Diferencia pp"), names(controls)), drop = FALSE]
  } else {
    data.frame(Actor = character(), Variable = character(), Valor = character(), Universo = integer(), Efectivas = integer(), check.names = FALSE)
  }

  list(
    reporte = reporte,
    avance_actor = avance_actor,
    efectivas_fecha = matriz,
    fuentes_actor = fuentes,
    variables_control = variables_control,
    daily_general = daily_general
  )
}

monitoreo_acreditacion_client_report_sheets <- function(model, include_targets = FALSE) {
  frames <- .monitoreo_client_report_sheet_frames(model, include_targets)
  list(
    .monitoreo_report_sheet("cliente_reporte", "Reporte", "Resumen ejecutivo de avance efectivo por actor.", list(
      .monitoreo_report_block("resumen_actor", "Resumen por actor", frames$reporte)
    ), scope = "cliente"),
    .monitoreo_report_sheet("cliente_avance_actor", "Avance por actor", "Efectivas diarias y acumuladas por actor.", list(
      .monitoreo_report_block("avance_actor_dia", "Avance diario por actor", frames$avance_actor)
    ), scope = "cliente"),
    .monitoreo_report_sheet("cliente_efectivas_fecha", "Efectivas por fecha", "Matriz de efectivas por fecha y actor.", list(
      .monitoreo_report_block("efectivas_fecha", "Efectivas por fecha", frames$efectivas_fecha)
    ), scope = "cliente"),
    .monitoreo_report_sheet("cliente_fuentes_actor", "Fuentes por actor", "Fuentes exactas de plataforma incluidas en el reporte.", list(
      .monitoreo_report_block("fuentes_actor", "Fuentes por actor", frames$fuentes_actor)
    ), scope = "cliente"),
    .monitoreo_report_sheet("cliente_variables_control", "Variables de control", "Distribución del avance frente al universo para variables relevantes por actor.", list(
      .monitoreo_report_block("variables_control", "Distribución por variable de control", frames$variables_control)
    ), scope = "cliente")
  )
}

monitoreo_acreditacion_client_report_model <- function(data, config = list(), detail = c("full", "advance_summary"), case_rollup = NULL) {
  .monitoreo_client_report_model(data, config, detail = match.arg(detail), case_rollup = case_rollup)
}

.monitoreo_pdf_add_internal_links <- function(pdf_path, links) {
  links <- links %||% list()
  if (!length(links) || !file.exists(pdf_path)) return(invisible(FALSE))
  if (!requireNamespace("jsonlite", quietly = TRUE)) return(invisible(FALSE))

  python_candidates <- c(
    Sys.getenv("PROSECNUR_PDF_PYTHON", ""),
    file.path(Sys.getenv("HOME", ""), ".cache", "codex-runtimes", "codex-primary-runtime", "dependencies", "python", "bin", "python3"),
    unname(Sys.which("python3"))
  )
  python_candidates <- python_candidates[nzchar(python_candidates) & file.exists(python_candidates)]
  python_candidates <- python_candidates[file.access(python_candidates, 1) == 0]
  if (!length(python_candidates)) return(invisible(FALSE))

  script <- c(
    "import json, os, sys",
    "try:",
    "    from pypdf import PdfReader, PdfWriter",
    "except Exception:",
    "    sys.exit(7)",
    "pdf_path, links_path = sys.argv[1], sys.argv[2]",
    "with open(links_path, 'r', encoding='utf-8') as handle:",
    "    links = json.load(handle)",
    "reader = PdfReader(pdf_path)",
    "writer = PdfWriter()",
    "for page in reader.pages:",
    "    writer.add_page(page)",
    "page_count = len(writer.pages)",
    "for link in links:",
    "    try:",
    "        source = int(link.get('source_page_index', -1))",
    "        target = int(link.get('target_page_index', -1))",
    "        if source < 0 or source >= page_count or target < 0 or target >= page_count:",
    "            continue",
    "        page = writer.pages[source]",
    "        width = float(page.mediabox.width)",
    "        height = float(page.mediabox.height)",
    "        x0 = max(0.0, min(1.0, float(link.get('x0', 0))))",
    "        y0 = max(0.0, min(1.0, float(link.get('y0', 0))))",
    "        x1 = max(0.0, min(1.0, float(link.get('x1', 0))))",
    "        y1 = max(0.0, min(1.0, float(link.get('y1', 0))))",
    "        if x1 <= x0 or y1 <= y0:",
    "            continue",
    "        rect = [x0 * width, y0 * height, x1 * width, y1 * height]",
    "        annotation = {",
    "            '/Type': '/Annot',",
    "            '/Subtype': '/Link',",
    "            '/Rect': rect,",
    "            '/Border': [0, 0, 0],",
    "            '/Dest': {'target_page_index': target, 'fit': '/Fit', 'fit_args': []},",
    "        }",
    "        writer.add_annotation(source, annotation)",
    "    except Exception:",
    "        continue",
    "tmp_path = pdf_path + '.links.tmp'",
    "with open(tmp_path, 'wb') as handle:",
    "    writer.write(handle)",
    "os.replace(tmp_path, pdf_path)"
  )

  links_path <- tempfile(fileext = ".json")
  script_path <- tempfile(fileext = ".py")
  on.exit(unlink(c(links_path, script_path), force = TRUE), add = TRUE)
  jsonlite::write_json(links, links_path, auto_unbox = TRUE, null = "null")
  writeLines(script, script_path, useBytes = TRUE)

  result <- tryCatch(
    system2(python_candidates[[1]], c(script_path, normalizePath(pdf_path, mustWork = TRUE), links_path), stdout = TRUE, stderr = TRUE),
    error = function(e) structure(character(), status = 1L)
  )
  status <- attr(result, "status")
  invisible(is.null(status) || identical(as.integer(status), 0L))
}

monitoreo_acreditacion_client_report_pdf <- function(model, output_file, include_targets = FALSE, title = NULL) {
  records_df <- function(records) {
    records <- records %||% list()
    if (!length(records)) return(data.frame())
    rows <- lapply(records, function(row) as.data.frame(as.list(row), check.names = FALSE, stringsAsFactors = FALSE))
    out <- tryCatch(do.call(rbind, rows), error = function(e) data.frame())
    rownames(out) <- NULL
    out
  }
  num <- function(x) {
    out <- suppressWarnings(as.numeric(x))
    out[!is.finite(out)] <- 0
    out
  }
  one_num <- function(x, default = 0) {
    out <- num(x)
    if (!length(out)) return(default)
    out[[1]]
  }
  pct_label <- function(x) {
    x <- suppressWarnings(as.numeric(x))
    if (!is.finite(x)) return("S/D")
    sprintf("%.1f%%", if (abs(x) <= 1) x * 100 else x)
  }
  fmt <- function(x) formatC(as.integer(round(one_num(x))), big.mark = ",", format = "d")
  fmt_sum <- function(x) formatC(as.integer(round(sum(num(x), na.rm = TRUE))), big.mark = ",", format = "d")
  pct_value <- function(num_value, den_value) {
    .monitoreo_client_report_pct(one_num(num_value), one_num(den_value))
  }
  state_pct <- function(value, total) {
    value <- one_num(value, NA_real_)
    total <- one_num(total, NA_real_)
    if (!is.finite(value) || !is.finite(total) || total <= 0) return(NA_real_)
    value / total
  }
  state_value_label <- function(value, total) {
    fmt(value)
  }
  ellipsize <- function(x, max_chars = 64) {
    x <- as.character(x %||% "")
    x[is.na(x)] <- ""
    vapply(x, function(item) {
      if (nchar(item, type = "width") <= max_chars) return(item)
      paste0(substr(item, 1L, max(1L, max_chars - 3L)), "...")
    }, character(1))
  }
  actors <- records_df(model$actors)
  daily_general <- records_df(model$daily_general)
  daily_actor <- records_df(model$daily_actor)
  sources <- records_df(model$sources)
  channel_aliases <- model$client_report$channel_labels %||%
    model$presentation$channel_labels %||%
    model$channel_labels %||%
    list()
  channel_alias <- function(value) {
    raw <- as.character(value %||% "")
    if (!nzchar(raw) || is.na(raw)) raw <- "Sin canal"
    key <- .monitoreo_text_key(raw)
    label <- trimws(.monitoreo_scalar(channel_aliases[[key]], ""))
    if (nzchar(label)) return(label)
    if (grepl("whatsapp|whartsapp|wsp|personalizado", key, perl = TRUE)) return("Enlace personalizado")
    raw
  }
  total_effective <- sum(num(actors$Efectivas), na.rm = TRUE)
  total_partial <- sum(num(actors$Parciales), na.rm = TRUE)
  total_refusal <- sum(.monitoreo_publication_platform_refusal_values(actors), na.rm = TRUE)
  total_pending <- sum(num(actors$`Sin respuesta`), na.rm = TRUE)
  total_universe <- sum(num(actors$Universo), na.rm = TRUE)
  if (total_pending <= 0 && total_universe > 0) {
    total_pending <- max(0, total_universe - total_effective - total_partial - total_refusal)
  }
  report_title <- title %||% "Reporte de avance"
  generated_at <- as.character(model$generated_at %||% "")
  pretty_stamp <- function(x) {
    parsed <- .monitoreo_parse_time_vec(x)
    if (length(parsed) && !is.na(parsed[[1]])) {
      local_tz <- Sys.getenv("TZ", "")
      if (!nzchar(local_tz)) local_tz <- "America/Lima"
      month_labels <- c("Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic")
      local_day <- as.POSIXlt(parsed[[1]], tz = local_tz)
      return(sprintf("%02d %s %d", local_day$mday, month_labels[[local_day$mon + 1L]], local_day$year + 1900L))
    }
    x
  }
  pretty_day <- function(x, stacked = TRUE) {
    parsed <- suppressWarnings(as.Date(as.character(x)))
    month_labels <- c("ene.", "feb.", "mar.", "abr.", "may.", "jun.", "jul.", "ago.", "set.", "oct.", "nov.", "dic.")
    out <- ifelse(
      is.na(parsed),
      as.character(x),
      paste(month_labels[as.integer(format(parsed, "%m"))], as.integer(format(parsed, "%d")))
    )
    if (isTRUE(stacked)) out <- gsub(" ", "\n", out, fixed = TRUE)
    out
  }
  generated_label <- pretty_stamp(generated_at)
  pulso_logo_path <- function() {
    candidates <- c(
      system.file("hojas_ruta", "assets", "logo_pulso.png", package = "prosecnurapp"),
      file.path(getwd(), "api", "inst", "hojas_ruta", "assets", "logo_pulso.png"),
      file.path(getwd(), "api", "inst", "manuales_qmd", "files_manuales", "img", "logo_pulso.png"),
      file.path(getwd(), "inst", "hojas_ruta", "assets", "logo_pulso.png")
    )
    candidates <- candidates[nzchar(candidates) & file.exists(candidates)]
    if (length(candidates)) candidates[[1]] else ""
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  grDevices::pdf(output_file, paper = "a4", width = 8.27, height = 11.69, onefile = TRUE)
  pdf_device <- grDevices::dev.cur()
  pdf_closed <- FALSE
  close_pdf <- function() {
    if (isTRUE(pdf_closed)) return(invisible(NULL))
    tryCatch(
      {
        if (identical(grDevices::dev.cur(), pdf_device)) {
          grDevices::dev.off()
        } else {
          grDevices::dev.off(pdf_device)
        }
      },
      error = function(e) NULL
    )
    pdf_closed <<- TRUE
    invisible(NULL)
  }
  on.exit(close_pdf(), add = TRUE)

  ink <- "#152033"
  muted <- "#667085"
  faint <- "#98a2b3"
  panel <- "#ffffff"
  canvas <- "#f6f8fb"
  border <- "#d8e1ee"
  grid_line <- "#e9eef6"
  accent <- "#be123c"
  effective <- "#168a55"
  partial_col <- "#b7791f"
  refusal_col <- "#be123c"
  pending_col <- "#98a2b3"
  navy <- "#06346f"

  page_no <- 0L
  pdf_links <- list()
  add_pdf_link <- function(target_page_index, x, y, w, h, label = "") {
    if (!is.finite(target_page_index) || target_page_index < 0) return(invisible(NULL))
    pdf_links[[length(pdf_links) + 1L]] <<- list(
      source_page_index = as.integer(max(0L, page_no - 1L)),
      target_page_index = as.integer(target_page_index),
      x0 = as.numeric(x),
      y0 = as.numeric(y),
      x1 = as.numeric(x + w),
      y1 = as.numeric(y + h),
      label = as.character(label %||% "")
    )
    invisible(NULL)
  }
  rr <- function(x, y, w, h, fill = panel, col = border, lwd = 1, r = 0.016) {
    grid::grid.roundrect(
      x = grid::unit(x + w / 2, "npc"),
      y = grid::unit(y + h / 2, "npc"),
      width = grid::unit(w, "npc"),
      height = grid::unit(h, "npc"),
      r = grid::unit(r, "snpc"),
      gp = grid::gpar(fill = fill, col = col, lwd = lwd)
    )
  }
  txt <- function(label, x, y, size = 9, col = ink, face = "plain", just = c("left", "center"),
                  rot = 0, lineheight = 1.05) {
    label <- as.character(label %||% "")
    grid::grid.text(
      label,
      x = grid::unit(x, "npc"),
      y = grid::unit(y, "npc"),
      just = just,
      rot = rot,
      gp = grid::gpar(fontsize = size, col = col, fontface = face, lineheight = lineheight)
    )
  }
  line <- function(x0, y0, x1, y1, col = border, lwd = 1, lty = 1) {
    grid::grid.segments(
      x0 = grid::unit(x0, "npc"),
      y0 = grid::unit(y0, "npc"),
      x1 = grid::unit(x1, "npc"),
      y1 = grid::unit(y1, "npc"),
      gp = grid::gpar(col = col, lwd = lwd, lty = lty)
    )
  }
  rect <- function(x, y, w, h, fill, col = NA, lwd = 1) {
    grid::grid.rect(
      x = grid::unit(x + w / 2, "npc"),
      y = grid::unit(y + h / 2, "npc"),
      width = grid::unit(w, "npc"),
      height = grid::unit(h, "npc"),
      gp = grid::gpar(fill = fill, col = col, lwd = lwd)
    )
  }
  draw_chip <- function(x, y, label, fill = "#ffffff", col = border, text_col = ink, w = NULL) {
    label <- as.character(label %||% "")
    width <- w %||% max(0.072, min(0.22, 0.022 + nchar(label, type = "width") * 0.006))
    rr(x, y - 0.015, width, 0.03, fill = fill, col = col, lwd = 0.8, r = 0.014)
    txt(label, x + width / 2, y, size = 6.6, col = text_col, face = "bold", just = c("center", "center"))
    invisible(width)
  }
  draw_pulso_logo <- function(x, y, height = 0.036) {
    logo_aspect <- 1078 / 423
    logo_width <- height * logo_aspect * (11.69 / 8.27)
    path <- pulso_logo_path()
    if (nzchar(path) && requireNamespace("png", quietly = TRUE)) {
      img <- tryCatch(png::readPNG(path), error = function(e) NULL)
      if (!is.null(img)) {
        grid::grid.raster(
          img,
          x = grid::unit(x + logo_width / 2, "npc"),
          y = grid::unit(y, "npc"),
          width = grid::unit(logo_width, "npc"),
          height = grid::unit(height, "npc"),
          interpolate = TRUE
        )
        return(invisible(logo_width))
      }
    }
    txt("PULSO", x, y + 0.006, size = 10.8, col = navy, face = "bold", just = c("left", "center"))
    txt("PUCP", x, y - 0.013, size = 6.2, col = muted, face = "bold", just = c("left", "center"))
    invisible(0.085)
  }
  draw_page <- function(section = "") {
    page_no <<- page_no + 1L
    grid::grid.newpage()
    rect(0, 0, 1, 1, canvas, col = NA)
    rect(0, 0.925, 1, 0.075, "#ffffff", col = NA)
    line(0.045, 0.925, 0.955, 0.925, col = border, lwd = 0.8)
    logo_w <- draw_pulso_logo(0.055, 0.960, height = 0.032)
    title_x <- 0.055 + logo_w + 0.018
    txt(ellipsize(report_title, 64), title_x, 0.958, size = 12.2, col = ink, face = "bold")
    txt(generated_label, 0.945, 0.958, size = 7.2, col = muted, face = "bold", just = c("right", "center"))
    txt("Avance", 0.055, 0.025, size = 6.2, col = faint, face = "bold")
    txt(paste("Página", page_no), 0.945, 0.025, size = 6.2, col = faint, just = c("right", "center"))
  }
  metric_box <- function(x, y, w, h, label, value, hint = "", tone = "neutral") {
    tones <- list(
      effective = c("#f0fdf4", "#91d8ad", effective),
      progress = c("#fff7ed", "#f0d2a4", "#9a5b10"),
      partial = c("#fff8ed", "#ead7b6", partial_col),
      refusal = c("#fff1f4", "#efb8c5", refusal_col),
      pending = c("#f8fbff", "#d9e3f0", pending_col),
      base = c("#f8fbff", "#d9e3f0", navy),
      neutral = c("#ffffff", border, ink)
    )
    pal <- tones[[tone]] %||% tones$neutral
    rr(x, y, w, h, fill = pal[[1]], col = pal[[2]], lwd = 1.1, r = 0.016)
    txt(label, x + 0.018, y + h - 0.025, size = 7.0, col = muted, face = "bold", just = c("left", "top"))
    value_chars <- nchar(as.character(value), type = "width")
    value_size <- if (value_chars > 15) 14.8 else if (value_chars > 12) 16.2 else 18.0
    txt(value, x + 0.018, y + h * 0.40, size = value_size, col = ink, face = "bold")
    if (nzchar(hint)) txt(hint, x + 0.018, y + 0.023, size = 6.2, col = muted, face = "bold", just = c("left", "bottom"))
    rect(x, y, 0.0045, h, pal[[3]], col = NA)
  }
  actor_metric_tile <- function(x, y, w, h, label, value, tone = "neutral") {
    tones <- list(
      effective = c("#f0fdf4", "#b8e6ca", effective),
      progress = c("#fff8ed", "#ead7b6", "#9a5b10"),
      partial = c("#fff8ed", "#ead7b6", partial_col),
      refusal = c("#fff1f4", "#efb8c5", refusal_col),
      pending = c("#f8fbff", "#d9e3f0", pending_col),
      base = c("#f8fbff", "#d9e3f0", navy),
      neutral = c("#ffffff", "#e4ebf4", ink)
    )
    pal <- tones[[tone]] %||% tones$neutral
    rr(x, y, w, h, fill = pal[[1]], col = pal[[2]], lwd = 0.85, r = 0.012)
    rect(x, y, 0.0038, h, pal[[3]], col = NA)
    label_size <- if (h >= 0.074) 5.4 else 4.9
    txt(label, x + 0.012, y + h - 0.012, size = label_size, col = muted, face = "bold", just = c("left", "top"))
    value_chars <- nchar(as.character(value), type = "width")
    base_value_size <- if (h >= 0.074) 12.0 else 10.0
    value_size <- if (value_chars > 14) base_value_size - 1.8 else if (value_chars > 11) base_value_size - 1.0 else base_value_size
    txt(value, x + 0.012, y + 0.012, size = value_size, col = ink, face = "bold", just = c("left", "bottom"))
  }
  state_num <- function(x, default = 0) {
    out <- suppressWarnings(as.numeric(x))
    if (!length(out) || !is.finite(out[[1]])) return(default)
    out[[1]]
  }
  actor_state <- function(row) {
    universo <- state_num(row$Universo, 0)
    efectivas <- state_num(row$Efectivas, 0)
    parciales <- state_num(row$Parciales, 0)
    rechazo <- state_num(.monitoreo_publication_platform_refusal_value(row, 0), 0)
    sin_respuesta <- state_num(row$`Sin respuesta`, NA_real_)
    if (!is.finite(sin_respuesta)) sin_respuesta <- max(0, universo - efectivas - parciales - rechazo)
    referencia <- state_num(row$`Referencia operativa` %||% row$Meta, NA_real_)
    raw_referencia_label <- row$`Referencia etiqueta`
    referencia_label <- if (length(raw_referencia_label)) as.character(raw_referencia_label[[1]]) else ""
    if (is.na(referencia_label) || !nzchar(trimws(referencia_label))) referencia_label <- "Mínimo a alcanzar"
    list(
      universo = max(0, universo),
      efectivas = max(0, efectivas),
      parciales = max(0, parciales),
      rechazo = max(0, rechazo),
      sin_respuesta = max(0, sin_respuesta),
      referencia = referencia,
      referencia_label = referencia_label
    )
  }
  draw_state_composition <- function(x, y, w, h, state, compact = FALSE) {
    total <- state$universo
    visible_total <- sum(c(state$efectivas, state$parciales, state$rechazo, state$sin_respuesta), na.rm = TRUE)
    if (!is.finite(total) || total <= 0) total <- visible_total
    rr(x, y, w, h, fill = "#edf2f8", col = NA, lwd = 0, r = h / 2)
    segments <- list(
      list(value = state$efectivas, color = effective, label = "Efectivas", text = "#ffffff"),
      list(value = state$parciales, color = partial_col, label = "Parciales", text = "#ffffff"),
      list(value = state$rechazo, color = refusal_col, label = "Rechazo", text = "#ffffff"),
      list(value = state$sin_respuesta, color = pending_col, label = "Sin respuesta", text = ink)
    )
    cursor <- x
    if (is.finite(total) && total > 0) {
      for (seg in segments) {
        value <- seg$value
        if (!is.finite(value) || value <= 0) next
        seg_w <- min(x + w - cursor, w * value / total)
        if (seg_w <= 0) next
        rect(cursor, y, seg_w, h, seg$color, col = NA)
        pct <- value / total
        if (!isTRUE(compact) && is.finite(pct) && pct >= 0.03) {
          label_text <- if (pct >= 0.08 && seg_w >= 0.095) paste(seg$label, pct_label(pct)) else pct_label(pct)
          txt(label_text, cursor + seg_w / 2, y + h / 2, size = if (seg_w < 0.055) 4.4 else 5.2, col = seg$text, face = "bold", just = c("center", "center"))
        }
        cursor <- cursor + seg_w
      }
    }
    if (!isTRUE(compact)) {
      txt(paste("Base reportada:", fmt(total)), x, y - 0.014, size = 5.8, col = muted, face = "bold", just = c("left", "top"))
      if (is.finite(state$referencia)) {
        txt(paste0(state$referencia_label, ": ", fmt(state$referencia)), x + w, y - 0.014, size = 5.8, col = muted, face = "bold", just = c("right", "top"))
      }
    }
  }
  draw_actor_overview_card <- function(row, x, y, w, h, target_page_index = NULL) {
    actor <- as.character(row$Actor[[1]] %||% "")
    state <- actor_state(row)
    pct <- if (state$universo > 0) min(1, state$efectivas / state$universo) else 0
    rr(x, y, w, h, fill = "#ffffff", col = border, lwd = 1.1, r = 0.018)
    rect(x, y + h - 0.006, w, 0.006, effective, col = NA)
    txt(ellipsize(actor, 32), x + 0.018, y + h - 0.034, size = 11.0, col = ink, face = "bold", just = c("left", "top"))
    draw_chip(x + w - 0.118, y + h - 0.034, "Ver detalle", fill = "#f8fbff", col = "#d9e3f0", text_col = navy, w = 0.100)
    txt(paste(fmt(state$efectivas), "efectivas de", fmt(state$universo)), x + 0.018, y + h - 0.067, size = 7.0, col = muted, face = "bold", just = c("left", "center"))
    txt(pct_label(pct), x + w - 0.020, y + h - 0.067, size = 9.0, col = ink, face = "bold", just = c("right", "center"))
    draw_state_composition(x + 0.018, y + h - 0.092, w - 0.036, 0.015, state, compact = TRUE)
    tile_gap <- 0.010
    tile_w <- (w - 0.046 - tile_gap) / 2
    tile_gap_y <- min(0.014, max(0.006, h * 0.035))
    tile_top_limit <- y + h - 0.110
    tile_bottom_limit <- y + 0.020
    tile_available <- max(0.112, tile_top_limit - tile_bottom_limit)
    tile_h <- min(0.083, max(0.052, (tile_available - tile_gap_y) / 2))
    tile_grid_h <- tile_h * 2 + tile_gap_y
    tile_y_bottom <- tile_bottom_limit + max(0, (tile_available - tile_grid_h) / 2)
    tile_y_top <- tile_y_bottom + tile_h + tile_gap_y
    actor_metric_tile(x + 0.018, tile_y_top, tile_w, tile_h, "Efectivas", state_value_label(state$efectivas, state$universo), "effective")
    actor_metric_tile(x + 0.028 + tile_w, tile_y_top, tile_w, tile_h, "Parciales", state_value_label(state$parciales, state$universo), "partial")
    actor_metric_tile(x + 0.018, tile_y_bottom, tile_w, tile_h, "Rechazo", state_value_label(state$rechazo, state$universo), "refusal")
    actor_metric_tile(x + 0.028 + tile_w, tile_y_bottom, tile_w, tile_h, "Sin respuesta", state_value_label(state$sin_respuesta, state$universo), "pending")
    if (!is.null(target_page_index)) add_pdf_link(target_page_index, x, y, w, h, actor)
  }
  actor_overview_layout <- function(n) {
    n <- min(max(as.integer(n), 1L), 4L)
    area_x <- 0.055
    area_w <- 0.890
    top_y <- 0.795
    bottom_y <- 0.115
    area_h <- top_y - bottom_y
    gap_x <- 0.026
    gap_y <- 0.028
    half_w <- (area_w - gap_x) / 2
    if (n == 1L) {
      h <- min(0.500, area_h)
      return(data.frame(x = area_x, y = top_y - h, w = area_w, h = h))
    }
    if (n == 2L) {
      h <- (area_h - gap_y) / 2
      return(data.frame(
        x = c(area_x, area_x),
        y = c(top_y - h, bottom_y),
        w = c(area_w, area_w),
        h = c(h, h)
      ))
    }
    if (n == 3L) {
      top_h <- 0.290
      bottom_h <- area_h - top_h - gap_y
      return(data.frame(
        x = c(area_x, area_x, area_x + half_w + gap_x),
        y = c(top_y - top_h, bottom_y, bottom_y),
        w = c(area_w, half_w, half_w),
        h = c(top_h, bottom_h, bottom_h)
      ))
    }
    h <- (area_h - gap_y) / 2
    data.frame(
      x = c(area_x, area_x + half_w + gap_x, area_x, area_x + half_w + gap_x),
      y = c(top_y - h, top_y - h, bottom_y, bottom_y),
      w = rep(half_w, 4),
      h = rep(h, 4)
    )
  }
  draw_actor_overview_page <- function(df) {
    draw_page()
    txt("Avance por actor", 0.055, 0.855, size = 18, col = ink, face = "bold")
    txt("Selecciona un grupo para ver su detalle diario y sus canales.", 0.055, 0.826, size = 7.6, col = muted, face = "bold")
    if (!nrow(df)) {
      rr(0.055, 0.520, 0.890, 0.160, fill = "#ffffff", col = border, lwd = 1.1)
      txt("Sin actores reportados.", 0.500, 0.600, size = 8.5, col = muted, just = c("center", "center"))
      return(invisible(NULL))
    }
    max_cards <- min(nrow(df), 4L)
    layout <- actor_overview_layout(max_cards)
    for (i in seq_len(max_cards)) {
      draw_actor_overview_card(
        df[i, , drop = FALSE],
        layout$x[[i]],
        layout$y[[i]],
        layout$w[[i]],
        layout$h[[i]],
        target_page_index = i
      )
    }
    if (nrow(df) > max_cards) {
      txt(paste("+", nrow(df) - max_cards, "grupos adicionales en el detalle"), 0.055, 0.090, size = 6.5, col = muted, face = "bold")
    }
  }
  draw_effective_trend <- function(df, x0, y0, w, h, title = "Avance diario", subtitle = "") {
    if (!nrow(df)) {
      rr(x0, y0, w, h, fill = "#ffffff", col = border, lwd = 1.1)
      txt(title, x0 + 0.02, y0 + h - 0.03, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
      txt("Sin datos para mostrar.", x0 + w / 2, y0 + h / 2, size = 8, col = muted, just = c("center", "center"))
      return(invisible(NULL))
    }
    if ("Fecha" %in% names(df)) {
      ord <- order(suppressWarnings(as.Date(as.character(df$Fecha))), as.character(df$Fecha))
      df <- df[ord, , drop = FALSE]
    }
    daily_col <- intersect(c("Nuevas efectivas", "Efectivas", "Nuevas UMP efectivas", "Total respuestas"), names(df))
    daily_col <- if (length(daily_col)) daily_col[[1]] else ""
    values <- if (nzchar(daily_col)) num(df[[daily_col]]) else rep(0, nrow(df))
    accum_col <- intersect(c("Acumulado", "Efectivas acumuladas", "UMP efectivas acumuladas"), names(df))
    accum <- if (length(accum_col)) num(df[[accum_col[[1]]]]) else cumsum(values)
    n <- length(values)
    if (!n || max(values, accum, na.rm = TRUE) <= 0) {
      rr(x0, y0, w, h, fill = "#ffffff", col = border, lwd = 1.1)
      txt(title, x0 + 0.02, y0 + h - 0.03, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
      txt("Sin datos para mostrar.", x0 + w / 2, y0 + h / 2, size = 8, col = muted, just = c("center", "center"))
      return(invisible(NULL))
    }
    ymax_bar <- max(values, 1)
    ymax_line <- max(accum, 1)
    bar_axis_ticks <- if (ymax_bar <= 6) {
      seq(0, ceiling(ymax_bar), by = 1)
    } else {
      pretty(c(0, ymax_bar), n = 4)
    }
    bar_axis_ticks <- sort(unique(bar_axis_ticks[bar_axis_ticks >= 0]))
    if (!length(bar_axis_ticks)) bar_axis_ticks <- c(0, ymax_bar)
    if (ymax_bar > 6) {
      rounded_ticks <- sort(unique(as.numeric(round(bar_axis_ticks))))
      rounded_ticks <- rounded_ticks[rounded_ticks >= 0]
      if (length(rounded_ticks) >= 2L) bar_axis_ticks <- rounded_ticks
    }
    bar_axis_max <- max(max(bar_axis_ticks, na.rm = TRUE), ymax_bar, 1)
    line_axis_ticks <- pretty(c(0, ymax_line), n = 4)
    line_axis_ticks <- line_axis_ticks[line_axis_ticks >= 0]
    if (!length(line_axis_ticks)) line_axis_ticks <- c(0, ymax_line)
    line_axis_max <- max(max(line_axis_ticks, na.rm = TRUE), ymax_line, 1)
    rr(x0, y0, w, h, fill = "#ffffff", col = border, lwd = 1.1)
    chart_x0 <- x0 + 0.055
    chart_y0 <- y0 + 0.075
    chart_w <- w - 0.105
    chart_h <- h - 0.122
    txt(title, chart_x0, chart_y0 + chart_h + 0.032, size = 9.2, col = ink, face = "bold", just = c("left", "bottom"))
    if (nzchar(subtitle)) txt(subtitle, chart_x0, chart_y0 + chart_h + 0.018, size = 6.4, col = muted, face = "bold", just = c("left", "bottom"))
    bar_ticks <- sort(unique(bar_axis_ticks))
    bar_ticks <- bar_ticks[bar_ticks >= 0 & bar_ticks <= bar_axis_max]
    if (length(bar_ticks) > 6L) {
      bar_ticks <- bar_ticks[unique(round(seq(1, length(bar_ticks), length.out = 6L)))]
    }
    bar_ticks <- sort(unique(as.numeric(round(bar_ticks))))
    if (!length(bar_ticks) || length(bar_ticks) < 2L) bar_ticks <- c(0, ceiling(ymax_bar))
    for (tick in bar_ticks) {
      k <- if (bar_axis_max > 0) tick / bar_axis_max else 0
      y <- chart_y0 + chart_h * k
      line(chart_x0, y, chart_x0 + chart_w, y, col = grid_line, lwd = 0.55)
      txt(fmt(tick), chart_x0 - 0.014, y, size = 5.8, col = faint, just = c("right", "center"))
    }
    txt(fmt(line_axis_max), chart_x0 + chart_w + 0.014, chart_y0 + chart_h, size = 5.8, col = "#43608b", just = c("left", "center"))
    txt("0", chart_x0 + chart_w + 0.014, chart_y0, size = 5.8, col = "#43608b", just = c("left", "center"))
    bar_w <- min(0.032, chart_w / max(4, n) * 0.60)
    edge_pad <- max(bar_w / 2, 0.010)
    xs <- if (n == 1L) {
      chart_x0 + chart_w / 2
    } else {
      chart_x0 + edge_pad + (chart_w - edge_pad * 2) * (seq_len(n) - 1) / (n - 1)
    }
    bar_heights <- numeric(n)
    min_visible_bar_h <- if (n <= 26L) 0.024 else 0.020
    for (i in seq_len(n)) {
      bh <- chart_h * values[[i]] / bar_axis_max
      draw_h <- if (bh > 0) min(chart_h, max(bh, min_visible_bar_h)) else 0
      bar_heights[[i]] <- draw_h
      if (draw_h > 0) rect(xs[[i]] - bar_w / 2, chart_y0, bar_w, draw_h, effective, col = NA)
    }
    ys <- chart_y0 + chart_h * accum / line_axis_max
    if (n > 1L) {
      grid::grid.lines(
        x = grid::unit(xs, "npc"),
        y = grid::unit(ys, "npc"),
        gp = grid::gpar(col = navy, lwd = 1.65, lineend = "round", linejoin = "round")
      )
    }
    grid::grid.points(
      x = grid::unit(xs, "npc"),
      y = grid::unit(ys, "npc"),
      pch = 21,
      size = grid::unit(2.8, "mm"),
      gp = grid::gpar(col = navy, fill = "#ffffff", lwd = 1)
    )
    label_size <- if (n <= 26L) 5.0 else 4.6
    daily_label_y <- chart_y0 - 0.013
    for (i in seq_len(n)) {
      if (!is.finite(values[[i]]) || values[[i]] <= 0) next
      txt(
        fmt(values[[i]]),
        xs[[i]],
        daily_label_y,
        size = label_size,
        col = effective,
        face = "bold",
        just = c("center", "center")
      )
    }
    label_dates <- if ("Fecha" %in% names(df)) suppressWarnings(as.Date(as.character(df$Fecha))) else rep(as.Date(NA), n)
    label_weekday <- suppressWarnings(as.POSIXlt(label_dates)$wday)
    accum_keep <- unique(c(1L, which(!is.na(label_weekday) & label_weekday == 1L), n))
    accum_keep <- accum_keep[accum_keep >= 1L & accum_keep <= n]
    if (!length(accum_keep)) accum_keep <- n
    accum_label_y <- chart_y0 + chart_h + 0.008
    for (i in accum_keep) {
      if (!is.finite(accum[[i]]) || accum[[i]] <= 0) next
      guide_bottom <- chart_y0 + max(0.002, bar_heights[[i]])
      line(xs[[i]], accum_label_y - 0.004, xs[[i]], guide_bottom + 0.004, col = "#8aa0bd", lwd = 0.65, lty = 3)
      txt(fmt(accum[[i]]), xs[[i]], accum_label_y, size = 5.2, col = navy, face = "bold", just = c("center", "bottom"))
    }
    labels <- pretty_day(as.character(df$Fecha %||% seq_len(n)), stacked = TRUE)
    keep <- if (n <= 28L) seq_len(n) else unique(round(seq(1, n, length.out = 28L)))
    txt(labels[keep], xs[keep], chart_y0 - 0.034, size = if (n <= 20L) 5.7 else 5.1,
        col = muted, just = c("center", "center"), rot = 0, lineheight = 0.86)
    invisible(NULL)
  }

  draw_actor_board <- function(df, x0, y0, w, h, title = "Avance por grupo") {
    rr(x0, y0, w, h, fill = "#ffffff", col = border, lwd = 1.1)
    txt(title, x0 + 0.02, y0 + h - 0.03, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
    if (!nrow(df)) {
      txt("Sin actores reportados.", x0 + w / 2, y0 + h / 2, size = 8, col = muted, just = c("center", "center"))
      return(invisible(NULL))
    }
    rows <- df[seq_len(min(nrow(df), 8L)), , drop = FALSE]
    row_h <- min(0.052, (h - 0.078) / max(1, nrow(rows)))
    label_x <- x0 + 0.02
    bar_x <- x0 + 0.245
    metric_x <- x0 + w - 0.150
    bar_w <- max(0.260, metric_x - bar_x - 0.034)
    y <- y0 + h - 0.084
    for (i in seq_len(nrow(rows))) {
      state <- actor_state(rows[i, , drop = FALSE])
      pct <- if (state$universo > 0) min(1, state$efectivas / state$universo) else 0
      txt(ellipsize(rows$Actor[[i]], 26), label_x, y + 0.014, size = 7.3, col = ink, face = "bold")
      txt(paste(fmt(state$efectivas), "efectivas de", fmt(state$universo)), label_x, y - 0.007, size = 5.8, col = muted, face = "bold")
      draw_state_composition(bar_x, y - 0.006, bar_w, 0.017, state, compact = TRUE)
      txt(pct_label(pct), metric_x, y + 0.012, size = 7.0, col = ink, face = "bold", just = c("left", "center"))
      txt(paste(fmt(state$sin_respuesta), "sin respuesta"), metric_x + 0.072, y + 0.012, size = 5.3, col = muted, face = "bold", just = c("left", "center"))
      line(x0 + 0.02, y - row_h / 2, x0 + w - 0.02, y - row_h / 2, col = grid_line, lwd = 0.55)
      y <- y - row_h
    }
    if (nrow(df) > nrow(rows)) txt(paste("+", nrow(df) - nrow(rows), "actores adicionales"), x0 + 0.02, y0 + 0.025, size = 6.2, col = muted, face = "bold")
  }
  channel_summary <- function(df) {
    df <- .monitoreo_workbook_df(df)
    if (!nrow(df)) return(list(rows = data.frame(), top_label = "", top_value = 0, top_share = NA_real_, last_date = ""))
    df$.__eff <- num(df$Efectivas)
    df <- df[df$.__eff > 0, , drop = FALSE]
    if (!nrow(df)) return(list(rows = data.frame(), top_label = "", top_value = 0, top_share = NA_real_, last_date = ""))
    channel <- vapply(as.character(df$Canal %||% ""), channel_alias, character(1))
    grouped <- stats::aggregate(
      df$.__eff,
      by = list(Canal = channel),
      FUN = sum
    )
    names(grouped)[names(grouped) == "x"] <- "Efectivas"
    grouped <- grouped[order(-grouped$Efectivas, grouped$Canal), , drop = FALSE]
    total <- sum(grouped$Efectivas, na.rm = TRUE)
    date_values <- as.character(df$`Última efectiva` %||% df$`Última respuesta` %||% "")
    date_values <- date_values[nzchar(date_values) & !is.na(date_values)]
    list(
      rows = grouped,
      top_label = as.character(grouped$Canal[[1]] %||% ""),
      top_value = one_num(grouped$Efectivas[[1]]),
      top_share = if (total > 0) grouped$Efectivas[[1]] / total else NA_real_,
      last_date = if (length(date_values)) date_values[[length(date_values)]] else ""
    )
  }
  short_day <- function(x) {
    parsed <- suppressWarnings(as.Date(as.character(x)))
    months <- c("ene.", "feb.", "mar.", "abr.", "may.", "jun.", "jul.", "ago.", "set.", "oct.", "nov.", "dic.")
    if (!length(parsed) || is.na(parsed[[1]])) return(as.character(x %||% ""))
    paste(as.integer(format(parsed[[1]], "%d")), months[[as.integer(format(parsed[[1]], "%m"))]])
  }
  weekly_recent_summary <- function(df) {
    df <- .monitoreo_workbook_df(df)
    empty_last7 <- data.frame(Fecha = character(), `Avance del día` = numeric(), check.names = FALSE)
    empty <- list(has_previous = FALSE, actual = 0, previous = 0, delta = 0, previous_date = "", last7 = empty_last7)
    if (!nrow(df) || !"Fecha" %in% names(df)) return(empty)
    df$.__date <- suppressWarnings(as.Date(as.character(df$Fecha)))
    df <- df[!is.na(df$.__date), , drop = FALSE]
    if (!nrow(df)) return(empty)
    df <- df[order(df$.__date), , drop = FALSE]
    daily_col <- intersect(c("Nuevas efectivas", "Efectivas", "Nuevas UMP efectivas", "Total respuestas"), names(df))
    daily_col <- if (length(daily_col)) daily_col[[1]] else ""
    df$.__daily <- if (nzchar(daily_col)) num(df[[daily_col]]) else rep(0, nrow(df))
    accum_col <- intersect(c("Acumulado", "Efectivas acumuladas", "UMP efectivas acumuladas"), names(df))
    df$.__accum <- if (length(accum_col)) num(df[[accum_col[[1]]]]) else cumsum(df$.__daily)
    current_idx <- nrow(df)
    current_date <- df$.__date[[current_idx]]
    current_value <- df$.__accum[[current_idx]]
    weekdays <- suppressWarnings(as.POSIXlt(df$.__date)$wday)
    checkpoint_idx <- sort(unique(c(1L, which(!is.na(weekdays) & weekdays == 1L), current_idx)))
    previous_candidates <- checkpoint_idx[df$.__date[checkpoint_idx] < current_date]
    previous_idx <- if (length(previous_candidates)) previous_candidates[[length(previous_candidates)]] else NA_integer_
    last7 <- if (is.finite(previous_idx)) {
      df[df$.__date > df$.__date[[previous_idx]] & df$.__date <= current_date, c("Fecha", ".__date", ".__daily"), drop = FALSE]
    } else {
      tail(df[, c("Fecha", ".__date", ".__daily"), drop = FALSE], 7L)
    }
    if (!nrow(last7)) {
      last7 <- df[current_idx, c("Fecha", ".__date", ".__daily"), drop = FALSE]
    }
    names(last7)[names(last7) == ".__daily"] <- "Avance del día"
    list(
      has_previous = is.finite(previous_idx),
      actual = current_value,
      previous = if (is.finite(previous_idx)) df$.__accum[[previous_idx]] else 0,
      delta = if (is.finite(previous_idx)) current_value - df$.__accum[[previous_idx]] else 0,
      previous_date = if (is.finite(previous_idx)) as.character(df$.__date[[previous_idx]]) else "",
      last7 = last7
    )
  }
  validate_actor_bottom_insights <- function(actor, summary, recent) {
    issues <- character()
    if (!nrow(.monitoreo_workbook_df(summary$rows))) issues <- c(issues, "canales")
    if (!nrow(.monitoreo_workbook_df(recent$last7))) issues <- c(issues, "ritmo reciente")
    list(
      actor = as.character(actor %||% ""),
      ok = !length(issues),
      issues = issues
    )
  }
  draw_actor_bottom_insights <- function(actor, sources_df, daily_df, x0, y0, w, h) {
    summary <- channel_summary(sources_df)
    recent <- weekly_recent_summary(daily_df)
    validation <- validate_actor_bottom_insights(actor, summary, recent)
    rr(x0, y0, w, h, fill = "#ffffff", col = border, lwd = 1.1)
    title_y <- y0 + h - 0.028
    content_top <- y0 + h - 0.064
    content_bottom <- y0 + 0.026
    txt("Canales y ritmo reciente", x0 + 0.020, title_y, size = 9.6, col = ink, face = "bold", just = c("left", "top"))

    left_x <- x0 + 0.024
    left_w <- w * 0.478
    divider_x <- x0 + w * 0.535
    right_x <- x0 + w * 0.568
    right_w <- x0 + w - 0.024 - right_x
    line(divider_x, content_bottom, divider_x, content_top, col = grid_line, lwd = 0.7)

    txt("Canales", left_x, content_top - 0.004, size = 6.0, col = muted, face = "bold", just = c("left", "top"))
    grouped <- summary$rows
    if (nrow(grouped)) {
      rows <- grouped[seq_len(min(nrow(grouped), 4L)), , drop = FALSE]
      max_eff <- max(num(rows$Efectivas), 1)
      row_top <- content_top - 0.032
      row_bottom <- content_bottom + if (nrow(grouped) > nrow(rows)) 0.026 else 0.004
      row_step <- min(0.036, max(0.024, (row_top - row_bottom) / max(1, nrow(rows))))
      row_y <- row_top
      label_w <- 0.170
      value_w <- 0.036
      bar_x <- left_x + label_w
      bar_w <- max(0.060, left_w - label_w - value_w - 0.018)
      value_x <- bar_x + bar_w + value_w
      for (k in seq_len(nrow(rows))) {
        txt(ellipsize(rows$Canal[[k]], 24), left_x, row_y, size = 6.7, col = ink, face = "bold", just = c("left", "center"))
        txt(fmt(rows$Efectivas[[k]]), value_x, row_y, size = 6.9, col = ink, face = "bold", just = c("right", "center"))
        rr(bar_x, row_y - 0.006, bar_w, 0.012, fill = "#edf2f8", col = NA, lwd = 0, r = 0.006)
        rr(bar_x, row_y - 0.006, max(0.006, bar_w * one_num(rows$Efectivas[[k]]) / max_eff), 0.012, fill = effective, col = NA, lwd = 0, r = 0.006)
        row_y <- row_y - row_step
      }
      if (nrow(grouped) > nrow(rows)) {
        txt(paste("+", nrow(grouped) - nrow(rows), "canales adicionales"), left_x, content_bottom + 0.004, size = 5.8, col = muted, face = "bold")
      }
    } else {
      txt("Sin canales reportados.", left_x, content_top - 0.060, size = 7.0, col = muted, face = "bold")
    }

    metric_h <- min(0.074, max(0.062, (content_top - content_bottom) * 0.44))
    metric_y <- content_top - metric_h
    strip_y <- content_bottom
    strip_h <- max(0.075, metric_y - strip_y - 0.012)
    rr(right_x, metric_y, right_w, metric_h, fill = "#f8fbff", col = "#e0e9f5", lwd = 0.85, r = 0.012)
    txt("Desde último informe", right_x + 0.014, metric_y + metric_h - 0.014, size = 5.8, col = muted, face = "bold", just = c("left", "top"))
    if (isTRUE(recent$has_previous)) {
      delta_prefix <- if (one_num(recent$delta) > 0) "+" else ""
      txt(paste0(delta_prefix, fmt(recent$delta)), right_x + 0.014, metric_y + metric_h * 0.36, size = 15.5, col = effective, face = "bold", just = c("left", "center"))
      txt(
        paste0(fmt(recent$actual), " acumuladas\n", fmt(recent$previous), " al ", short_day(recent$previous_date)),
        right_x + 0.102,
        metric_y + metric_h * 0.36,
        size = 5.8,
        col = muted,
        face = "bold",
        just = c("left", "center"),
        lineheight = 1.00
      )
    } else {
      txt("Sin reporte anterior", right_x + 0.014, metric_y + metric_h * 0.38, size = 8.2, col = muted, face = "bold")
    }

    rr(right_x, strip_y, right_w, strip_h, fill = "#ffffff", col = "#edf2f8", lwd = 0.7, r = 0.012)
    txt(if (isTRUE(recent$has_previous)) "Desde último informe" else "Días disponibles", right_x + 0.014, strip_y + strip_h - 0.012, size = 5.8, col = muted, face = "bold", just = c("left", "top"))
    last7 <- .monitoreo_workbook_df(recent$last7)
    if (nrow(last7)) {
      recent_col <- intersect(c("Avance del día", "Nuevas efectivas", "Efectivas", "Total respuestas"), names(last7))
      recent_col <- if (length(recent_col)) recent_col[[1]] else ""
      values <- if (nzchar(recent_col)) num(last7[[recent_col]]) else rep(0, nrow(last7))
      max_val <- max(values, 1)
      chart_x <- right_x + 0.018
      chart_w <- right_w - 0.036
      chart_y <- strip_y + 0.026
      chart_h <- max(0.022, strip_h - 0.058)
      slots <- nrow(last7)
      xs <- if (slots == 1L) chart_x + chart_w / 2 else chart_x + chart_w * (seq_len(slots) - 1) / (slots - 1)
      bar_w <- min(0.020, chart_w / max(7, slots) * 0.42)
      for (j in seq_len(slots)) {
        bar_h <- if (values[[j]] > 0) max(0.006, chart_h * values[[j]] / max_val) else 0
        if (bar_h > 0) rect(xs[[j]] - bar_w / 2, chart_y, bar_w, bar_h, effective, col = NA)
        txt(fmt(values[[j]]), xs[[j]], chart_y + chart_h + 0.006, size = 4.7, col = effective, face = "bold", just = c("center", "center"))
        txt(gsub(" ", "\n", short_day(last7$Fecha[[j]]), fixed = TRUE), xs[[j]], strip_y + 0.012, size = 4.4, col = faint, just = c("center", "center"), lineheight = 0.84)
      }
    } else {
      txt("Sin actividad reciente.", right_x + 0.014, strip_y + strip_h / 2, size = 6.6, col = muted, face = "bold")
    }
    if (!isTRUE(validation$ok)) {
      txt("Bloque validado con información parcial.", x0 + w - 0.020, y0 + 0.016, size = 4.7, col = faint, face = "bold", just = c("right", "bottom"))
    }
  }
  draw_wrapped_lines <- function(text, x, y, max_chars = 96, size = 6.6, col = muted,
                                 face = "plain", line_step = 0.018) {
    lines <- strwrap(as.character(text %||% ""), width = max_chars)
    if (!length(lines)) return(y)
    for (line_text in lines) {
      txt(line_text, x, y, size = size, col = col, face = face, just = c("left", "top"))
      y <- y - line_step
    }
    y
  }
  source_label <- function(value) {
    value <- as.character(value %||% "")
    value[is.na(value)] <- ""
    value <- trimws(value)
    ifelse(nzchar(value), value, "Fuente operativa")
  }
  source_col <- function(df, name, default = "") {
    if (!is.data.frame(df) || !name %in% names(df)) return(rep(default, nrow(df)))
    values <- as.character(df[[name]] %||% default)
    values[is.na(values)] <- default
    values
  }
  source_num_col <- function(df, name, default = 0) {
    if (!is.data.frame(df) || !name %in% names(df)) return(rep(default, nrow(df)))
    num(df[[name]])
  }
  draw_sources_page <- function() {
    draw_page()
    txt("Corte y fuentes", 0.055, 0.855, size = 18, col = ink, face = "bold")
    txt("Trazabilidad resumida del reporte cliente y criterio canónico usado para el avance.", 0.055, 0.826, size = 7.6, col = muted, face = "bold")

    metric_box(0.055, 0.735, 0.205, 0.070, "Corte publicado", generated_label, "", "base")
    metric_box(0.280, 0.735, 0.205, 0.070, "Universo", state_value_label(total_universe, total_universe), "", "base")
    metric_box(0.505, 0.735, 0.205, 0.070, "Efectivas", state_value_label(total_effective, total_universe), "", "effective")
    metric_box(0.730, 0.735, 0.205, 0.070, "Sin respuesta", state_value_label(total_pending, total_universe), "", "pending")

    rr(0.055, 0.565, 0.890, 0.130, fill = "#ffffff", col = border, lwd = 1.1)
    txt("Fuente de verdad", 0.075, 0.667, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
    y <- 0.638
    y <- draw_wrapped_lines(
      "La base oficial define el universo. Solo respuestas cruzadas contra un caso canónico de esa base suman como efectivas.",
      0.075, y, max_chars = 118, size = 6.8, col = muted, face = "bold", line_step = 0.019
    )
    draw_wrapped_lines(
      "Las respuestas de SurveyMonkey u otros canales se deduplican por actor + caso canónico; los canales no duplican personas.",
      0.075, y - 0.004, max_chars = 118, size = 6.8, col = muted, face = "bold", line_step = 0.019
    )

    rr(0.055, 0.310, 0.890, 0.235, fill = "#ffffff", col = border, lwd = 1.1)
    txt("Fuentes de respuestas", 0.075, 0.532, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
    source_rows <- .monitoreo_workbook_df(sources)
    if (nrow(source_rows)) {
      source_rows$.__eff <- source_num_col(source_rows, "Efectivas")
      source_rows <- source_rows[order(
        -source_rows$.__eff,
        source_col(source_rows, "Actor", "Sin actor"),
        source_col(source_rows, "Canal", "Sin canal"),
        source_col(source_rows, "Fuente", "Fuente operativa")
      ), , drop = FALSE]
      rows <- source_rows[seq_len(min(7L, nrow(source_rows))), , drop = FALSE]
      header_y <- 0.500
      txt("Actor", 0.075, header_y, size = 5.8, col = muted, face = "bold")
      txt("Canal", 0.225, header_y, size = 5.8, col = muted, face = "bold")
      txt("Fuente", 0.385, header_y, size = 5.8, col = muted, face = "bold")
      txt("Efectivas", 0.790, header_y, size = 5.8, col = muted, face = "bold", just = c("right", "center"))
      txt("Última completa", 0.925, header_y, size = 5.8, col = muted, face = "bold", just = c("right", "center"))
      line(0.075, 0.486, 0.925, 0.486, col = grid_line, lwd = 0.65)
      row_y <- 0.463
      for (i in seq_len(nrow(rows))) {
        actor <- source_col(rows, "Actor", "Sin actor")[[i]]
        channel <- channel_alias(source_col(rows, "Canal", "Sin canal")[[i]])
        source <- source_label(source_col(rows, "Fuente", "")[[i]])
        last_effective <- source_col(rows, "Última efectiva", "")[[i]]
        if (!nzchar(last_effective)) last_effective <- source_col(rows, "Última respuesta", "")[[i]]
        txt(ellipsize(actor, 24), 0.075, row_y, size = 6.2, col = ink, face = "bold", just = c("left", "center"))
        txt(ellipsize(channel, 24), 0.225, row_y, size = 6.1, col = ink, just = c("left", "center"))
        txt(ellipsize(source, 44), 0.385, row_y, size = 6.1, col = ink, just = c("left", "center"))
        txt(fmt(source_num_col(rows, "Efectivas")[[i]]), 0.790, row_y, size = 6.1, col = ink, face = "bold", just = c("right", "center"))
        txt(ellipsize(last_effective, 18), 0.925, row_y, size = 5.8, col = muted, face = "bold", just = c("right", "center"))
        row_y <- row_y - 0.025
      }
      if (nrow(source_rows) > nrow(rows)) {
        txt(paste("+", nrow(source_rows) - nrow(rows), "fuentes adicionales en el workbook cliente"), 0.075, 0.343, size = 5.7, col = muted, face = "bold")
      }
    } else {
      txt("Sin fuentes reportadas en el modelo.", 0.075, 0.455, size = 7.0, col = muted, face = "bold")
    }

    rr(0.055, 0.115, 0.890, 0.180, fill = "#ffffff", col = border, lwd = 1.1)
    txt("Lectura para cliente", 0.075, 0.267, size = 9.2, col = ink, face = "bold", just = c("left", "top"))
    draw_wrapped_lines(
      "Este PDF resume el avance ejecutivo. El detalle completo del corte, fuentes, canales y registros auditables queda en el XLSX/Sheet cliente e interno generado desde el mismo motor.",
      0.075, 0.235, max_chars = 118, size = 6.8, col = muted, face = "bold", line_step = 0.019
    )
    draw_wrapped_lines(
      "No se usa el Apps Script viejo como fuente de verdad para estos conteos.",
      0.075, 0.175, max_chars = 118, size = 6.8, col = muted, face = "bold", line_step = 0.019
    )
  }

  if (nrow(actors)) {
    draw_actor_overview_page(actors)
    for (i in seq_len(nrow(actors))) {
      actor <- as.character(actors$Actor[[i]])
      actor_daily_df <- daily_actor[daily_actor$Actor == actor, , drop = FALSE]
      actor_sources <- sources[sources$Actor == actor, , drop = FALSE]
      state <- actor_state(actors[i, , drop = FALSE])
      draw_page()
      txt(ellipsize(actor, 58), 0.055, 0.855, size = 18, col = ink, face = "bold")
      metric_box(0.055, 0.735, 0.205, 0.070, "Efectivas", state_value_label(state$efectivas, state$universo), "", "effective")
      metric_box(0.280, 0.735, 0.205, 0.070, "Parciales", state_value_label(state$parciales, state$universo), "", "partial")
      metric_box(0.505, 0.735, 0.205, 0.070, "Rechazo", state_value_label(state$rechazo, state$universo), "", "refusal")
      metric_box(0.730, 0.735, 0.205, 0.070, "Sin respuesta", state_value_label(state$sin_respuesta, state$universo), "", "pending")
      draw_state_composition(0.055, 0.690, 0.890, 0.020, state, compact = FALSE)
      draw_effective_trend(actor_daily_df, 0.055, 0.380, 0.890, 0.250, "Avance diario")
      draw_actor_bottom_insights(actor, actor_sources, actor_daily_df, 0.055, 0.095, 0.890, 0.260)
    }
  }

  draw_page()
  txt("Avance general", 0.055, 0.855, size = 18, col = ink, face = "bold")
  txt("Vista agregada del corte luego del detalle por actor.", 0.055, 0.826, size = 7.6, col = muted, face = "bold")
  total_state <- list(
    universo = total_universe,
    efectivas = total_effective,
    parciales = total_partial,
    rechazo = total_refusal,
    sin_respuesta = total_pending,
    referencia = sum(num(actors$`Referencia operativa` %||% actors$Meta), na.rm = TRUE),
    referencia_label = "Mínimo a alcanzar"
  )
  if (!is.finite(total_state$referencia) || total_state$referencia <= 0) total_state$referencia <- NA_real_
  metric_box(0.055, 0.735, 0.205, 0.070, "Efectivas", state_value_label(total_effective, total_universe), "", "effective")
  metric_box(0.280, 0.735, 0.205, 0.070, "Parciales", state_value_label(total_partial, total_universe), "", "partial")
  metric_box(0.505, 0.735, 0.205, 0.070, "Rechazo", state_value_label(total_refusal, total_universe), "", "refusal")
  metric_box(0.730, 0.735, 0.205, 0.070, "Sin respuesta", state_value_label(total_pending, total_universe), "", "pending")
  draw_state_composition(0.055, 0.690, 0.890, 0.020, total_state, compact = FALSE)
  draw_effective_trend(
    daily_general,
    0.055, 0.400, 0.890, 0.245,
    "Avance diario"
  )
  if (nrow(actors)) {
    draw_actor_board(actors, 0.055, 0.110, 0.890, 0.270, "Avance por grupo")
  }
  draw_sources_page()
  close_pdf()
  if (length(pdf_links)) .monitoreo_pdf_add_internal_links(output_file, pdf_links)
  invisible(output_file)
}

monitoreo_territorial_advance_report_pdf <- function(model, output_file, include_targets = FALSE, title = NULL) {
  if (is.null(output_file) || !nzchar(.monitoreo_scalar(output_file, ""))) {
    stop("Falta ruta de salida para el PDF territorial.", call. = FALSE)
  }
  records_df <- function(records) .monitoreo_workbook_df(records %||% list())
  num <- function(x) {
    out <- suppressWarnings(as.numeric(gsub("%", "", as.character(x))))
    out[!is.finite(out)] <- 0
    out
  }
  one_num <- function(x, default = 0) {
    out <- num(x)
    if (!length(out)) return(default)
    out[[1]]
  }
  fmt <- function(x) formatC(as.integer(round(one_num(x))), big.mark = ",", format = "d")
  pct_label <- function(x) {
    value <- suppressWarnings(as.numeric(gsub("%", "", as.character(x %||% ""))))
    if (!length(value) || !is.finite(value[[1]])) return("S/D")
    if (abs(value[[1]]) <= 1) value[[1]] <- value[[1]] * 100
    sprintf("%.1f%%", value[[1]])
  }
  pct_from <- function(value, target) {
    value <- one_num(value, NA_real_)
    target <- one_num(target, NA_real_)
    if (!is.finite(value) || !is.finite(target) || target <= 0) return(NA_real_)
    100 * value / target
  }
  ellipsize <- function(x, max_chars = 42) {
    x <- as.character(x %||% "")
    x[is.na(x)] <- ""
    vapply(x, function(item) {
      if (nchar(item, type = "width") <= max_chars) return(item)
      paste0(substr(item, 1L, max(1L, max_chars - 3L)), "...")
    }, character(1))
  }
  pretty_stamp <- function(x) {
    raw <- .monitoreo_scalar(x, "")
    if (!nzchar(raw)) return("sin fecha")
    parsed <- suppressWarnings(.monitoreo_parse_time_vec(raw))
    if (length(parsed) && !is.na(parsed[[1]])) {
      tz <- Sys.getenv("TZ", "")
      if (!nzchar(tz)) tz <- "America/Lima"
      months <- c("ene.", "feb.", "mar.", "abr.", "may.", "jun.", "jul.", "ago.", "set.", "oct.", "nov.", "dic.")
      local <- as.POSIXlt(parsed[[1]], tz = tz)
      return(sprintf("%02d %s %d, %02d:%02d", local$mday, months[[local$mon + 1L]], local$year + 1900L, local$hour, local$min))
    }
    raw
  }
  value_col <- function(df, label, cols = c("n", "Valor", "value", "Cantidad")) {
    df <- .monitoreo_workbook_df(df)
    if (!nrow(df) || !"Indicador" %in% names(df)) return("")
    idx <- which(.monitoreo_text_key(df$Indicador) == .monitoreo_text_key(label))
    if (!length(idx)) return("")
    for (col in cols) {
      if (col %in% names(df)) return(df[[col]][[idx[[1]]]])
    }
    ""
  }
  column_num <- function(df, col) {
    if (!nrow(df) || !col %in% names(df)) return(numeric(0))
    num(df[[col]])
  }
  first_col <- function(candidates, nms) {
    hit <- intersect(candidates, nms)
    if (length(hit)) hit[[1]] else ""
  }
  cell_value <- function(df, candidates, i, default = "") {
    df <- .monitoreo_workbook_df(df)
    if (!nrow(df) || i < 1L || i > nrow(df)) return(default)
    for (col in candidates) {
      if (col %in% names(df)) {
        value <- df[[col]][[i]]
        if (!is.null(value) && length(value) && !is.na(value[[1]]) && nzchar(.monitoreo_scalar(value, ""))) return(value)
      }
    }
    default
  }
  cell_num <- function(df, candidates, i, default = 0) {
    value <- cell_value(df, candidates, i, default = NA)
    out <- suppressWarnings(as.numeric(gsub("%", "", as.character(value))))
    if (length(out) && is.finite(out[[1]])) out[[1]] else default
  }
  section <- function(key) .monitoreo_publication_section_frame(model, key)
  block <- function(df, key) .monitoreo_publication_block_df(df, key)

  resumen <- section("resumen_operativo")
  if (!nrow(resumen)) resumen <- section("resumen_avance")
  avance <- section("avance_campo")
  quick <- block(resumen, "Lectura rapida de avance")
  if (!nrow(quick)) quick <- block(resumen, "Lectura rápida de avance")
  if (!nrow(quick)) quick <- block(resumen, "Tarjetas ejecutivas")
  district <- block(resumen, "Avance por distrito")
  if (!nrow(district)) district <- section("avance_por_distrito")
  production <- block(resumen, "Produccion por encuestador")
  if (!nrow(production)) production <- block(resumen, "Producción por encuestador")
  if (!nrow(production)) production <- section("avance_por_responsable")
  by_ump <- block(avance, "Avance por UMP/manzana")
  if (!nrow(by_ump)) by_ump <- section("avance_por_ump")
  daily <- records_df((model$daily_progress %||% list())$daily_effective)
  cumulative <- records_df((model$daily_progress %||% list())$cumulative_effective)

  total_row <- if (nrow(district) && "Distrito" %in% names(district)) {
    district[.monitoreo_text_key(district$Distrito) == "total", , drop = FALSE]
  } else {
    data.frame()
  }
  district_rows <- if (nrow(district) && "Distrito" %in% names(district)) {
    district[.monitoreo_text_key(district$Distrito) != "total", , drop = FALSE]
  } else {
    district
  }
  if (nrow(district_rows) && "UMP efectivas" %in% names(district_rows)) {
    district_rows <- district_rows[order(-column_num(district_rows, "UMP efectivas"), as.character(district_rows$Distrito)), , drop = FALSE]
  }
  if (nrow(production) && "UMP efectivas" %in% names(production)) {
    production <- production[order(-column_num(production, "UMP efectivas"), -column_num(production, "Encuestas válidas"), as.character(production$Responsable %||% "")), , drop = FALSE]
  }

  metric_value <- function(label, fallback = 0) {
    value <- value_col(quick, label)
    if (!nzchar(.monitoreo_scalar(value, "")) && nrow(total_row)) {
      lookup <- switch(label,
        "Encuestas válidas" = "Encuestas válidas",
        "Meta encuestas" = "Meta encuestas",
        "Brecha encuestas" = "Brecha encuestas",
        "Meta UMP" = "Meta UMP",
        "UMP efectivas" = "UMP efectivas",
        "UMP en campo" = "UMP en campo",
        "UMP pendientes" = "UMP pendientes",
        "UMP no iniciadas" = "UMP no iniciadas",
        "Reemplazos usados" = "Reemplazos usados",
        ""
      )
      if (nzchar(lookup) && lookup %in% names(total_row)) value <- total_row[[lookup]][[1]]
    }
    if (!nzchar(.monitoreo_scalar(value, ""))) fallback else value
  }

  sum_first_col <- function(df, candidates) {
    df <- .monitoreo_workbook_df(df)
    for (col in candidates) {
      if (col %in% names(df)) {
        values <- num(df[[col]])
        if (length(values)) return(sum(values, na.rm = TRUE))
      }
    }
    0
  }
  count_applied_rows <- function(df) {
    df <- .monitoreo_workbook_df(df)
    if (!nrow(df)) return(0)
    values <- NULL
    for (col in c("Efectivas", "Encuestas válidas", "Validas", "Válidas", "Casos efectivos")) {
      if (col %in% names(df)) {
        values <- num(df[[col]])
        break
      }
    }
    if (!is.null(values)) return(sum(values > 0, na.rm = TRUE))
    if ("Estado" %in% names(df)) {
      status <- .monitoreo_text_key(df$Estado)
      return(sum(!status %in% c("sin avance", "no iniciada", "no iniciado", "pendiente", ""), na.rm = TRUE))
    }
    0
  }
  applied_row_mask <- function(df) {
    df <- .monitoreo_workbook_df(df)
    if (!nrow(df)) return(logical(0))
    for (col in c("Efectivas", "Encuestas válidas", "Validas", "Válidas", "Casos efectivos")) {
      if (col %in% names(df)) return(num(df[[col]]) > 0)
    }
    if ("Estado" %in% names(df)) {
      status <- .monitoreo_text_key(df$Estado)
      return(!status %in% c("sin avance", "no iniciada", "no iniciado", "pendiente", ""))
    }
    rep(FALSE, nrow(df))
  }

  validas <- metric_value("Encuestas válidas")
  if (one_num(validas) <= 0 && nrow(district_rows)) validas <- sum_first_col(district_rows, c("Encuestas válidas", "Validas", "Válidas", "Efectivas"))
  meta_encuestas <- metric_value("Meta encuestas")
  if (one_num(meta_encuestas) <= 0 && nrow(district_rows)) meta_encuestas <- sum_first_col(district_rows, c("Meta encuestas", "Meta", "Referencia poblacional"))
  brecha_encuestas <- metric_value("Brecha encuestas")
  if (one_num(brecha_encuestas) <= 0 && one_num(meta_encuestas) > 0) brecha_encuestas <- max(0, one_num(meta_encuestas) - one_num(validas))
  ump_efectivas <- metric_value("UMP efectivas")
  if (one_num(ump_efectivas) <= 0 && nrow(by_ump)) ump_efectivas <- count_applied_rows(by_ump)
  meta_ump <- metric_value("Meta UMP")
  if (one_num(meta_ump) <= 0 && nrow(by_ump)) meta_ump <- nrow(by_ump)
  manzanas_muestrales <- ump_efectivas
  ump_campo <- metric_value("UMP en campo")
  ump_pendientes <- metric_value("UMP pendientes")
  ump_no_iniciadas <- metric_value("UMP no iniciadas")
  reemplazos_usados <- metric_value("Reemplazos usados")
  if (one_num(reemplazos_usados) <= 0 && nrow(by_ump) && "Tipo" %in% names(by_ump)) {
    replacement_mask <- .monitoreo_text_key(by_ump$Tipo) %in% c("reemplazo", "replacement")
    replacement_values <- if ("Efectivas" %in% names(by_ump)) num(by_ump$Efectivas) else rep(0, nrow(by_ump))
    reemplazos_usados <- sum(replacement_mask & replacement_values > 0, na.rm = TRUE)
  }
  avance_pct <- pct_from(validas, meta_encuestas)
  ump_pct <- pct_from(ump_efectivas, meta_ump)
  encuestas_por_zona_values <- {
    values <- numeric(0)
    for (col in c("Encuestas por manzana", "Encuestas por zona", "Cuota", "Meta")) {
      if (col %in% names(by_ump)) {
        values <- num(by_ump[[col]])
        break
      }
    }
    unique(values[is.finite(values) & values > 0])
  }
  encuestas_por_zona_num <- if (length(encuestas_por_zona_values) == 1L) encuestas_por_zona_values[[1]] else NA_real_
  encuestas_por_zona <- if (!length(encuestas_por_zona_values)) "S/D" else if (length(encuestas_por_zona_values) == 1L) fmt(encuestas_por_zona_num) else "Según ruta"

  report_title <- title %||% "Avance territorial de campo"
  generated_label <- pretty_stamp(model$synced_at %||% model$generated_at %||% "")
  pulso_logo_path <- function() {
    candidates <- c(
      system.file("hojas_ruta", "assets", "logo_pulso.png", package = "prosecnurapp"),
      file.path(getwd(), "api", "inst", "hojas_ruta", "assets", "logo_pulso.png"),
      file.path(getwd(), "api", "inst", "manuales_qmd", "files_manuales", "img", "logo_pulso.png"),
      file.path(getwd(), "inst", "hojas_ruta", "assets", "logo_pulso.png")
    )
    candidates <- candidates[nzchar(candidates) & file.exists(candidates)]
    if (length(candidates)) candidates[[1]] else ""
  }

  dir.create(dirname(output_file), recursive = TRUE, showWarnings = FALSE)
  grDevices::pdf(output_file, paper = "special", width = 11.69, height = 8.27, onefile = TRUE)
  pdf_device <- grDevices::dev.cur()
  pdf_closed <- FALSE
  close_pdf <- function() {
    if (isTRUE(pdf_closed)) return(invisible(NULL))
    tryCatch(
      {
        if (identical(grDevices::dev.cur(), pdf_device)) {
          grDevices::dev.off()
        } else {
          grDevices::dev.off(pdf_device)
        }
      },
      error = function(e) NULL
    )
    pdf_closed <<- TRUE
    invisible(NULL)
  }
  on.exit(close_pdf(), add = TRUE)

