  grid_line <- "#E7EDF5"
  pulso_blue <- "#002457"
  navy <- "#002457"
  deep_blue <- "#0B3A66"
  accent <- "#0369A1"
  teal <- "#0E7490"
  green <- "#0F8F7D"
  green_dark <- "#0F766E"
  blue_gray <- "#486176"
  slate <- "#64748B"
  surface_alt <- "#F8FAFC"
  blue_soft <- "#EEF4FA"
  blue_border <- "#C7D7E8"
  green_soft <- "#EAF5F2"
  green_border <- "#B9D2D7"
