    line(x + 0.025, y + 0.075, x + w - 0.025, y + 0.075, col = blue_border, lwd = 0.8)
    rect(x + 0.025, y + 0.032, 0.022, 0.022, fill = green, col = green_dark, lwd = 0.4)
