  }
  draw_map_summary_strip <- function(x, y, w, h) {
    rr(x, y, w, h, fill = surface_alt, col = blue_border, lwd = 1.0, r = 0.006)
    txt("Resumen de aplicación", x + 0.025, y + h - 0.030, size = 10.4, col = navy, face = "bold", just = c("left", "top"))
