      txt(item[[1]], cx, y + h - 0.078, size = value_size, col = pulso_blue, face = "bold", just = c("left", "center"))
      txt(item[[2]], cx, y + h - 0.112, size = 6.6, col = ink, face = "bold", just = c("left", "center"))
