.monitoreo_xlsx_max_cell_chars <- function() {
  32767L
}

.monitoreo_xlsx_warning_safe_chars <- function(limit = .monitoreo_xlsx_max_cell_chars()) {
  max(1000L, as.integer(limit) - 64L)
}

.monitoreo_xlsx_encoded_chars <- function(value) {
  value <- as.character(value %||% "")
  if (!length(value)) value <- ""
  value <- value[[1]]
  if (is.na(value)) value <- ""
  nchar(.monitoreo_xml_escape(value), type = "chars", allowNA = FALSE)
}

.monitoreo_xlsx_sanitize_cell <- function(value, limit = .monitoreo_xlsx_max_cell_chars()) {
  value <- as.character(value %||% "")
  if (!length(value)) value <- ""
  value <- value[[1]]
  if (is.na(value)) value <- ""

  limit <- suppressWarnings(as.integer(limit))
  if (!length(limit) || is.na(limit[[1]]) || !is.finite(limit[[1]]) || limit[[1]] < 1000L) {
    limit <- .monitoreo_xlsx_max_cell_chars()
  } else {
    limit <- limit[[1]]
  }

  chars <- nchar(value, type = "chars", allowNA = FALSE)
  encoded_chars <- .monitoreo_xlsx_encoded_chars(value)
  if (chars <= limit && encoded_chars <= limit) return(value)

  marker <- sprintf(
    "\n\n[Truncado para XLSX: %s caracteres originales; valor completo disponible en el modelo JSON/evidencia interna.]",
    chars
  )
  if (.monitoreo_xlsx_encoded_chars(marker) > .monitoreo_xlsx_warning_safe_chars(limit)) {
    marker <- sprintf("\n\n[Truncado para XLSX: %s caracteres originales.]", chars)
  }

  target <- .monitoreo_xlsx_warning_safe_chars(limit)
  best <- marker
  lo <- 0L
  hi <- chars
  while (lo <= hi) {
    mid <- floor((lo + hi) / 2)
    candidate <- paste0(substr(value, 1L, mid), marker)
    candidate_chars <- nchar(candidate, type = "chars", allowNA = FALSE)
    candidate_encoded_chars <- .monitoreo_xlsx_encoded_chars(candidate)
    if (candidate_chars <= limit && candidate_encoded_chars <= target) {
      best <- candidate
      lo <- mid + 1L
    } else {
      hi <- mid - 1L
    }
  }
  best
}

.monitoreo_xlsx_sanitize_df <- function(df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  for (col in seq_along(df)) {
    values <- df[[col]]
    if (is.list(values)) {
      df[[col]] <- vapply(values, function(item) {
        .monitoreo_xlsx_sanitize_cell(.monitoreo_workbook_cell_value(item))
      }, character(1))
    } else if (is.character(values) || is.factor(values)) {
      df[[col]] <- vapply(as.character(values), .monitoreo_xlsx_sanitize_cell, character(1), USE.NAMES = FALSE)
    }
  }
  df
}

.monitoreo_publication_add_sheet <- function(wb, sheet_name, df, styles) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) df <- data.frame(Estado = "Sin datos para este corte.", check.names = FALSE)
  pct_cols <- grep("avance|%|pct|cumplimiento", names(df), ignore.case = TRUE)
  if (length(pct_cols)) {
    for (col in pct_cols) {
      if (is.numeric(df[[col]])) {
        values <- df[[col]]
        if (any(abs(values) > 1, na.rm = TRUE)) df[[col]] <- values / 100
      } else {
        raw <- as.character(df[[col]])
        parsed <- suppressWarnings(as.numeric(gsub("%", "", gsub("[[:space:]]", "", gsub(",", ".", raw)))))
        parseable <- !nzchar(raw) | is.na(raw) | !is.na(parsed)
        if (all(parseable)) {
          needs_scale <- grepl("%", raw, fixed = TRUE) | abs(parsed) > 1
          df[[col]] <- ifelse(is.na(parsed), NA_real_, parsed / ifelse(needs_scale, 100, 1))
        }
      }
    }
  }
  df <- .monitoreo_xlsx_sanitize_df(df)
  sheet_name <- .monitoreo_workbook_sheet_name(sheet_name)
  existing <- names(wb)
  if (sheet_name %in% existing) {
    suffix <- 2L
    base <- substr(sheet_name, 1L, 28L)
    while (paste0(base, "_", suffix) %in% existing) suffix <- suffix + 1L
    sheet_name <- paste0(base, "_", suffix)
  }
  openxlsx::addWorksheet(wb, sheet_name, gridLines = FALSE)
  openxlsx::writeData(wb, sheet_name, sheet_name, startRow = 1, startCol = 1, colNames = FALSE)
  openxlsx::writeData(wb, sheet_name, sprintf("Generado por Prosecnur - %s", .monitoreo_now_iso()), startRow = 2, startCol = 1, colNames = FALSE)
  openxlsx::writeData(wb, sheet_name, df, startRow = 4, startCol = 1)
  n_cols <- max(1L, ncol(df))
  n_rows <- max(1L, nrow(df))
  openxlsx::addStyle(wb, sheet_name, styles$title, rows = 1, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
  openxlsx::addStyle(wb, sheet_name, styles$meta, rows = 2, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
  openxlsx::addStyle(wb, sheet_name, styles$header, rows = 4, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
  if (n_rows > 0L) {
    openxlsx::addStyle(wb, sheet_name, styles$body, rows = 5:(n_rows + 4L), cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    openxlsx::addFilter(wb, sheet_name, rows = 4, cols = 1:n_cols)
  }
  if (length(pct_cols) && n_rows > 0L) {
    openxlsx::addStyle(wb, sheet_name, styles$percent, rows = 5:(n_rows + 4L), cols = pct_cols, gridExpand = TRUE, stack = TRUE)
  }
  severity_cols <- grep("severidad|severity|prioridad|riesgo|estado|status|nivel", names(df), ignore.case = TRUE)
  if (length(severity_cols) && n_rows > 0L) {
    severity_text <- apply(df[, severity_cols, drop = FALSE], 1L, function(row) {
      tolower(paste(as.character(row), collapse = " "))
    })
    high <- grepl("crit|alto|alta|grave|danger|error|rojo|vencid|no defendible", severity_text)
    warn <- !high & grepl("medio|media|warn|alert|revision|observacion|pendiente|amarillo", severity_text)
    ok <- !high & !warn & grepl("ok|bajo|baja|resuelto|verde|valid|complet|efectiv", severity_text)
    if (any(high)) openxlsx::addStyle(wb, sheet_name, styles$severity_high, rows = which(high) + 4L, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    if (any(warn)) openxlsx::addStyle(wb, sheet_name, styles$severity_warn, rows = which(warn) + 4L, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    if (any(ok)) openxlsx::addStyle(wb, sheet_name, styles$severity_ok, rows = which(ok) + 4L, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
  }
  openxlsx::freezePane(wb, sheet_name, firstActiveRow = 5)
  widths <- pmin(42, pmax(12, nchar(names(df)) + 4L))
  openxlsx::setColWidths(wb, sheet_name, cols = 1:n_cols, widths = widths)
  invisible(sheet_name)
}

.monitoreo_publication_rows_rect_df <- function(rows) {
  rows <- rows %||% list()
  if (!length(rows)) rows <- list("Sin datos para este corte.")
  max_cols <- max(1L, max(vapply(rows, function(row) length(row %||% character(0)), integer(1))))
  padded <- lapply(rows, function(row) {
    values <- vapply(row %||% character(0), .monitoreo_workbook_cell_value, character(1))
    length(values) <- max_cols
    values[is.na(values)] <- ""
    values
  })
  out <- as.data.frame(do.call(rbind, padded), stringsAsFactors = FALSE, check.names = FALSE)
  names(out) <- paste0("V", seq_len(ncol(out)))
  .monitoreo_xlsx_sanitize_df(out)
}

.monitoreo_publication_rows_col_widths <- function(rows, n_cols) {
  rows <- rows %||% list()
  widths <- rep(12L, n_cols)
  for (col in seq_len(n_cols)) {
    values <- vapply(rows, function(row) {
      value <- if (length(row %||% character(0)) >= col) row[[col]] else ""
      .monitoreo_workbook_cell_value(value)
    }, character(1))
    widths[[col]] <- min(44L, max(12L, max(nchar(values), na.rm = TRUE) + 3L))
  }
  widths
}

.monitoreo_publication_add_rows_sheet <- function(wb, sheet_name, rows, styles) {
  rows <- rows %||% list()
  sheet_name <- .monitoreo_workbook_sheet_name(sheet_name)
  existing <- names(wb)
  if (sheet_name %in% existing) {
    suffix <- 2L
    base <- substr(sheet_name, 1L, 28L)
    while (paste0(base, "_", suffix) %in% existing) suffix <- suffix + 1L
    sheet_name <- paste0(base, "_", suffix)
  }
  df <- .monitoreo_publication_rows_rect_df(rows)
  n_cols <- max(1L, ncol(df))
  n_rows <- max(1L, nrow(df))
  openxlsx::addWorksheet(wb, sheet_name, gridLines = FALSE)
  openxlsx::writeData(wb, sheet_name, df, startRow = 1, startCol = 1, colNames = FALSE)
  section_rows <- which(vapply(rows, .monitoreo_sheets_is_section_row, logical(1)))
  if (length(section_rows)) {
    for (idx in section_rows) {
      openxlsx::addStyle(wb, sheet_name, styles$section, rows = idx, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    }
  }
  headers <- .monitoreo_sheets_table_header_rows(rows)
  if (length(headers)) {
    for (item in headers) {
      idx <- item$index
      header <- item$header
      header_cols <- seq_len(max(1L, length(header)))
      openxlsx::addStyle(wb, sheet_name, styles$header, rows = idx, cols = header_cols, gridExpand = TRUE, stack = TRUE)
      end_idx <- .monitoreo_sheets_next_block_end(rows, idx)
      if (end_idx > idx) {
        body_rows <- (idx + 1L):end_idx
        body_rows <- body_rows[body_rows <= n_rows]
        if (length(body_rows)) {
          openxlsx::addStyle(wb, sheet_name, styles$body, rows = body_rows, cols = header_cols, gridExpand = TRUE, stack = TRUE)
          pct_cols <- .monitoreo_sheets_progress_columns(header)
          pct_cols <- pct_cols[pct_cols <= length(header)]
          if (length(pct_cols)) {
            openxlsx::addStyle(wb, sheet_name, styles$percent, rows = body_rows, cols = pct_cols, gridExpand = TRUE, stack = TRUE)
          }
        }
      }
    }
    filter_idx <- .monitoreo_sheets_filter_header_index(sheet_name, rows, headers)
    filter_match <- which(vapply(headers, function(item) identical(item$index, filter_idx), logical(1)))
    filter_item <- headers[[if (length(filter_match)) filter_match[[1]] else 1L]]
    filter_cols <- seq_len(max(1L, length(filter_item$header)))
    end_idx <- .monitoreo_sheets_next_block_end(rows, filter_idx)
    if (end_idx > filter_idx) {
      try(openxlsx::addFilter(wb, sheet_name, rows = filter_idx, cols = filter_cols), silent = TRUE)
    }
    openxlsx::freezePane(wb, sheet_name, firstActiveRow = min(n_rows + 1L, max(2L, filter_idx + 1L)))
  } else {
    openxlsx::addStyle(wb, sheet_name, styles$body, rows = 1:n_rows, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    openxlsx::freezePane(wb, sheet_name, firstActiveRow = 2)
  }
  card_sections <- section_rows[vapply(section_rows, function(idx) {
    values <- .monitoreo_sheets_row_values(rows[[idx]])
    grepl("INDICADORES DEL CORTE|TARJETAS|CARDS", .monitoreo_scalar(values[[1]] %||% "", ""), ignore.case = TRUE)
  }, logical(1))]
  for (section_idx in card_sections) {
    block_end <- .monitoreo_sheets_next_block_end(rows, section_idx)
    card_rows <- seq.int(section_idx + 1L, block_end)
    card_rows <- card_rows[card_rows <= n_rows]
    card_rows <- card_rows[!vapply(rows[card_rows], .monitoreo_sheets_is_blank_row, logical(1))]
    if (length(card_rows)) {
      openxlsx::addStyle(wb, sheet_name, styles$card, rows = card_rows, cols = 1:n_cols, gridExpand = TRUE, stack = TRUE)
    }
  }
  openxlsx::setColWidths(wb, sheet_name, cols = 1:n_cols, widths = .monitoreo_publication_rows_col_widths(rows, n_cols))
  invisible(sheet_name)
}

.monitoreo_publication_sheet_rows <- function(title, df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) df <- data.frame(Estado = "Sin datos para este corte.", check.names = FALSE)
  rows <- list(names(df))
  for (idx in seq_len(nrow(df))) {
    rows[[length(rows) + 1L]] <- vapply(df[idx, , drop = FALSE], .monitoreo_workbook_cell_value, character(1))
  }
  rows
}

.monitoreo_sheets_section_row <- function(title) {
  list(toupper(.monitoreo_scalar(title, "")))
}

.monitoreo_sheets_blank_row <- function() {
  character(0)
}

.monitoreo_sheets_table_rows <- function(df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) df <- data.frame(Estado = "Sin datos para este corte.", check.names = FALSE)
  rows <- list(names(df))
  pct_cols <- .monitoreo_sheets_progress_columns(names(df))
  for (idx in seq_len(nrow(df))) {
    values <- vapply(df[idx, , drop = FALSE], .monitoreo_workbook_cell_value, character(1))
    for (col in pct_cols) {
      raw <- values[[col]]
      parsed <- suppressWarnings(as.numeric(gsub("%", "", gsub("[[:space:]]", "", gsub(",", ".", raw)))))
      if (nzchar(raw) && is.finite(parsed) && !grepl("%", raw, fixed = TRUE)) {
        values[[col]] <- sprintf("%.1f%%", parsed)
      }
    }
    rows[[length(rows) + 1L]] <- values
  }
  rows
}

.monitoreo_sheets_section_table <- function(title, df) {
  c(list(.monitoreo_sheets_section_row(title)), .monitoreo_sheets_table_rows(df), list(.monitoreo_sheets_blank_row()))
}

.monitoreo_sheets_card_rows <- function(title, df, cards_per_row = 3L) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) || !"Indicador" %in% names(df)) {
    return(.monitoreo_sheets_section_table(title, df))
  }
  cards_per_row <- max(1L, min(4L, .monitoreo_int(cards_per_row, 3L)))
  rows <- list(.monitoreo_sheets_section_row(title))
  pct_col <- if ("%" %in% names(df)) "%" else ""
  for (start in seq(1L, nrow(df), by = cards_per_row)) {
    end <- min(nrow(df), start + cards_per_row - 1L)
    title_row <- character(0)
    value_row <- character(0)
    note_row <- character(0)
    for (idx in seq.int(start, end)) {
      card <- df[idx, , drop = FALSE]
      pct <- if (nzchar(pct_col)) {
        raw <- suppressWarnings(as.numeric(card[[pct_col]][[1]] %||% NA_real_))
        if (is.finite(raw)) sprintf("%.1f%%", raw) else ""
      } else {
        ""
      }
      title_row <- c(title_row, .monitoreo_workbook_cell_value(card$Indicador[[1]]), "", "")
      value_row <- c(value_row, .monitoreo_workbook_cell_value(card$n[[1]] %||% card$Valor[[1]] %||% ""), pct, "")
      note_row <- c(note_row, .monitoreo_workbook_cell_value(card$Lectura[[1]] %||% card$Estado[[1]] %||% ""), .monitoreo_workbook_cell_value(card$Estado[[1]] %||% ""), "")
    }
    missing_cards <- cards_per_row - (end - start + 1L)
    if (missing_cards > 0L) {
      for (i in seq_len(missing_cards)) {
        title_row <- c(title_row, "", "", "")
        value_row <- c(value_row, "", "", "")
        note_row <- c(note_row, "", "", "")
      }
    }
    rows <- c(rows, list(title_row, value_row, note_row, .monitoreo_sheets_blank_row()))
  }
  rows
}

.monitoreo_publication_block_df <- function(df, block) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) || !"Bloque" %in% names(df)) return(data.frame())
  out <- df[as.character(df$Bloque) == block, setdiff(names(df), "Bloque"), drop = FALSE]
  if (nrow(out) && ncol(out)) {
    keep <- vapply(out, function(col) {
      values <- as.character(col)
      values[is.na(values)] <- ""
      any(nzchar(trimws(values)))
    }, logical(1))
    if (identical(block, "Asignación planificada")) {
      keep <- keep | names(out) == "Última actividad" | grepl("^Encuesta [0-9]+$", names(out))
    }
    out <- out[, keep, drop = FALSE]
  }
  rownames(out) <- NULL
  out
}

.monitoreo_publication_cols_first <- function(df, cols) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  cols <- cols[cols %in% names(df)]
  df[, c(cols, setdiff(names(df), cols)), drop = FALSE]
}

.monitoreo_publication_drop_operational_technical_cols <- function(df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  technical <- c("tipo_manzana", "reemplazo", "titular_id_manzana", "replacement_order")
  df[, setdiff(names(df), technical), drop = FALSE]
}

.monitoreo_publication_drop_empty_columns <- function(df, keep = character()) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  keep <- intersect(as.character(keep %||% character(0)), names(df))
  has_value <- vapply(df, function(col) {
    values <- trimws(as.character(col))
    values[is.na(values)] <- ""
    any(nzchar(values))
  }, logical(1))
  has_value[names(has_value) %in% keep] <- TRUE
  df[, has_value, drop = FALSE]
}

.monitoreo_publication_accreditation_present_values <- function(df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  replacements <- c(
    "No disponible" = "Sin dato",
    "No registrado" = "Sin registro",
    "No registrada" = "Sin registro",
    "Sin umbral configurado" = "Sin mínimo configurado",
    "Efectivas" = "Completas",
    "Meta alcanzada" = "Mínimo completo",
    "Mínimo alcanzado" = "Mínimo completo",
    "Sobre el mínimo" = "Por encima del mínimo",
    "Cerca del mínimo" = "Cerca de completar",
    "Bajo mínimo" = "Falta avance",
    "En campo" = "En seguimiento",
    "Pendientes universo" = "Pendientes por cubrir",
    "Brecha contra mínimo" = "Faltan para mínimo",
    "% sobre mínimo" = "% mínimo logrado",
    "% sobre universo" = "% universo logrado",
    "% avance universo" = "% avance",
    "% cobertura" = "% avance",
    "Filas internas de seguimiento" = "Filas de seguimiento",
    "Referencia operativa total" = "Mínimo esperado",
    "% umbral interno" = "% mínimo logrado",
    "Campos técnicos crudos" = "Campos del registro",
    "Actor faltante" = "Actor sin asignar",
    "Fecha faltante" = "Fecha sin registro",
    "Baja cobertura" = "Avance bajo",
    "Actor por debajo del mínimo interno." = "Actor por debajo del mínimo esperado.",
    "Avance de campo" = "Avance del corte",
    "Encuestadores y rutas" = "Responsables y fuentes",
    "Validacion de tiempos" = "Validación del registro",
    "Validación de tiempos" = "Validación del registro",
    "Enumerador" = "Responsable de carga",
    "Fecha de encuesta" = "Fecha de respuesta",
    "Estado del caso" = "Estado de respuesta",
    "Duracion" = "Duración",
    "config" = "Configuración",
    "email" = "Correo electrónico",
    "weblink" = "Enlace web",
    "web link" = "Enlace web",
    "phone" = "Telefónico",
    "telephone" = "Telefónico"
  )
  for (col in names(df)) {
    if (!is.character(df[[col]]) && !is.factor(df[[col]])) next
    values <- as.character(df[[col]])
    replace_idx <- match(values, names(replacements))
    values[!is.na(replace_idx)] <- unname(replacements[replace_idx[!is.na(replace_idx)]])
    df[[col]] <- values
  }
  df
}

.monitoreo_publication_accreditation_normalize_dates <- function(df) {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  date_cols <- grep(
    "fecha|registro|efectiva|actualizaci[oó]n|corte publicado|corte de datos",
    names(df),
    ignore.case = TRUE
  )
  for (col in date_cols) {
    raw <- trimws(as.character(df[[col]] %||% ""))
    raw[is.na(raw)] <- ""
    parsed <- suppressWarnings(.monitoreo_parse_time_vec(raw))
    has_date <- !is.na(parsed)
    if (any(has_date)) raw[has_date] <- as.character(as.Date(parsed[has_date]))
    df[[col]] <- raw
  }
  df
}

.monitoreo_publication_accreditation_present_df <- function(df, audience = "client", purpose = "") {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) && !ncol(df)) return(df)
  audience <- .monitoreo_workbook_audience(audience)
  purpose <- .monitoreo_text_key(purpose)
  if (all(c("% avance universo", "% cobertura") %in% names(df))) {
    df <- df[, setdiff(names(df), "% cobertura"), drop = FALSE]
  }
  if (identical(audience, "client")) {
    noisy <- grep(
      "session|spreadsheet|warning|warnings|campo detectado|columna detectada|seccion|sección|origen tecnico|origen técnico|schema|source_id|^\\.|^_",
      names(df),
      ignore.case = TRUE
    )
    if (length(noisy) && purpose %in% c("fuentes_actualizacion", "sources", "corte_y_fuentes")) {
      df <- df[, -noisy, drop = FALSE]
    }
  }
  names_map <- c(
    "Mínimo/meta operativa" = "Mínimo esperado",
    "Referencia operativa" = "Mínimo esperado",
    "% sobre mínimo" = "% mínimo logrado",
    "% sobre mínimo acumulado" = "% mínimo acumulado",
    "% umbral interno" = "% mínimo logrado",
    "% umbral interno acumulado" = "% mínimo acumulado",
    "Brecha contra mínimo" = "Faltan para mínimo",
    "Brecha umbral interno" = "Faltan para mínimo",
    "Estado interno" = "Estado del mínimo",
    "Estado umbral interno" = "Estado del mínimo",
    "% avance universo" = "% avance",
    "% avance universo acumulado" = "% avance acumulado",
    "% sobre universo" = "% universo logrado",
    "Efectivas" = "Completas",
    "Nuevas efectivas" = "Completas del día",
    "Efectivas acumuladas" = "Completas acumuladas",
    "Último aumento" = "Último avance",
    "Rechazos plataforma" = "Rechazo",
    "Rechazos" = "Rechazo",
    "Sin respuesta plataforma" = "Sin respuesta",
    "Total respuestas" = "Respuestas registradas",
    "Primer día" = "Primer registro",
    "Última respuesta" = "Último registro",
    "Última efectiva" = "Última completa",
    "Canal" = "Canal operativo",
    "Fuente" = "Título / fuente",
    "Recopilador" = "Responsable de carga",
    "Collector" = "Responsable de carga",
    "Tipo recopilador" = "Tipo de responsable",
    "Pendientes universo" = "Pendientes por cubrir",
    "Filas internas de seguimiento" = "Filas de seguimiento",
    "Base técnica" = "Registros del corte",
    "Auditoría técnica" = "Trazabilidad del corte",
    "Seccion" = "Sección",
    "Fecha/hora de publicación" = "Corte publicado",
    "Tipo registro" = "Tipo de información",
    "Campo detectado" = "Campo usado"
  )
  if (identical(audience, "internal") && purpose %in% c("control_seguimiento", "seguimiento_operativo")) {
    names_map <- names_map[!names(names_map) %in% c("Rechazos plataforma", "Sin respuesta plataforma")]
  }
  mapped <- unname(names_map[names(df)])
  names(df)[!is.na(mapped) & nzchar(mapped)] <- mapped[!is.na(mapped) & nzchar(mapped)]
  if (purpose %in% c("alertas_internas", "casos_accionables", "auditoria_tecnica")) {
    alert_map <- c(
      "Prioridad" = "Nivel",
      "Tipo de alerta" = "Motivo",
      "ID caso" = "Caso",
      "Descripción" = "Detalle",
      "Fuente" = if (identical(purpose, "auditoria_tecnica")) "Origen de alerta" else "Origen"
    )
    mapped_alert <- unname(alert_map[names(df)])
    names(df)[!is.na(mapped_alert) & nzchar(mapped_alert)] <- mapped_alert[!is.na(mapped_alert) & nzchar(mapped_alert)]
  }
  if (purpose %in% c("base_tecnica", "registros")) {
    base_map <- c(
      "response_id" = "ID registro",
      "_id" = "ID registro",
      "_uuid" = "UUID",
      "uuid" = "UUID",
      "nombre_contacto" = "Nombre",
      "correo_contacto" = "Correo",
      "telefono_contacto" = "Teléfono",
      "dim_actor" = "Actor",
      "carrera" = "Segmento",
      "fecha" = "Fecha",
      "status" = "Estado",
      "efectiva" = "Respondió",
      ".source_id" = "ID fuente",
      ".source_role" = "Rol fuente",
      ".source_label" = "Fuente"
    )
    mapped_base <- unname(base_map[names(df)])
    names(df)[!is.na(mapped_base) & nzchar(mapped_base)] <- mapped_base[!is.na(mapped_base) & nzchar(mapped_base)]
  }
  if (any(duplicated(names(df)))) {
    duplicate_names <- unique(names(df)[duplicated(names(df))])
    drop <- logical(ncol(df))
    for (nm in duplicate_names) {
      idx <- which(names(df) == nm)
      first <- idx[[1]]
      for (candidate in idx[-1]) {
        same_values <- identical(as.character(df[[first]]), as.character(df[[candidate]]))
        empty_values <- !any(nzchar(trimws(as.character(df[[candidate]]))), na.rm = TRUE)
        if (isTRUE(same_values) || isTRUE(empty_values)) drop[[candidate]] <- TRUE
      }
    }
    if (any(drop)) df <- df[, !drop, drop = FALSE]
    names(df) <- make.unique(names(df), sep = " ")
  }
  df <- .monitoreo_publication_accreditation_present_values(df)
  df <- .monitoreo_publication_accreditation_normalize_dates(df)
  if (purpose %in% c("summary", "resumen_ejecutivo", "resumen_operativo") && "Indicador" %in% names(df)) {
    indicator <- trimws(as.character(df$Indicador %||% ""))
    keep <- !duplicated(indicator)
    keep[!nzchar(indicator)] <- TRUE
    df <- df[keep, , drop = FALSE]
  }
  keep_empty_columns <- character()
  if (purpose %in% c("avance_por_canal_recopilador", "avance_por_canal_fuente", "channel")) {
    keep_empty_columns <- c(
      keep_empty_columns,
      "Canal operativo",
      "Responsable de carga",
      "Tipo de responsable"
    )
  }
  if (purpose %in% c("metas_internas_actor", "pendientes_por_actor", "targets", "pending", "avance_general", "avance_por_actor", "actor", "avance_diario", "daily", "avance_por_segmento", "segment")) {
    keep_empty_columns <- c(
      keep_empty_columns,
      "Mínimo esperado",
      "Faltan para mínimo",
      "% mínimo logrado",
      "Estado del mínimo"
    )
  }
  if (purpose %in% c("control_seguimiento", "seguimiento_operativo")) {
    keep_empty_columns <- c(keep_empty_columns, "Brecha mínimo")
    if (!"Brecha mínimo" %in% names(df)) {
      minimum_gap <- rep("", nrow(df))
      gap_col <- intersect(c("Faltan para mínimo", "Brecha contra mínimo"), names(df))
      if (length(gap_col)) {
        minimum_gap <- as.character(df[[gap_col[[1]]]])
      } else {
        minimum_col <- intersect(c("Mínimo esperado", "Mínimo", "Minimo", "Referencia operativa"), names(df))
        complete_col <- intersect(c("Completas", "Efectivas"), names(df))
        if (length(minimum_col) && length(complete_col)) {
          parse_number <- function(values) {
            suppressWarnings(as.numeric(gsub("%", "", gsub("[[:space:]]", "", gsub(",", ".", as.character(values))))))
          }
          minimum <- parse_number(df[[minimum_col[[1]]]])
          complete <- parse_number(df[[complete_col[[1]]]])
          gap <- pmax(minimum - complete, 0)
          gap[!is.finite(minimum) | !is.finite(complete)] <- NA_real_
          minimum_gap <- ifelse(is.na(gap), "", as.character(gap))
        }
      }
      df[["Brecha mínimo"]] <- minimum_gap
    }
  }
  df <- .monitoreo_publication_drop_empty_columns(df, keep = keep_empty_columns)
  if (purpose %in% c("avance_por_canal_recopilador", "avance_por_canal_fuente", "channel")) {
    df <- .monitoreo_publication_cols_first(df, c("Actor", "Canal operativo", "Título / fuente", "Responsable de carga", "Tipo de responsable", "Completas", "Parciales", "Rechazos", "Sin respuesta", "Respuestas registradas", "Primer registro", "Último registro", "Última completa"))
  } else if (purpose %in% c("control_seguimiento", "seguimiento_operativo")) {
    df <- .monitoreo_publication_cols_first(df, c("Actor", "Unidad", "Universo", "Mínimo esperado", "Mínimo", "Completas", "Parciales", "Rechazo", "Rechazos plataforma", "Rechazos telefónicos", "Sin respuesta", "Brecha mínimo", "% avance", "Avance total", "Estado"))
  } else if (purpose %in% c("metas_internas_actor", "pendientes_por_actor", "targets", "pending")) {
    df <- .monitoreo_publication_cols_first(df, c("Actor", "Universo", "Mínimo esperado", "Completas", "Pendientes", "Faltan para mínimo", "% mínimo logrado", "% universo logrado", "Último avance", "Estado del mínimo"))
  } else if (purpose %in% c("avance_por_actor", "actor")) {
    df <- .monitoreo_publication_cols_first(df, c("Actor", "Universo", "Completas", "Parciales", "Rechazo", "Sin respuesta", "% avance", "Mínimo esperado", "% mínimo logrado", "Faltan para mínimo", "Último avance", "Estado de avance", "Estado del mínimo"))
  } else if (purpose %in% c("avance_diario", "daily")) {
    df <- .monitoreo_publication_cols_first(df, c("Fecha", "Actor", "Completas del día", "Completas acumuladas", "Universo", "Sin respuesta", "Pendientes", "% avance acumulado", "Mínimo esperado", "% mínimo acumulado", "Faltan para mínimo", "Estado de avance"))
  } else if (purpose %in% c("avance_por_segmento", "segment")) {
    df <- .monitoreo_publication_cols_first(df, c("Segmento", "Actor", "Universo", "Completas", "Pendientes", "% avance", "Mínimo esperado", "% mínimo logrado", "Faltan para mínimo", "Estado de avance", "Estado del mínimo"))
  }
  rownames(df) <- NULL
  df
}

.monitoreo_publication_accreditation_section_table <- function(title, df, audience = "client", purpose = "") {
  .monitoreo_sheets_section_table(
    title,
    .monitoreo_publication_accreditation_present_df(df, audience = audience, purpose = purpose)
  )
}

.monitoreo_publication_accreditation_block_rows <- function(title, df, audience = "client", purpose = "") {
  df <- .monitoreo_workbook_df(df)
  if (!nrow(df) || !"Bloque" %in% names(df)) {
    return(.monitoreo_publication_accreditation_section_table(title, df, audience, purpose))
  }
  blocks <- unique(trimws(as.character(df$Bloque %||% "")))
  blocks <- blocks[nzchar(blocks)]
  if (!length(blocks)) return(.monitoreo_publication_accreditation_section_table(title, df, audience, purpose))
  rows <- list()
  for (block in blocks) {
    part <- .monitoreo_publication_block_df(df, block)
    rows <- c(rows, .monitoreo_publication_accreditation_section_table(block, part, audience, purpose))
  }
  rows
}

.monitoreo_publication_accreditation_sources_rows <- function(df, audience = "client") {
  df <- .monitoreo_workbook_df(df)
  audience <- .monitoreo_workbook_audience(audience)
  if (!nrow(df)) {
    return(.monitoreo_publication_accreditation_section_table("Corte y fuentes", df, audience, "fuentes_actualizacion"))
  }
  has_text <- function(col) {
    if (!col %in% names(df)) return(rep(FALSE, nrow(df)))
    values <- trimws(as.character(df[[col]]))
    values[is.na(values)] <- ""
    nzchar(values)
  }
  tipo <- if ("Tipo" %in% names(df)) trimws(as.character(df$Tipo)) else rep("", nrow(df))
  tipo[is.na(tipo)] <- ""
  source_like <- tipo %in% c("Fuente", "Corte") | has_text("Fuente de datos") | has_text("Registros procesados")
  channel_like <- has_text("Actor") | has_text("Canal")
  field_like <- !source_like & !channel_like
  rows <- list()
  sources <- df[source_like, , drop = FALSE]
  if (nrow(sources)) {
    sources <- sources[, intersect(c(
      "Tipo", "Fuente de datos", "Rol", "Conector", "Fecha/hora de publicación",
      "Última actualización", "Registros procesados", "Registros excluidos"
    ), names(sources)), drop = FALSE]
    rows <- c(rows, .monitoreo_publication_accreditation_section_table("Fuentes del corte", sources, audience, "fuentes_actualizacion"))
  }
  if (identical(audience, "internal")) {
    fields <- df[field_like, , drop = FALSE]
    if (nrow(fields)) {
      fields <- fields[, intersect(c(
        "Seccion", "Sección", "Concepto", "Campo", "Campo detectado",
        "Etiqueta publicación", "Origen", "Estado", "Familia de monitoreo",
        "Audiencia", "Sección UI / componente", "Dato o cálculo existente",
        "Sección publicada", "Campos faltantes tolerados"
      ), names(fields)), drop = FALSE]
      rows <- c(rows, .monitoreo_publication_accreditation_section_table("Campos usados para el corte", fields, audience, "fuentes_actualizacion"))
    }
  }
  if (!length(rows)) {
    rows <- .monitoreo_publication_accreditation_section_table("Corte y fuentes", df, audience, "fuentes_actualizacion")
  }
  rows
}

.monitoreo_publication_accreditation_sheet_rows <- function(model, key) {
  audience <- .monitoreo_workbook_audience(model$audience %||% "client")
  family_key <- .monitoreo_publication_family_key(model$family %||% "")
  tabs <- .monitoreo_publication_sheet_tab_names(model$family, audience)
  tab_title <- unname(tabs[[key]] %||% key)
  section_df <- .monitoreo_publication_section_frame(model, key)
  frame <- function(section_key) .monitoreo_publication_section_frame(model, section_key)
  table <- function(title, df, purpose = key) {
    .monitoreo_publication_accreditation_section_table(title, df, audience, purpose)
  }
  is_empty_state <- function(df) {
    df <- .monitoreo_workbook_df(df)
    !nrow(df) ||
      (identical(names(df), "Estado") && nrow(df) <= 1L)
  }
  structured_empty <- function(kind, message) {
    message <- .monitoreo_scalar(message, "Sin datos para este corte.")
    if (identical(kind, "control")) {
      return(data.frame(
        Actor = "Todos",
        `Brecha mínimo` = "",
        Estado = message,
        Detalle = "No hay seguimiento operativo adicional para este corte.",
        Origen = "Motor canónico",
        check.names = FALSE,
        stringsAsFactors = FALSE
      ))
    }
    if (identical(kind, "phone")) {
      return(data.frame(
        Actor = "Todos",
        Responsable = "",
        Estatus = "Sin monitoreo",
        `Rechazos telefónicos` = 0L,
        Estado = message,
        Detalle = "Sin estados telefónicos operativos para este corte.",
        check.names = FALSE,
        stringsAsFactors = FALSE
      ))
    }
    if (identical(kind, "channel")) {
      return(data.frame(
        Actor = "Todos",
        `Canal operativo` = "Sin canal registrado",
        `Título / fuente` = "Sin fuente de respuestas para este corte",
        `Responsable de carga` = "Sin dato",
        `Tipo de responsable` = "Sin dato",
        Completas = 0L,
        Parciales = 0L,
        Rechazos = 0L,
        `Sin respuesta` = 0L,
        `Respuestas registradas` = 0L,
        Estado = "Sin avance por canal/fuente para este corte.",
        check.names = FALSE,
        stringsAsFactors = FALSE
      ))
    }
    if (identical(kind, "case")) {
      return(data.frame(
        Nivel = "Sin casos",
        Caso = "",
        Detalle = message,
        Origen = "Motor canónico",
        Estado = "Sin casos accionables",
        check.names = FALSE,
        stringsAsFactors = FALSE
      ))
    }
    if (identical(kind, "alert")) {
      return(data.frame(
        Nivel = "Sin alertas",
        Motivo = message,
        Detalle = message,
        Origen = "Motor canónico",
        Estado = "Sin alertas",
        check.names = FALSE,
        stringsAsFactors = FALSE
      ))
    }
    .monitoreo_publication_empty_df(message)
  }
  daily_tables <- function(daily) {
    daily <- .monitoreo_workbook_df(daily)
    if (nrow(daily) && "Bloque" %in% names(daily)) {
      general <- daily[as.character(daily$Bloque) == "General", setdiff(names(daily), "Bloque"), drop = FALSE]
      by_actor <- daily[as.character(daily$Bloque) == "Por actor", setdiff(names(daily), "Bloque"), drop = FALSE]
      return(c(
        table("Ritmo general", general, "avance_diario"),
        table("Ritmo por actor", by_actor, "avance_diario")
      ))
    }
    table("Ritmo diario", daily, "avance_diario")
  }
  if (identical(key, "portada")) {
    if (identical(audience, "client") && identical(family_key, "telefonico")) {
      return(c(
        table("Datos del corte", section_df, "portada"),
        table("Seguimiento telefónico", frame("monitoreo_telefonico"), "monitoreo_telefonico"),
        table("Puntos de atención", frame("alertas_internas"), "alertas_internas")
      ))
    }
    if (identical(audience, "client")) {
      cards <- .monitoreo_publication_accreditation_present_df(frame("resumen_ejecutivo"), audience, "summary")
      return(c(
        table("Datos del corte", section_df, "portada"),
        .monitoreo_sheets_card_rows("Indicadores del corte", cards),
        table("Avance por actor", frame("avance_por_actor"), "avance_por_actor"),
        table("Avance por canal", frame("avance_por_canal_fuente"), "avance_por_canal_fuente"),
        table("Pendientes por cubrir", frame("cobertura_pendientes"), "cobertura_pendientes")
      ))
    }
    return(table("Resumen del corte", section_df, "portada"))
  }
  if (identical(key, "resumen_ejecutivo")) {
    cards <- .monitoreo_publication_accreditation_present_df(section_df, audience, "summary")
    return(c(
      .monitoreo_sheets_card_rows("Indicadores del corte", cards),
      table("Avance por actor", frame("avance_por_actor"), "avance_por_actor"),
      table("Pendientes por cubrir", frame("cobertura_pendientes"), "cobertura_pendientes")
    ))
  }
  if (identical(key, "resumen_operativo")) {
    cards <- .monitoreo_publication_accreditation_present_df(section_df, audience, "summary")
    return(c(
      table("Datos del corte", frame("portada"), "portada"),
      .monitoreo_sheets_card_rows("Indicadores del corte", cards),
      table("Vista general", frame("avance_general"), "avance_general"),
      table("Avance por actor", frame("avance_por_actor"), "avance_por_actor"),
      table("Mínimos por actor", frame("metas_internas_actor"), "metas_internas_actor"),
      table("Faltantes por actor", frame("pendientes_por_actor"), "pendientes_por_actor")
    ))
  }
  if (identical(key, "produccion_responsable")) {
    return(.monitoreo_publication_accreditation_block_rows("Producción por responsable", section_df, audience, "produccion_responsable"))
  }
  if (identical(key, "avance_diario")) {
    rows <- daily_tables(section_df)
    if (identical(audience, "client")) {
      return(c(
        rows,
        table("Avance por segmento", frame("avance_por_segmento"), "avance_por_segmento")
      ))
    }
    return(rows)
  }
  if (identical(key, "cobertura_pendientes")) {
    coverage <- .monitoreo_workbook_df(section_df)
    if (nrow(coverage) && "Tipo" %in% names(coverage)) {
      actors <- coverage[as.character(coverage$Tipo) == "Actor", setdiff(names(coverage), "Tipo"), drop = FALSE]
      segments <- coverage[as.character(coverage$Tipo) == "Segmento", setdiff(names(coverage), "Tipo"), drop = FALSE]
      return(c(
        table("Pendientes por actor", actors, "cobertura_pendientes"),
        table("Pendientes por segmento", segments, "cobertura_pendientes")
      ))
    }
    return(table("Pendientes por cubrir", coverage, "cobertura_pendientes"))
  }
  if (identical(key, "control_seguimiento")) {
    tracking <- section_df
    if (is_empty_state(tracking)) {
      tracking <- structured_empty("control", "Sin control de seguimiento interno para este corte.")
    }
    phone <- frame("monitoreo_telefonico")
    if (is_empty_state(phone)) {
      phone <- structured_empty("phone", "Sin monitoreo telefónico para este corte.")
    }
    cases <- frame("casos_accionables")
    if (is_empty_state(cases)) {
      cases <- structured_empty("case", "Sin casos accionables internos.")
    }
    return(c(
      table("Seguimiento operativo", tracking, "control_seguimiento"),
      table("Seguimiento telefónico", phone, "monitoreo_telefonico"),
      table("Casos para revisar", cases, "casos_accionables")
    ))
  }
  if (identical(key, "avance_por_canal_recopilador")) {
    channel <- section_df
    if (is_empty_state(channel)) {
      channel <- structured_empty("channel", "Sin avance por canal/fuente para este corte.")
    }
    return(c(
      daily_tables(frame("avance_diario")),
      table("Avance por canal y responsable", channel, "avance_por_canal_recopilador"),
      table("Avance por segmento", frame("avance_por_segmento"), "avance_por_segmento")
    ))
  }
  if (identical(key, "fuentes_actualizacion")) {
    return(.monitoreo_publication_accreditation_sources_rows(section_df, audience))
  }
  if (identical(key, "auditoria_tecnica")) {
    return(.monitoreo_publication_accreditation_block_rows("Trazabilidad del corte", section_df, audience, "auditoria_tecnica"))
  }
  if (identical(key, "base_tecnica")) {
    return(table("Registros del corte", section_df, "base_tecnica"))
  }
  if (identical(key, "alertas_internas") && is_empty_state(section_df)) {
    section_df <- structured_empty("alert", "Sin alertas internas determinísticas para este corte.")
  }
  section_titles <- c(
    avance_general = "Vista general",
    avance_por_actor = "Avance por actor",
    avance_por_segmento = "Avance por segmento",
    avance_por_canal_fuente = "Avance por canal",
    avance_por_canal_recopilador = "Canal y responsable",
    produccion_responsable = "Producción por responsable",
    metas_internas_actor = "Mínimos por actor",
    pendientes_por_actor = "Faltantes por actor",
    monitoreo_telefonico = "Seguimiento telefónico",
    alertas_internas = "Puntos de atención",
    casos_accionables = "Casos para revisar"
  )
  table(unname(section_titles[[key]] %||% tab_title), section_df, key)
}

.monitoreo_publication_rows_df <- function(rows) {
  .monitoreo_workbook_df(rows %||% list())
}

.monitoreo_publication_route_summary_df <- function(routes) {
  routes <- .monitoreo_workbook_df(routes)
  if (!nrow(routes) || !"Tipo" %in% names(routes)) return(.monitoreo_publication_empty_df("Sin relación UMP/manzanas para resumir."))
  tipo_raw <- as.character(routes$tipo_manzana %||% routes$Tipo %||% "")
  tipo_label <- as.character(routes$Tipo %||% "")
  is_titular <- .monitoreo_text_key(tipo_raw) != "reemplazo" & !grepl("^Reemplazo", tipo_label)
  is_replacement <- !is_titular
  replacement_state <- as.character(routes$`Estado reemplazo` %||% "")
  replacement_used <- is_replacement & (
    grepl("usado", replacement_state, ignore.case = TRUE) |
      suppressWarnings(as.numeric(routes$`Válidas observadas` %||% 0)) > 0
  )
  validas <- suppressWarnings(as.numeric(routes$`Válidas observadas` %||% 0))
  responsible <- trimws(as.character(routes$Responsable %||% ""))
  status <- as.character(routes$`Estado UMP` %||% "")
  group_key <- trimws(as.character(routes$`UMP titular` %||% routes$`UMP base` %||% routes$UMP %||% ""))
  group_key <- rep_len(group_key, nrow(routes))
  missing_group <- is.na(group_key) | !nzchar(group_key)
  if (any(missing_group)) {
    fallback_group <- rep_len(trimws(as.character(routes$UMP %||% "")), nrow(routes))
    group_key[missing_group] <- fallback_group[missing_group]
  }
  missing_group <- is.na(group_key) | !nzchar(group_key)
  if (any(missing_group)) {
    generated_group <- paste0("sin_ump_", seq_len(nrow(routes)))
    group_key[missing_group] <- generated_group[missing_group]
  }
  groups <- unique(group_key)
  group_complete <- vapply(groups, function(key) {
    idx <- group_key == key
    any(status[idx] %in% c("Completa", "Excedida"), na.rm = TRUE)
  }, logical(1))
  group_in_field <- vapply(groups, function(key) {
    idx <- group_key == key
    if (isTRUE(group_complete[groups == key])) return(FALSE)
    activity <- trimws(as.character(routes$`Última actividad`[idx] %||% ""))
    activity_state <- vapply(activity, .monitoreo_publication_activity_status_label, character(1))
    any(status[idx] %in% c("En campo") & activity_state == "today", na.rm = TRUE)
  }, logical(1))
  group_pending <- vapply(groups, function(key) {
    idx <- group_key == key
    if (isTRUE(group_complete[groups == key]) || isTRUE(group_in_field[groups == key])) return(FALSE)
    activity <- trimws(as.character(routes$`Última actividad`[idx] %||% ""))
    activity_state <- vapply(activity, .monitoreo_publication_activity_status_label, character(1))
    any(
      status[idx] %in% c("Cuota pendiente", "Falta cuota", "Sin cuota", "No configurada", "Sin información suficiente") |
        (status[idx] %in% c("En campo") & activity_state != "today") |
        activity_state == "previous" |
        validas[idx] > 0,
      na.rm = TRUE
    )
  }, logical(1))
  group_no_start <- vapply(groups, function(key) {
    idx <- group_key == key
    !group_complete[groups == key] && !group_in_field[groups == key] && !group_pending[groups == key] &&
      !any(validas[idx] > 0, na.rm = TRUE)
  }, logical(1))
  data.frame(
    Indicador = c(
      "Meta UMP", "Reemplazos disponibles", "Reemplazos usados",
      "Responsables",
      "UMP efectivas", "UMP en campo", "UMP pendientes", "UMP no iniciadas"
    ),
    Valor = c(
      length(groups),
      sum(is_replacement, na.rm = TRUE),
      sum(replacement_used, na.rm = TRUE),
      length(unique(responsible[nzchar(responsible) & responsible != "Sin responsable"])),
      sum(group_complete, na.rm = TRUE),
      sum(group_in_field, na.rm = TRUE),
      sum(group_pending, na.rm = TRUE),
      sum(group_no_start, na.rm = TRUE)
    ),
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
}

.monitoreo_publication_route_summary_cards_df <- function(model, routes) {
  route_summary <- .monitoreo_publication_route_summary_df(routes)
  resumen <- .monitoreo_publication_section_frame(model, "resumen_operativo")
  quick <- .monitoreo_publication_block_df(resumen, "Lectura rápida de avance")
  if (!nrow(quick) || !"Indicador" %in% names(quick) || !"n" %in% names(quick)) return(route_summary)

  route_value <- function(label) {
    idx <- which(route_summary$Indicador == label)
    if (length(idx)) route_summary$Valor[[idx[[1]]]] else ""
  }
  quick_row <- function(label) {
    idx <- which(quick$Indicador == label)
    if (length(idx)) quick[idx[[1]], , drop = FALSE] else data.frame()
  }
  quick_value <- function(label, col = "n", fallback = "") {
    row <- quick_row(label)
    if (nrow(row) && col %in% names(row)) row[[col]][[1]] else fallback
  }

  labels <- c(
    "Meta UMP", "Reemplazos disponibles", "Reemplazos usados",
    "Responsables", "UMP efectivas", "UMP en campo", "UMP pendientes", "UMP no iniciadas"
  )
  data.frame(
    Indicador = labels,
    n = c(
      quick_value("Meta UMP", fallback = route_value("Meta UMP")),
      route_value("Reemplazos disponibles"),
      quick_value("Reemplazos usados", fallback = route_value("Reemplazos usados")),
      route_value("Responsables"),
      quick_value("UMP efectivas", fallback = route_value("UMP efectivas")),
      quick_value("UMP en campo", fallback = route_value("UMP en campo")),
      quick_value("UMP pendientes", fallback = route_value("UMP pendientes")),
      quick_value("UMP no iniciadas", fallback = route_value("UMP no iniciadas"))
    ),
    `%` = c(
      quick_value("Meta UMP", "%"),
      "",
      "",
      "",
      quick_value("UMP efectivas", "%"),
      quick_value("UMP en campo", "%"),
      quick_value("UMP pendientes", "%"),
      quick_value("UMP no iniciadas", "%")
    ),
    Estado = c(
      quick_value("Meta UMP", "Estado"),
      "Referencia",
      quick_value("Reemplazos usados", "Estado"),
      "Equipo",
      quick_value("UMP efectivas", "Estado"),
      quick_value("UMP en campo", "Estado"),
      quick_value("UMP pendientes", "Estado"),
      quick_value("UMP no iniciadas", "Estado")
    ),
    Lectura = c(
      quick_value("Meta UMP", "Lectura"),
      "Reemplazos disponibles en la muestra.",
      quick_value("Reemplazos usados", "Lectura"),
      "Responsables con UMP asignadas u observadas.",
      quick_value("UMP efectivas", "Lectura"),
      quick_value("UMP en campo", "Lectura"),
      quick_value("UMP pendientes", "Lectura"),
      quick_value("UMP no iniciadas", "Lectura")
    ),
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
}

.monitoreo_publication_territorial_internal_sheet_rows <- function(model, key) {
  section_df <- .monitoreo_publication_section_frame(model, key)
  routes <- .monitoreo_publication_section_frame(model, "encuestadores_rutas")
  responsible <- .monitoreo_publication_section_frame(model, "responsables_rutas")
  quota <- .monitoreo_publication_section_frame(model, "cuotas_ump")
  if (identical(key, "resumen_operativo")) {
    quick <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Lectura rápida de avance"),
      c("Indicador", "n", "%", "Estado", "Lectura")
    )
    cards <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Tarjetas ejecutivas"),
      c("Indicador", "n", "%", "Estado", "Lectura", "Corte publicado")
    )
    general <- .monitoreo_publication_block_df(section_df, "Estado general")
    quota_status <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Estado de UMP operativas"),
      c("Estado cuota", "Cantidad", "%")
    )
    district <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Avance por distrito"),
      c(
        "Distrito", "Encuestas válidas", "Meta encuestas", "% avance encuestas",
        "Brecha encuestas", "Meta UMP", "UMP efectivas", "% UMP efectivas",
        "UMP subsanadas", "UMP en campo", "% UMP en campo", "UMP pendientes", "% UMP pendientes",
        "UMP no iniciadas", "% UMP no iniciadas", "Reemplazos usados",
        "Efectivas poblacionales", "Referencia poblacional", "% avance poblacional",
        "Pendientes poblacionales", "UMP titulares", "UMP completas", "% UMP completas",
        "UMP falta cuota", "% UMP falta cuota"
      )
    )
    production <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Producción por encuestador"),
      c(
        "Responsable", "Código encuestador", "Distritos", "Meta UMP",
        "UMP efectivas", "UMP subsanadas", "% UMP efectivas",
        "UMP en campo", "UMP pendientes", "UMP no iniciadas", "Reemplazos usados",
        "Encuestas válidas", "Meta encuestas", "% avance encuestas",
        "UMP asignadas", "UMP completas cumpliendo cuota", "% UMP completas",
        "UMP falta cuota", "Efectivas poblacionales", "Referencia poblacional", "% avance poblacional",
        "Última actividad"
      )
    )
    return(c(
      .monitoreo_sheets_card_rows("Lectura rápida de avance", quick),
      .monitoreo_sheets_card_rows("Tarjetas ejecutivas", cards),
      .monitoreo_sheets_section_table("Estado general", general),
      .monitoreo_sheets_section_table("Estado de UMP operativas", quota_status),
      .monitoreo_sheets_section_table("Avance por distrito", district),
      .monitoreo_sheets_section_table("Producción por encuestador", production)
    ))
  }
  if (identical(key, "produccion_responsable")) {
    ranking <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Ranking por responsable"),
      c(
        "Responsable", "Código encuestador", "Distritos", "Meta UMP",
        "UMP efectivas", "UMP subsanadas", "% UMP efectivas",
        "UMP en campo", "UMP pendientes", "UMP no iniciadas", "Reemplazos usados",
        "Encuestas válidas", "Meta encuestas", "% avance encuestas", "Última actividad"
      )
    )
    detail <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "UMP completadas por responsable"),
      c(
        "Responsable", "Distrito", "UMP", "Manzana", "Estado operativo",
        "Tipo que completa", "Encuestas válidas", "Meta encuestas",
        "Reemplazos usados", "Última actividad"
      )
    )
    return(c(
      .monitoreo_sheets_section_table("Ranking por responsable", ranking),
      .monitoreo_sheets_section_table("UMP completadas por responsable", detail)
    ))
  }
  if (identical(key, "avance_campo")) {
    progress <- model$daily_progress %||% list()
    by_ump <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Avance por UMP/manzana"),
      c(
        "Distrito", "Zona", "UMP", "Manzana", "Tipo", "Reemplazo", "Uso reemplazo", "Reemplaza a",
        "Responsable", "Responsable real", "UMP titular",
        "Meta", "Total", "Efectivas", "% avance", "Brecha", "Estado", "Última actividad",
        "tipo_manzana", "reemplazo", "titular_id_manzana", "replacement_order"
      )
    )
    by_ump <- .monitoreo_publication_drop_operational_technical_cols(by_ump)
    return(c(
      .monitoreo_sheets_section_table("UMP finalizadas por día", .monitoreo_publication_daily_completion_matrix(progress)),
      .monitoreo_sheets_section_table("UMP finalizadas por distrito", .monitoreo_publication_daily_unit_completion_matrix(
        progress,
        key = "by_date_district",
        row_col = "Distrito",
        first_label = "Distrito / Fecha",
        empty_message = "Sin UMP finalizadas por distrito para este corte."
      )),
      .monitoreo_sheets_section_table("UMP finalizadas por encuestador", .monitoreo_publication_daily_unit_completion_matrix(
        progress,
        key = "by_date_responsible",
        row_col = "Encuestador",
        first_label = "Encuestador / Fecha",
        empty_message = "Sin UMP finalizadas por encuestador para este corte."
      )),
      .monitoreo_sheets_section_table("Avance por UMP/manzana", by_ump)
    ))
  }
  if (identical(key, "encuestadores_rutas")) {
    routes_display <- .monitoreo_publication_cols_first(
      routes,
      c(
        "Distrito", "Zona", "UMP", "Manzana", "Tipo", "Reemplazo", "Reemplaza a",
        "Responsable", "Código encuestador", "Estado UMP",
        "Válidas observadas", "Última actividad", "UMP titular", "Manzana de referencia",
        "Estado reemplazo", "Reemplazo asociado", "Rango", "Viviendas", "Población",
        "tipo_manzana", "reemplazo", "titular_id_manzana", "replacement_order"
      )
    )
    routes_display <- .monitoreo_publication_drop_operational_technical_cols(routes_display)
    return(c(
      .monitoreo_sheets_card_rows("Resumen UMP y responsables", .monitoreo_publication_route_summary_cards_df(model, routes)),
      .monitoreo_sheets_section_table("Relación UMP · manzanas de referencia · responsables", routes_display)
    ))
  }
  if (identical(key, "responsables_rutas")) {
    observed <- .monitoreo_publication_block_df(responsible, "Responsables observados por registros")
    planned <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(responsible, "Asignación planificada"),
      c(
        "Distrito", "Zona", "UMP", "Manzana de referencia", "Tipo", "Reemplazo", "Reemplaza a",
        "Responsable asignado", "Código asignado", "UMP titular",
        "Reemplazos disponibles", "Reemplazos usados", "Reemplazos", "Rango",
        "Encuestas válidas", "Encuestas faltantes",
        "Estado UMP", "Última actividad",
        paste("Encuesta", seq_len(15L)),
        "tipo_manzana", "reemplazo", "titular_id_manzana", "replacement_order"
      )
    )
    planned <- .monitoreo_publication_drop_operational_technical_cols(planned)
    return(c(
      .monitoreo_sheets_section_table("Responsables observados por registros", observed),
      .monitoreo_sheets_section_table("Asignación planificada", planned)
    ))
  }
  if (identical(key, "cuotas_ump")) {
    quota_summary <- .monitoreo_publication_block_df(quota, "Resumen de cuotas UMP")
    quota_detail <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(quota, "Cumplimiento por UMP"),
      c(
	        "Distrito", "Zona", "UMP", "Manzana", "Tipo", "Reemplazo", "Uso reemplazo", "Reemplaza a",
	        "Responsable", "Responsable real", "Efectivas (n)", "Avance (%)", "Estado cuota",
	        "UMP titular", "tipo_manzana", "reemplazo",
	        "titular_id_manzana", "replacement_order", "Último ingreso"
	      )
    )
    quota_detail <- .monitoreo_publication_drop_operational_technical_cols(quota_detail)
    expected <- .monitoreo_publication_block_df(quota, "Matriz esperada sexo/edad")
    detail <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(quota, "Faltantes por categoría"),
      c("Distrito", "UMP", "UMP titular", "Manzana ref.", "Tipo", "Reemplazo", "Uso reemplazo", "Reemplaza a", "Responsable", "Sexo", "Grupo edad", "Esperado", "Observado", "Faltante", "Estado")
    )
    return(c(
      .monitoreo_sheets_section_table("Resumen de cuotas UMP", quota_summary),
      .monitoreo_sheets_section_table("Cumplimiento por UMP", quota_detail),
      .monitoreo_sheets_section_table("Matriz esperada sexo/edad", expected),
      .monitoreo_sheets_section_table("Faltantes por categoría", detail)
    ))
  }
  if (identical(key, "ocurrencias_campo")) {
    summary <- .monitoreo_publication_block_df(section_df, "Resumen de ocurrencias")
    ranking <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Ranking por categoría"),
      c("Ranking", "Categoría", "Reportes", "Participación (%)", "Lectura")
    )
    daily <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Ritmo diario de ocurrencias"),
      c("Indicador / Fecha")
    )
    daily_category <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Qué se reporta cada día"),
      c("Categoría / Fecha")
    )
    daily_district <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Reportes por distrito y día"),
      c("Distrito / Fecha")
    )
    by_ump <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Estado por UMP"),
      c(
        "Distrito", "UMP", "Manzana", "Tipo", "Reemplazo", "Reemplaza a",
        "Responsable", "UMP titular", "Estado", "Motivo principal", "Reportes",
        "Efectivas", "No efectivas", "Intentos", "Tasa no efectiva", "Último reporte",
        "tipo_manzana", "reemplazo", "titular_id_manzana", "replacement_order"
      )
    )
    by_ump <- .monitoreo_publication_drop_operational_technical_cols(by_ump)
    district <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Resumen por distrito"),
      c("Distrito", "Reportes", "UMP reportadas", "UMP sin reporte", "Efectivas", "No efectivas", "Intentos", "Tasa no efectiva", "Motivo predominante")
    )
    review <- .monitoreo_publication_cols_first(
      .monitoreo_publication_block_df(section_df, "Observaciones por revisar"),
      c("Fecha", "Distrito", "UMP", "Responsable", "Tipo de ocurrencia", "Descripción", "Estado")
    )
    return(c(
      .monitoreo_sheets_card_rows("Resumen de ocurrencias", summary),
      .monitoreo_sheets_section_table("Ranking por categoría", ranking),
      .monitoreo_sheets_section_table("Ritmo diario de ocurrencias", daily),
      .monitoreo_sheets_section_table("Qué se reporta cada día", daily_category),
      .monitoreo_sheets_section_table("Reportes por distrito y día", daily_district),
      .monitoreo_sheets_section_table("Resumen por distrito", district),
      .monitoreo_sheets_section_table("Observaciones por revisar", review),
      .monitoreo_sheets_section_table("Estado por UMP", by_ump)
    ))
  }
  .monitoreo_publication_sheet_rows(model[[key]]$title %||% key, section_df)
}

monitoreo_publication_sheets_tabs <- function(data, config = list(), audience = "client", include_targets = FALSE, dashboard = NULL, synced_at = "", context = list()) {
  model <- monitoreo_publication_model(
    data,
    config,
    audience = audience,
    include_targets = include_targets,
    dashboard = dashboard,
    synced_at = synced_at,
    context = context
  )
  tab_names <- .monitoreo_publication_sheet_tab_names(model$family, model$audience)
  out <- list()
  for (key in names(tab_names)) {
    tab_name <- unname(tab_names[[key]])
    family_key <- .monitoreo_publication_family_key(model$family)
    audience_key <- .monitoreo_workbook_audience(model$audience)
    if (family_key %in% c("acreditacion", "telefonico")) {
      out[[tab_name]] <- .monitoreo_publication_accreditation_sheet_rows(model, key)
    } else if (identical(family_key, "territorial") && identical(audience_key, "internal")) {
      out[[tab_name]] <- .monitoreo_publication_territorial_internal_sheet_rows(model, key)
    } else {
      out[[tab_name]] <- .monitoreo_publication_sheet_rows(tab_name, .monitoreo_publication_section_frame(model, key))
    }
  }
  attr(out, "publication_model") <- model
  attr(out, "sheets_model") <- .monitoreo_publication_sheets_model(model)
  out
}

.monitoreo_publication_workbook_styles <- function(audience = "client") {
  audience <- .monitoreo_workbook_audience(audience)
  list(
    title = openxlsx::createStyle(fontSize = 15, textDecoration = "bold", fontColour = "#17212F"),
    meta = openxlsx::createStyle(fontSize = 9, fontColour = "#5F6B7A"),
    section = openxlsx::createStyle(textDecoration = "bold", fgFill = if (identical(audience, "internal")) "#4B5563" else "#0F355E", fontColour = "#FFFFFF", halign = "left"),
    header = openxlsx::createStyle(textDecoration = "bold", fgFill = if (identical(audience, "internal")) "#FEE2E2" else "#E8F0FE", border = "Bottom", halign = "left"),
    body = openxlsx::createStyle(border = "Bottom", borderColour = "#E2E7F0", valign = "top", wrapText = TRUE),
    card = openxlsx::createStyle(fgFill = "#F8FAFC", border = "TopBottomLeftRight", borderColour = "#CBD5E1", valign = "top", wrapText = TRUE),
    percent = openxlsx::createStyle(numFmt = "0.0%"),
    severity_high = openxlsx::createStyle(fgFill = "#FEE2E2", border = "Bottom", borderColour = "#E2E7F0", valign = "top", wrapText = TRUE),
    severity_warn = openxlsx::createStyle(fgFill = "#FEF3C7", border = "Bottom", borderColour = "#E2E7F0", valign = "top", wrapText = TRUE),
    severity_ok = openxlsx::createStyle(fgFill = "#DCFCE7", border = "Bottom", borderColour = "#E2E7F0", valign = "top", wrapText = TRUE)
  )
}

.monitoreo_publication_write_workbook_sheets <- function(sheets, path, audience = "client", use_sheet_rows = TRUE) {
  if (!requireNamespace("openxlsx", quietly = TRUE)) {
    stop("El paquete R 'openxlsx' no esta instalado.", call. = FALSE)
  }
  audience <- .monitoreo_workbook_audience(audience)
  wb <- openxlsx::createWorkbook()
  styles <- .monitoreo_publication_workbook_styles(audience)
  for (nm in names(sheets)) {
    if (isTRUE(use_sheet_rows)) {
      .monitoreo_publication_add_rows_sheet(wb, nm, sheets[[nm]], styles)
    } else {
      .monitoreo_publication_add_sheet(wb, nm, sheets[[nm]], styles)
    }
  }
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  openxlsx::saveWorkbook(wb, path, overwrite = TRUE)
  .monitoreo_xlsx_prune_missing_parts(path)
  invisible(path)
}

monitoreo_publication_workbook_from_tabs <- function(tabs, path, audience = "client") {
  .monitoreo_publication_write_workbook_sheets(
    tabs %||% list(),
    path = path,
    audience = audience,
    use_sheet_rows = TRUE
  )
}

monitoreo_publication_workbook <- function(data, config = list(), path, audience = "client", include_targets = FALSE, context = list(), dashboard = NULL, synced_at = "", sheets = NULL) {
  if (!requireNamespace("openxlsx", quietly = TRUE)) {
    stop("El paquete R 'openxlsx' no esta instalado.", call. = FALSE)
  }
  audience <- .monitoreo_workbook_audience(audience)
  family <- .monitoreo_publication_family_key(detect_monitoreo_family(config = config, data = data))
  use_sheet_rows <- family %in% c("acreditacion", "telefonico") ||
    (identical(family, "territorial") && identical(audience, "internal"))
  sheets <- if (!is.null(sheets)) {
    use_sheet_rows <- TRUE
    sheets
  } else if (isTRUE(use_sheet_rows)) {
    monitoreo_publication_sheets_tabs(
      data,
      config,
      audience = audience,
      include_targets = include_targets,
      dashboard = dashboard,
      synced_at = synced_at,
      context = context
    )
  } else {
    .monitoreo_publication_workbook_frames(data, config, audience, include_targets = include_targets, context = context, dashboard = dashboard, synced_at = synced_at)
  }
  .monitoreo_publication_write_workbook_sheets(sheets, path, audience = audience, use_sheet_rows = use_sheet_rows)
}

render_client_sheets_workbook <- function(data, config = list(), path, include_targets = FALSE, context = list(), dashboard = NULL, synced_at = "") {
  monitoreo_publication_workbook(
    data,
    config,
    path = path,
    audience = "client",
    include_targets = include_targets,
    context = context,
    dashboard = dashboard,
    synced_at = synced_at
  )
}

render_internal_sheets_workbook <- function(data, config = list(), path, include_targets = FALSE, context = list(), dashboard = NULL, synced_at = "") {
  monitoreo_publication_workbook(
    data,
    config,
    path = path,
    audience = "internal",
    include_targets = include_targets,
    context = context,
    dashboard = dashboard,
    synced_at = synced_at
  )
}

.monitoreo_publish_qa_dates <- function() {
  as.character(as.Date("2026-06-10") + 0:6)
}

.monitoreo_publish_qa_rec <- function(df) {
  .monitoreo_df_records(.monitoreo_workbook_df(df))
}

.monitoreo_publish_qa_territorial_fixture <- function() {
  quota <- data.frame(
    distrito = c("San Juan de Lurigancho", "San Juan de Lurigancho", "San Martín de Porres", "San Martín de Porres", "Chorrillos", "Chorrillos"),
    zona = c("ZN-01", "ZN-01", "ZC-02", "ZC-02", "ZS-03", "ZS-03"),
    ump = c("UMP-101", "UMP-102", "UMP-201", "UMP-202", "UMP-301", "UMP-302"),
    manzana = c("MZ-01", "MZ-02", "MZ-11", "MZ-12", "MZ-21", "MZ-22"),
    tipo_manzana = c("titular", "reemplazo", "titular", "reemplazo", "titular", "reemplazo"),
    titular_hoja_num = c("UMP-101", "UMP-101", "UMP-201", "UMP-201", "UMP-301", "UMP-301"),
    titular_manzana = c("MZ-01", "MZ-01", "MZ-11", "MZ-11", "MZ-21", "MZ-21"),
    responsable = c("Ana Rojas", "Ana Rojas", "Bruno Vega", "Bruno Vega", "Carla Nuñez", "Carla Nuñez"),
    pulso_code = c("ENC-100", "ENC-100", "ENC-210", "ENC-210", "ENC-330", "ENC-330"),
    rango_inicio = c(1L, 7L, 1L, 6L, 1L, 7L),
    rango_fin = c(6L, 11L, 5L, 9L, 6L, 11L),
    viviendas = c(82L, 74L, 69L, 63L, 88L, 71L),
    poblacion = c(246L, 221L, 204L, 188L, 264L, 213L),
    target = c(6L, 5L, 5L, 4L, 6L, 5L),
    validas = c(6L, 3L, 7L, 0L, 4L, 2L),
    partial = c(1L, 1L, 0L, 1L, 1L, 0L),
    rechazo = c(1L, 0L, 1L, 1L, 1L, 1L),
    pendiente = c(0L, 1L, 0L, 2L, 0L, 2L),
    stringsAsFactors = FALSE
  )
  dates <- .monitoreo_publish_qa_dates()
  duration_values <- c(45, 180, 900, 3600, NA, 720, 1200)
  duration_status <- c("muy_corta", "corta", "esperada", "larga", "sin_duracion", "esperada", "esperada")
  gps_status <- c("geo_ok", "geo_revision", "geo_sin_gps", "geo_no_defendible", "geo_ok", "geo_cerca", "geo_ok")
  rows <- list()
  case_id <- 1L
  add_case <- function(block, status, valid) {
    day <- dates[((case_id - 1L) %% length(dates)) + 1L]
    duration <- duration_values[((case_id - 1L) %% length(duration_values)) + 1L]
    duration_status_value <- duration_status[((case_id - 1L) %% length(duration_status)) + 1L]
    duration_has_time <- .monitoreo_territorial_duration_has_time(duration_status_value, duration)[[1]]
    duration_operational_status_value <- .monitoreo_territorial_duration_operational_status(duration_status_value, duration)
    duration_operational_label_value <- .monitoreo_territorial_duration_operational_label(duration_status_value, duration)
    if (!isTRUE(duration_has_time)) {
      duration_operational_status_value <- ""
      duration_operational_label_value <- ""
    }
    gps <- gps_status[((case_id - 1L) %% length(gps_status)) + 1L]
    lat <- if (identical(gps, "geo_sin_gps")) NA_real_ else -12.05 - (case_id %% 7L) / 100
    lon <- if (identical(gps, "geo_sin_gps")) NA_real_ else -77.01 - (case_id %% 9L) / 100
    rows[[length(rows) + 1L]] <<- data.frame(
      response_id = sprintf("TER-RAW-%04d", case_id),
      `_uuid` = sprintf("uuid-territorial-%04d", case_id),
      contact_name = paste("Contacto", sprintf("%02d", case_id)),
      contact_phone = sprintf("+51999%06d", case_id),
      distrito = block$distrito,
      advance_block_distrito = block$distrito,
      advance_block_ump = block$ump,
      advance_block_manzana = block$manzana,
      responsable = block$responsable,
      pulso_code = block$pulso_code,
      codigo_encuestador = block$pulso_code,
      `Core/E1_age` = c(22L, 34L, 51L, 65L)[((case_id - 1L) %% 4L) + 1L],
      `Core/E2_sex` = c("Hombre", "Mujer")[((case_id - 1L) %% 2L) + 1L],
      validation_status = status,
      advance_valid = valid,
      submission_date_iso = day,
      start = paste0(day, "T08:00:00-05:00"),
      end = paste0(day, "T08:", sprintf("%02d", pmin(59, max(1, round((duration %||% 0) / 60)))), ":00-05:00"),
      duration_seconds = duration,
      duration_status = duration_status_value,
      duration_operational_status = duration_operational_status_value,
      duration_operational_label = duration_operational_label_value,
      gps_inicio = if (is.na(lat)) "" else sprintf("%.6f %.6f 0 10", lat, lon),
      lat = lat,
      lon = lon,
      gps_parseable = !is.na(lat),
      geo_estado = gps,
      issues = if (!isTRUE(valid) || gps %in% c("geo_revision", "geo_no_defendible", "geo_sin_gps")) "revision_operativa" else "",
      `.source_id` = "qa_kobo_territorial_respuestas",
      `.source_role` = "respuestas",
      `.source_label` = "QA Kobo Territorial",
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
    case_id <<- case_id + 1L
  }
  for (idx in seq_len(nrow(quota))) {
    block <- as.list(quota[idx, , drop = FALSE])
    for (i in seq_len(block$validas)) add_case(block, "efectiva", TRUE)
    if (block$partial > 0L) for (i in seq_len(block$partial)) add_case(block, "parcial", FALSE)
    if (block$rechazo > 0L) for (i in seq_len(block$rechazo)) add_case(block, "rechazo", FALSE)
    if (block$pendiente > 0L) for (i in seq_len(block$pendiente)) add_case(block, "pendiente", FALSE)
  }
  data <- do.call(rbind, rows)
  rownames(data) <- NULL

  block_rows <- quota
  block_rows$total <- quota$validas + quota$partial + quota$rechazo + quota$pendiente
  block_rows$avance_pct <- round(100 * quota$validas / quota$target, 1)
  block_rows$brecha <- pmax(0L, quota$target - quota$validas)
  block_rows$status <- ifelse(quota$validas >= quota$target, "completa", ifelse(quota$validas > 0, "en_campo", "pendiente"))
  block_rows$last_record <- vapply(seq_len(nrow(block_rows)), function(i) {
    idx <- data$advance_block_ump == block_rows$ump[[i]] & data$advance_block_manzana == block_rows$manzana[[i]]
    values <- data$submission_date_iso[idx]
    values <- values[nzchar(values)]
    if (length(values)) max(values) else ""
  }, character(1))
  make_quota_buckets <- function(target, achieved) {
    sexes <- c("Hombre", "Mujer")
    ages <- c("18-29", "30-44", "45-59", "60+")
    combos <- expand.grid(sexo = sexes, edad = ages, stringsAsFactors = FALSE)
    spread_counts <- function(total) {
      total <- max(0L, as.integer(total %||% 0L))
      out <- integer(nrow(combos))
      if (total > 0L) {
        for (i in seq_len(total)) out[((i - 1L) %% length(out)) + 1L] <- out[((i - 1L) %% length(out)) + 1L] + 1L
      }
      out
    }
    combos$target <- spread_counts(target)
    combos$achieved <- spread_counts(achieved)
    cell_records <- lapply(seq_len(nrow(combos)), function(i) {
      list(
        sexo = combos$sexo[[i]],
        edad = combos$edad[[i]],
        target = as.integer(combos$target[[i]]),
        achieved = as.integer(combos$achieved[[i]])
      )
    })
    sex_records <- lapply(sexes, function(sex) {
      idx <- combos$sexo == sex
      list(label = sex, target = as.integer(sum(combos$target[idx])), achieved = as.integer(sum(combos$achieved[idx])))
    })
    age_records <- lapply(ages, function(age) {
      idx <- combos$edad == age
      list(label = age, target = as.integer(sum(combos$target[idx])), achieved = as.integer(sum(combos$achieved[idx])))
    })
    list(sex = sex_records, age = age_records, cells = cell_records)
  }
  block_records <- lapply(seq_len(nrow(block_rows)), function(i) {
    rec <- as.list(block_rows[i, , drop = FALSE])
    buckets <- make_quota_buckets(rec$target, rec$validas)
    rec$sex <- buckets$sex
    rec$age <- buckets$age
    rec$sex_age <- buckets$cells
    rec
  })
  district_progress <- stats::aggregate(
    block_rows[, c("target", "validas", "total")],
    by = list(distrito = block_rows$distrito),
    FUN = sum
  )
  district_progress$avance_pct <- round(100 * district_progress$validas / district_progress$target, 1)
  district_progress$brecha <- pmax(0L, district_progress$target - district_progress$validas)
  daily <- stats::aggregate(
    data.frame(
      total = rep(1L, nrow(data)),
      validas = as.integer(data$advance_valid %in% TRUE),
      stringsAsFactors = FALSE
    ),
    by = list(date_label = data$submission_date_iso),
    FUN = sum
  )
  daily <- daily[order(daily$date_label), , drop = FALSE]
  team <- stats::aggregate(
    data.frame(total = rep(1L, nrow(data)), validas = as.integer(data$advance_valid %in% TRUE)),
    by = list(responsable = data$responsable),
    FUN = sum
  )
  team$last_record <- vapply(team$responsable, function(resp) max(data$submission_date_iso[data$responsable == resp]), character(1))

  review_cases <- data[data$issues != "", , drop = FALSE]
  review_cases$reason <- ifelse(review_cases$geo_estado == "geo_no_defendible", "gps_no_defendible", ifelse(review_cases$duration_operational_status %in% c("muy_corto", "corto"), "duracion_revision", "caso_por_revisar"))
  incomplete <- block_rows[block_rows$validas < block_rows$target, , drop = FALSE]
  occurrences <- data.frame(
    fecha = c("2026-06-12", "2026-06-15"),
    hora = c("10:20", "16:35"),
    distrito = c("San Martín de Porres", "Chorrillos"),
    ump = c("UMP-201", "UMP-302"),
    manzana = c("MZ-11", "MZ-22"),
    responsable = c("Bruno Vega", "Carla Nuñez"),
    tipo_ocurrencia = c("Seguimiento de cuota", "GPS faltante"),
    severidad = c("Media", "Alta"),
    estado = c("Registrada", "Registrada"),
    descripcion = c("Se registró seguimiento operativo sobre la cuota asignada.", "Caso sin coordenada defendible para el corte."),
    accion = c("Seguimiento registrado", "Seguimiento registrado"),
    stringsAsFactors = FALSE
  )
  reports <- list(
    kpis = list(total_respuestas = nrow(data), validas = sum(data$advance_valid %in% TRUE), meta = sum(quota$target), avance_pct = round(100 * sum(data$advance_valid %in% TRUE) / sum(quota$target), 1)),
    route_overview = list(district_count = length(unique(quota$distrito)), operational_block_count = nrow(quota), block_count = nrow(quota), responsible_count = length(unique(quota$responsable))),
    advance = list(
      district_progress = district_progress,
      block_progress = block_rows,
      daily = daily,
      meta = sum(quota$target)
    ),
    district_progress = district_progress,
    block_progress = block_rows,
    team = team,
    route_blocks = block_records,
    route_quota_progress = list(blocks = block_records),
    response_audit = data,
    field_occurrences = list(rows = occurrences),
    internal_queries = list(
      review_cases = review_cases,
      far_gps = review_cases[review_cases$geo_estado %in% c("geo_revision", "geo_no_defendible"), , drop = FALSE],
      duration_review = review_cases[review_cases$duration_operational_status %in% c("muy_corto", "corto"), , drop = FALSE],
      incomplete_blocks = incomplete,
      exceeded_blocks = list(),
      cases = review_cases[seq_len(min(4L, nrow(review_cases))), , drop = FALSE],
      issues = review_cases[seq_len(min(3L, nrow(review_cases))), , drop = FALSE]
    ),
    map = list(points = data, alerts = .monitoreo_publish_qa_rec(review_cases))
  )
  config <- list(
    project_name = "QA Monitoreo Territorial",
    monitoreo_profile = list(family = "territorial"),
    territorial = list(objetivo_total = sum(quota$target), duration_min_seconds = 120, duration_max_seconds = 2700),
    fuentes = list(list(id = "qa_kobo_territorial_respuestas", role = "respuestas", label = "QA Kobo Territorial"))
  )
